# ------------------------------------------------------------------------------
# CandleStore: SQLite-backed persistent candle storage.
# ------------------------------------------------------------------------------
# Why SQLite instead of JSON files:
#   - JSON is slow: full file rewrite on every save, full file load on every
#     read, no indexing. For ~1000 candles per asset across many assets this
#     wastes I/O and risks corruption if the process is killed mid-write.
#   - SQLite is transactional, atomic, indexed by (symbol, time), and
#     supports efficient range queries ("give me all candles for symbol X
#     from time A to time B") without loading the whole table into memory.
#   - Concurrent reads + a single writer are safe out of the box.
#
# Schema:
#   candles(symbol TEXT, time INTEGER, open REAL, high REAL, low REAL,
#           close REAL, volume INTEGER, PRIMARY KEY(symbol, time))
#   gap_state(symbol TEXT PRIMARY KEY, filled INTEGER, last_fill_at REAL)
#       - 'filled' is 0/1 and tracks whether fill_gap_once has already
#         succeeded for this asset. Once it is 1, MT4Writer.fill_gap_once
#         stops touching closed candles for this asset entirely.
# ------------------------------------------------------------------------------
import sqlite3 as _sqlite3
import threading as _threading

class CandleStore:
    """Thread-safe SQLite-backed candle persistence layer.

    All public methods are safe to call from any thread. A single write
    connection (guarded by a lock) serializes writes; reads use a short-lived
    read-only connection per call.
    """
    def __init__(self, db_path: str):
        self.db_path = db_path
        self._write_lock = _threading.Lock()
        self._write_conn: Optional[_sqlite3.Connection] = None
        # Make sure parent dir exists
        try:
            parent = os.path.dirname(db_path)
            if parent:
                os.makedirs(parent, exist_ok=True)
        except Exception as e:
            pass  # silenced - non-essential diagnostic
        # Init schema on a short-lived connection
        self._init_schema()

    def _init_schema(self):
        try:
            conn = _sqlite3.connect(self.db_path, timeout=10.0, isolation_level=None)
            try:
                conn.execute("PRAGMA journal_mode=WAL;")    # crash-safe, fast writes
                conn.execute("PRAGMA synchronous=NORMAL;")  # safe + fast
                conn.execute("""
                    CREATE TABLE IF NOT EXISTS candles (
                        symbol TEXT NOT NULL,
                        time   INTEGER NOT NULL,
                        open   REAL NOT NULL,
                        high   REAL NOT NULL,
                        low    REAL NOT NULL,
                        close  REAL NOT NULL,
                        volume INTEGER NOT NULL DEFAULT 0,
                        PRIMARY KEY (symbol, time)
                    )
                """)
                conn.execute("""
                    CREATE INDEX IF NOT EXISTS idx_candles_symbol_time
                    ON candles(symbol, time)
                """)
                conn.execute("""
                    CREATE TABLE IF NOT EXISTS gap_state (
                        symbol        TEXT PRIMARY KEY,
                        filled        INTEGER NOT NULL DEFAULT 0,
                        last_fill_at  REAL NOT NULL DEFAULT 0
                    )
                """)
            finally:
                conn.close()
        except Exception as e:
            pass  # silenced - non-essential diagnostic

    # ------------------------------------------------------------------ writes
    def _get_write_conn(self) -> _sqlite3.Connection:
        if self._write_conn is None:
            self._write_conn = _sqlite3.connect(self.db_path, timeout=10.0, isolation_level=None)
            self._write_conn.execute("PRAGMA journal_mode=WAL;")
            self._write_conn.execute("PRAGMA synchronous=NORMAL;")
        return self._write_conn

    def upsert_candles(self, symbol: str, candles: list) -> int:
        """Insert-or-replace a batch of candles for the given symbol.
        Returns the number of rows written."""
        if not candles:
            return 0
        with self._write_lock:
            conn = self._get_write_conn()
            rows = 0
            try:
                conn.execute("BEGIN IMMEDIATE;")
                for c in candles:
                    conn.execute(
                        "INSERT OR REPLACE INTO candles(symbol, time, open, high, low, close, volume) "
                        "VALUES (?, ?, ?, ?, ?, ?, ?);",
                        (symbol, int(c['time']), float(c['open']), float(c['high']),
                         float(c['low']), float(c['close']), int(c.get('volume', 0)))
                    )
                    rows += 1
                conn.execute("COMMIT;")
            except Exception:
                try: conn.execute("ROLLBACK;")
                except Exception: pass
                pass  # silenced - non-essential diagnostic
                return 0
            return rows

    def append_new_candles(self, symbol: str, candles: list, after_time: int = 0) -> int:
        """Append candles whose time > after_time. Existing candles with time
        <= after_time are left untouched (frozen). Returns number of rows
        actually inserted (not the number replaced)."""
        if not candles:
            return 0
        with self._write_lock:
            conn = self._get_write_conn()
            inserted = 0
            try:
                conn.execute("BEGIN IMMEDIATE;")
                for c in candles:
                    t = int(c['time'])
                    if t <= after_time:
                        continue    # frozen - skip
                    cur = conn.execute(
                        "INSERT OR IGNORE INTO candles(symbol, time, open, high, low, close, volume) "
                        "VALUES (?, ?, ?, ?, ?, ?, ?);",
                        (symbol, t, float(c['open']), float(c['high']),
                         float(c['low']), float(c['close']), int(c.get('volume', 0)))
                    )
                    if cur.rowcount > 0:
                        inserted += 1
                conn.execute("COMMIT;")
            except Exception:
                try: conn.execute("ROLLBACK;")
                except Exception: pass
                pass  # silenced - non-essential diagnostic
                return 0
            return inserted

    def set_gap_filled(self, symbol: str, filled: bool = True, at_ts: float = None):
        if at_ts is None:
            at_ts = time.time()
        with self._write_lock:
            conn = self._get_write_conn()
            try:
                conn.execute("BEGIN IMMEDIATE;")
                conn.execute(
                    "INSERT INTO gap_state(symbol, filled, last_fill_at) VALUES (?, ?, ?) "
                    "ON CONFLICT(symbol) DO UPDATE SET filled=excluded.filled, last_fill_at=excluded.last_fill_at;",
                    (symbol, 1 if filled else 0, float(at_ts))
                )
                conn.execute("COMMIT;")
            except Exception:
                try: conn.execute("ROLLBACK;")
                except Exception: pass

    def is_gap_filled(self, symbol: str) -> Tuple[bool, float]:
        """Returns (filled, last_fill_at)."""
        try:
            conn = _sqlite3.connect(self.db_path, timeout=10.0, isolation_level=None)
            try:
                cur = conn.execute(
                    "SELECT filled, last_fill_at FROM gap_state WHERE symbol=?;",
                    (symbol,)
                )
                row = cur.fetchone()
                if row is None:
                    return (False, 0.0)
                return (bool(row[0]), float(row[1]))
            finally:
                conn.close()
        except Exception as e:
            pass  # silenced - non-essential diagnostic
            return (False, 0.0)

    # ------------------------------------------------------------------- reads
    def get_candles(self, symbol: str, limit: Optional[int] = None) -> list:
        """Return all candles for the symbol, sorted by time ascending.
        If limit is given, return only the last `limit` candles."""
        try:
            conn = _sqlite3.connect(self.db_path, timeout=10.0, isolation_level=None)
            try:
                if limit is None:
                    cur = conn.execute(
                        "SELECT time, open, high, low, close, volume FROM candles "
                        "WHERE symbol=? ORDER BY time ASC;",
                        (symbol,)
                    )
                else:
                    # Use a subselect to get the last N rows by time, then sort ascending.
                    cur = conn.execute(
                        "SELECT time, open, high, low, close, volume FROM candles "
                        "WHERE symbol=? ORDER BY time DESC LIMIT ?;",
                        (symbol, int(limit))
                    )
                    rows = cur.fetchall()
                    rows.reverse()
                    return [{
                        'time': r[0], 'open': r[1], 'high': r[2],
                        'low': r[3], 'close': r[4], 'volume': r[5]
                    } for r in rows]
                rows = cur.fetchall()
                return [{
                    'time': r[0], 'open': r[1], 'high': r[2],
                    'low': r[3], 'close': r[4], 'volume': r[5]
                } for r in rows]
            finally:
                conn.close()
        except Exception as e:
            pass  # silenced - non-essential diagnostic
            return []

    def get_max_time(self, symbol: str) -> int:
        """Return the largest candle timestamp stored for the symbol, or 0."""
        try:
            conn = _sqlite3.connect(self.db_path, timeout=10.0, isolation_level=None)
            try:
                cur = conn.execute(
                    "SELECT MAX(time) FROM candles WHERE symbol=?;",
                    (symbol,)
                )
                row = cur.fetchone()
                return int(row[0]) if row and row[0] is not None else 0
            finally:
                conn.close()
        except Exception as e:
            pass  # silenced - non-essential diagnostic
            return 0

    def count(self, symbol: str) -> int:
        try:
            conn = _sqlite3.connect(self.db_path, timeout=10.0, isolation_level=None)
            try:
                cur = conn.execute(
                    "SELECT COUNT(*) FROM candles WHERE symbol=?;",
                    (symbol,)
                )
                row = cur.fetchone()
                return int(row[0]) if row else 0
            finally:
                conn.close()
        except Exception as e:
            pass  # silenced - non-essential diagnostic
            return 0

    def clear_symbol(self, symbol: str) -> int:
        """Delete all candles + gap_state for a symbol (used by full re-fetch)."""
        with self._write_lock:
            conn = self._get_write_conn()
            try:
                conn.execute("BEGIN IMMEDIATE;")
                cur = conn.execute("DELETE FROM candles WHERE symbol=?;", (symbol,))
                deleted = cur.rowcount
                conn.execute("DELETE FROM gap_state WHERE symbol=?;", (symbol,))
                conn.execute("COMMIT;")
                return deleted
            except Exception:
                try: conn.execute("ROLLBACK;")
                except Exception: pass
                return 0


# Module-level singleton (created lazily so the path can be picked once
# after APPDATA is available at runtime).
_CANDLE_STORE: Optional[CandleStore] = None
_CANDLE_STORE_LOCK = _threading.Lock()

def get_candle_store() -> CandleStore:
    """Lazy-init the global CandleStore.

    The DB lives NEXT TO THE SCRIPT / EXE (not in APPDATA) so it is easy to
    bundle with a PyInstaller exe and easy for the user to find / back up.
    - When run as a script: candles.db is created in the script's directory.
    - When frozen with PyInstaller (one-file): candles.db is created in the
      directory the exe runs from (sys.executable's parent).
    """
    global _CANDLE_STORE
    if _CANDLE_STORE is not None:
        return _CANDLE_STORE
    with _CANDLE_STORE_LOCK:
        if _CANDLE_STORE is None:
            # Resolve the directory the script / exe lives in.
            # When frozen with PyInstaller, sys.executable points to the exe
            # and we want the DB next to it (not inside the temp _MEIPASS dir).
            if getattr(sys, 'frozen', False) and hasattr(sys, '_MEIPASS'):
                base_dir = os.path.dirname(os.path.abspath(sys.executable))
            else:
                base_dir = os.path.dirname(os.path.abspath(__file__))
            db_path = os.path.join(base_dir, 'candles.db')
            _CANDLE_STORE = CandleStore(db_path)
        return _CANDLE_STORE


# ==============================================================================
# SECTION 9.1: MT4 WRITER (uses CandleStore instead of JSON snapshots)
# ==============================================================================
class MT4Writer:
    """ MT4 .
 
 :
 - sync_state[asset] {period, candles, last_write, last_price}
 - seed_history: + HST 
 - update_candle: + HST 200ms
 - fill_gap_once: 20 + HST
 
 :
 - derived_symbol (AUDJPY-OTC) api_symbol 
 - PERIOD=1 (M1) 60 (H1) => AUDJPY-OTC1.hst
 - makedirs + retry + silent errors ( FIX 4/8)
 """
    def __init__(self):
        appdata = os.environ.get('APPDATA', '') or os.environ.get('HOME', '')
        self.mt4_history_path = os.path.join(appdata, 'MetaQuotes', 'Terminal', 'Common', 'Files', 'qx_hst')
        try:
            os.makedirs(self.mt4_history_path, exist_ok=True)
        except Exception as e:
            logmsg(f"Cannot create MT4 folder: {e}")
        # ===== FIX 10: sync_state derived_symbol ( AUDJPY-OTC) =====
        # seed_history + update_candle + fill_gap_once
        # => (AUDJPY-OTC1.hst)
        self.sync_state: Dict[str, Any] = {}
        self._writing_queue = set()
        self._gap_filled = {}
        # ===== FIX L8: =====
        # GAP_FILL_REFRESH_INTERVAL ( )
        # => .
        self._gap_filled_at: Dict[str, float] = {}
        # ---- PERSISTENT STORAGE: SQLite-backed candle store ----------------
        # CandleStore replaces the previous JSON snapshot approach. SQLite is
        # transactional, atomic, indexed by (symbol, time), and far faster than
        # writing/loading a 30 KB JSON file on every cycle. The DB lives at:
        #   %APPDATA%\MetaQuotes\Terminal\Common\Files\qx_hst_snapshots\candles.db
        # See SECTION 9 above for the CandleStore class definition.
        self._candle_store: Optional[CandleStore] = None   # lazy via get_candle_store()

    @property
    def candle_store(self) -> "CandleStore":
        """Lazy accessor so the DB connection is created after APPDATA is set."""
        if self._candle_store is None:
            self._candle_store = get_candle_store()
        return self._candle_store

    def load_snapshot(self, derived_symbol: str) -> Optional[list]:
        """Load candles for an asset from the SQLite store.
        Returns None if no candles exist (so seed_history falls back to the API).
        Also refreshes the in-memory gap_state from the DB."""
        try:
            stored = self.candle_store.get_candles(derived_symbol, limit=INITIAL_CANDLES)
            if not stored:
                return None
            # refresh in-memory gap_state from DB
            filled, last_at = self.candle_store.is_gap_filled(derived_symbol)
            self._gap_filled[derived_symbol] = filled
            self._gap_filled_at[derived_symbol] = last_at
            return stored
        except Exception as e:
            pass  # silenced - non-essential diagnostic
            return None

    def save_snapshot(self, derived_symbol: str, candles: list) -> None:
        """Persist the current candle list to the SQLite store.
        Called after seed_history + after each successful fill_gap_once."""
        try:
            self.candle_store.upsert_candles(derived_symbol, candles)
        except Exception as e:
            pass  # silenced - non-essential diagnostic

    def get_digits(self, symbol: str, price: float = 0.0) -> int:
        # FIX J: _resolve_digits ( mt4_digits.json)
        return _resolve_digits(symbol, price)

    def generate_hst_buffer(self, symbol: str, period: int, candles: list) -> bytes:
        # For sub-minute timeframes, write period=1 (M1) in the HST header
        # so MT4 opens it as a normal M1 file. The candles inside have actual
        # 5s/10s/15s/30s timestamps. For 60s+ timeframes, store the MT4 period int.
        header_period = 1 if PERIOD_SECONDS < 60 else period
        header = bytearray(148)
        struct.pack_into('<I', header, 0, 400)
        struct.pack_into('64s', header, 4, b'MetaQuotes Software Corp.'.ljust(64, b'\x00'))
        struct.pack_into('12s', header, 68, symbol[:12].encode('ascii').ljust(12, b'\x00'))
        struct.pack_into('<I', header, 80, header_period)
        first_price = candles[0]['close'] if candles else 0.0
        digits = self.get_digits(symbol, first_price)
        struct.pack_into('<I', header, 84, digits)
        struct.pack_into('<I', header, 88, 0)
        struct.pack_into('<I', header, 92, 0)
        body_size = len(candles) * 44
        buffer = bytearray(148 + body_size)
        buffer[:148] = header
        offset = 148
        for c in candles:
            struct.pack_into('<I', buffer, offset, int(c['time']))
            struct.pack_into('<d', buffer, offset + 4, float(c['open']))
            struct.pack_into('<d', buffer, offset + 12, float(c['low']))
            struct.pack_into('<d', buffer, offset + 20, float(c['high']))
            struct.pack_into('<d', buffer, offset + 28, float(c['close']))
            struct.pack_into('<Q', buffer, offset + 36, int(c.get('volume', 0)))
            offset += 44
        return bytes(buffer)

    def update_candle(self, asset: str, period: int, tick: dict):
        """ + HST 200ms ( ).

 Args:
 asset: derived_symbol ( "AUDJPY-OTC") — 
 period: MT4 timeframe (PERIOD=1 for M1) — 
 tick: {'time': int, 'price': float}
 """
        if asset not in self.sync_state:
            self.sync_state[asset] = {'period': period, 'candles': [], 'last_write': 0, 'last_price': 0.0}
        state = self.sync_state[asset]
        # ===== FIX L6: _align_time ( tz_offset + ) =====
        # —
        # seed_history fill_gap_once fetch_candles_once.
        aligned_time = _align_time(tick['time'])

        # FIX STALE-CANDLE v2: only the last candle (current/open) can be updated.
        # All candles before it are closed and must never be touched.
        if state['candles']:
            last_time = state['candles'][-1]['time']
            if aligned_time < last_time:
                # tick for a closed minute - ignore (protect closed candles)
                return
            elif aligned_time == last_time:
                last = state['candles'][-1]
                if tick['price'] == state['last_price']: return
                last['high'] = max(last['high'], tick['price'])
                last['low'] = min(last['low'], tick['price'])
                last['close'] = tick['price']
                last['volume'] += 1
            else:
                # new candle - check if there's a gap and fill it with flat candles
                period_secs = PERIOD_SECONDS if PERIOD_SECONDS > 0 else 60
                gap = (aligned_time - last_time) // period_secs
                if gap > 1:
                    # Fill gap with flat candles (use last close as price)
                    last_close = state['candles'][-1]['close']
                    fill_time = last_time + period_secs
                    while fill_time < aligned_time:
                        state['candles'].append({
                            'time': fill_time,
                            'open': last_close,
                            'high': last_close,
                            'low': last_close,
                            'close': last_close,
                            'volume': 0,
                        })
                        fill_time += period_secs
                # Now append the new candle (becomes the last)
                state['candles'].append({
                    'time': aligned_time, 'open': tick['price'], 'high': tick['price'],
                    'low': tick['price'], 'close': tick['price'], 'volume': 1,
                })
        else:
            state['candles'].append({
                'time': aligned_time, 'open': tick['price'], 'high': tick['price'],
                'low': tick['price'], 'close': tick['price'], 'volume': 1,
            })
        if len(state['candles']) > 1000:
            state['candles'] = state['candles'][-1000:]
        state['last_price'] = tick['price']
        now = time.time()
        if now - state['last_write'] > 0.2:
            self.write_to_file(asset, period, state['candles'])
            state['last_write'] = now

    def write_to_file(self, asset: str, period: int, candles: list):
        """ HST {asset}{period}.hst ( AUDJPY-OTC1.hst).

 Args:
 asset: derived_symbol ( "AUDJPY-OTC")
 period: MT4 timeframe (PERIOD=1 for M1)
"""
        # DISABLED: server no longer writes HST files (user request).
        # The web dashboard (Flask) is now the ONLY output — no disk writes.
        if not WRITE_HST_FILES_ENABLED:
            return
        if asset in self._writing_queue: return
        self._writing_queue.add(asset)
        file_name = f"{asset}{period}.hst"
        file_path = os.path.join(self.mt4_history_path, file_name)
        temp_path = file_path + '.tmp'
        # / +
        def _is_silent_error(err_str):
            err_str = err_str.lower()
            return any(x in err_str for x in [
                'winerror 2', 'winerror 5', 'winerror 32', 'winerror 13',
                'introuvable', 'refusé', 'acces refusé', 'access denied',
                'permission', 'used by another', 'ebusy', 'eperm',
                'no such file', 'not found', 'does not exist'
            ])
        # ( WinError 2)
        try:
            os.makedirs(self.mt4_history_path, exist_ok=True)
        except Exception:
            pass
        try:
            buffer = self.generate_hst_buffer(asset, period, candles)
            with open(temp_path, 'wb') as f:
                f.write(buffer)
            # retry WinError 5 + 32
            replaced = False
            for attempt in range(8):
                try:
                    os.replace(temp_path, file_path)
                    replaced = True
                    break
                except (PermissionError, OSError) as e:
                    if _is_silent_error(str(e)):
                        time.sleep(0.05 + 0.05 * attempt)
                        continue
                    raise
            if not replaced:
                # fallback —
                try:
                    with open(file_path, 'wb') as f:
                        f.write(buffer)
                    replaced = True
                except Exception as fallback_err:
                    if not _is_silent_error(str(fallback_err)):
                        logmsg(f"MT4 Write Error for {asset} (fallback): {fallback_err}")
        except OSError as e:
            if not _is_silent_error(str(e)):
                logmsg(f"MT4 Write Error for {asset}: {e}")
        except Exception as e:
            if not _is_silent_error(str(e)):
                logmsg(f"MT4 Write Error for {asset}: {e}")
        finally:
            self._writing_queue.discard(asset)
            if os.path.exists(temp_path):
                try: os.remove(temp_path)
                except Exception: pass

    async def seed_history(self, client, asset_obj, period: int, days: float = 0.75):
        """ + HST ( ).
 
 Args:
 client: Quotex
 asset_obj: Asset ( api_symbol symbol)
 period: MT4 timeframe (PERIOD=1 for M1) — get_candles PERIOD_SECONDS
 days: (default 0.75 = 18 )
 
 Returns:
 True False 
 """
        api_symbol = asset_obj.api_symbol
        derived_symbol = asset_obj.symbol

        # ---- SNAPSHOT FAST PATH ------------------------------------------------
        # If we have a previously-saved snapshot for this asset, use it directly.
        # This avoids re-fetching historical candles from the API on every restart
        # and prevents the "candles flicker / disappear and reappear" symptom
        # caused by the API returning slightly different candle data each call.
        # The streaming update_candle() path will simply append new candles as
        # they happen, and fill_gap_once() will only ADD new closed candles
        # (never replace existing ones, since the snapshot marks them as frozen).
        try:
            snap = self.load_snapshot(derived_symbol)
            if snap and len(snap) >= 2:
                snap = sorted(snap, key=lambda x: x['time'])[-INITIAL_CANDLES:]
                # populate sync_state from the snapshot
                self.sync_state[derived_symbol] = {
                    'period': period,
                    'candles': list(snap),
                    'last_write': 0,
                    'last_price': float(snap[-1]['close']) if snap else 0.0,
                }
                # write HST so MT4 picks them up immediately
                self.write_to_file(derived_symbol, period, snap)
                asset_obj.candles = list(snap)
                if snap:
                    asset_obj.price = snap[-1]['close']
                # gap is considered already filled (frozen) for the snapshot range
                self._gap_filled[derived_symbol] = True
                self._gap_filled_at[derived_symbol] = time.time()
                pass  # silenced - non-essential diagnostic
                return True
        except Exception as _se:
            pass  # silenced - non-essential diagnostic

        try:
            offset_seconds = int(days * 86400)
            # ===== FIX 10: get_candles PERIOD_SECONDS (60s ) =====
            # PERIOD (1 = M1 timeframe)
            candles = await client.get_candles(api_symbol, time.time(), offset_seconds, PERIOD_SECONDS)
            if candles and len(candles) > 0:
                # ===== FIX L7: _align_time ( tz_offset + ) =====
                # `t = int(c.get('time', ...)) + _tz_offset` —
                # => API 22:36:30 22:36:30
                # update_candle 22:36:00 => => .
                # : _align_time tz_offset + => .
                formatted = []
                for c in candles:
                    t = _align_time(int(c.get('time', c.get('timestamp', 0))))
                    o = float(c.get('open', c.get('o', 0)) or 0)
                    h = float(c.get('high', c.get('max', c.get('h', 0))) or 0)
                    l = float(c.get('low', c.get('min', c.get('l', 0))) or 0)
                    cl = float(c.get('close', c.get('c', 0)) or 0)
                    if o > 0 and h > 0 and l > 0 and cl > 0:
                        formatted.append({
                            'time': t, 'open': o, 'high': h, 'low': l, 'close': cl, 'volume': 0,
                        })
                formatted.sort(key=lambda x: x['time'])
                seen = set()
                unique_candles = [c for c in formatted if not (c['time'] in seen or seen.add(c['time']))]
                # ===== FIX 10: 1000 + =====
                unique_candles = unique_candles[-INITIAL_CANDLES:]
                # ===== FIX 10: sync_state derived_symbol ( AUDJPY-OTC) =====
                self.sync_state[derived_symbol] = {
                    'period': period, 'candles': unique_candles, 'last_write': 0, 'last_price': 0.0,
                }
                # ===== FIX 10: HST derived_symbol + period (AUDJPY-OTC1.hst) =====
                self.write_to_file(derived_symbol, period, unique_candles)
                # asset_obj.candles ( )
                asset_obj.candles = unique_candles
                if unique_candles:
                    asset_obj.price = unique_candles[-1]['close']
                self._gap_filled[derived_symbol] = False
                # ---- Save the freshly-fetched candles as the snapshot so the next
                # restart uses them as-is and never re-fetches this range. ----
                self.save_snapshot(derived_symbol, unique_candles)
                return True
            return False
        except Exception as e:
            # ( spam)
            err_str = str(e).lower()
            if not any(x in err_str for x in ['winerror', 'permission', 'access', 'closed', 'connection']):
                pass  # — main fetch loop
            return False

    async def fill_gap_once(self, client, asset_obj, period: int):
        """ GAP_FILL_CANDLES + .

 (FIX L9):
 1. _align_time tz_offset + => .
 2. GAP_FILL_REFRESH_INTERVAL => .
 3. _fill_missing_slots => .
 4. 0 (volume=0) => .

 (NEW - FREEZE AFTER FIRST SUCCESS):
 5. The original fill_gap_once algorithm is left intact. The ONLY new thing
    is a persistent freeze flag in the SQLite candle store (gap_state.filled).
    Once a successful fill has run for an asset, the flag is set to 1 and
    every subsequent call to fill_gap_once returns immediately without
    touching the candles. This preserves the candles exactly as they were
    after the first fill - no flicker, no replacement of closed candles.
    A 'full re-fetch' command can clear the flag and force a new fill.

 Args:
 client: Quotex
 asset_obj: Asset ( api_symbol symbol)
 period: MT4 timeframe (PERIOD=1 for M1)
 """
        api_symbol = asset_obj.api_symbol
        derived_symbol = asset_obj.symbol

        # 0) FREEZE CHECK: if a successful fill already happened for this asset
        # (gap_state.filled == 1 in the SQLite store), do NOT touch the candles
        # at all. This is the entire fix for the 'candles flicker' symptom -
        # the original algorithm is preserved 1:1, we only skip it after the
        # first successful run.
        try:
            is_filled, _last_at = self.candle_store.is_gap_filled(derived_symbol)
            if is_filled:
                return    # frozen - keep candles exactly as they were
        except Exception:
            pass

        # 1) skip if filled recently (within GAP_FILL_REFRESH_INTERVAL)
        now_ts = time.time()
        last_fill = self._gap_filled_at.get(derived_symbol, 0)
        already_filled = self._gap_filled.get(derived_symbol, False)
        if already_filled and (now_ts - last_fill) < GAP_FILL_REFRESH_INTERVAL:
            return

        # 2) sync_state asset_obj.candles
        if derived_symbol not in self.sync_state:
            if not asset_obj.candles:
                # try to load from store first
                snap = self.load_snapshot(derived_symbol)
                if snap:
                    asset_obj.candles = snap
                else:
                    return
            self.sync_state[derived_symbol] = {
                'period': period,
                'candles': list(asset_obj.candles),
                'last_write': 0,
                'last_price': float(asset_obj.candles[-1]['close']) if asset_obj.candles else 0.0,
            }
        state = self.sync_state[derived_symbol]
        if not state['candles']:
            return

        try:
            # Fetch last GAP_FILL_CANDLES (10) recent candles to replace incomplete ones
            small_days = (GAP_FILL_CANDLES * PERIOD_SECONDS) / 86400.0
            candles = await client.get_candles(api_symbol, time.time(), int(small_days * 86400), PERIOD_SECONDS)
            if not candles:
                # Fill existing gaps even without new data
                merged = sorted(state['candles'], key=lambda x: x['time'])[-INITIAL_CANDLES:]
                merged = _fill_missing_slots(merged, PERIOD_SECONDS, max_gap=1440)
                state['candles'] = merged
                self.write_to_file(derived_symbol, period, merged)
                asset_obj.candles = merged
                self._gap_filled[derived_symbol] = True
                self._gap_filled_at[derived_symbol] = now_ts
                self.save_snapshot(derived_symbol, merged)
                # mark as permanently filled in the DB so the next cycle skips
                self.candle_store.set_gap_filled(derived_symbol, True, now_ts)
                return

            # Build candle_map: replace incomplete closed candles with real API data
            # - Current streaming candle (time >= current_period_start): SKIP (streaming handles it)
            # - Closed candles in the fetched range: REPLACE with real data (fixes small bodies)
            # - Missing candles: ADD them
            # - Synthetic candles (volume=0): REPLACE with real data
            current_period_start = _align_time(int(time.time()))
            candle_map: Dict[int, dict] = {}
            for c in state['candles']:
                candle_map[c['time']] = c
            new_count = 0
            replaced_count = 0
            for c in candles:
                t = _align_time(int(c.get('time', c.get('timestamp', 0))))
                o = float(c.get('open', c.get('o', 0)) or 0)
                h = float(c.get('high', c.get('max', c.get('h', 0))) or 0)
                l = float(c.get('low', c.get('min', c.get('l', 0))) or 0)
                cl = float(c.get('close', c.get('c', 0)) or 0)
                v = int(c.get('volume', c.get('vol', 0)) or 0)
                if o > 0 and h > 0 and l > 0 and cl > 0:
                    existing = candle_map.get(t)
                    if existing is None:
                        # genuinely missing candle (real gap) - add it
                        candle_map[t] = {
                            'time': t, 'open': o, 'high': h, 'low': l, 'close': cl, 'volume': v,
                        }
                        new_count += 1
                    elif t >= current_period_start:
                        # current streaming candle - DON'T TOUCH (streaming handles it)
                        continue
                    else:
                        # closed candle in the fetched range - REPLACE with real data
                        # (fixes small/incomplete bodies from partial streaming)
                        candle_map[t] = {
                            'time': t, 'open': o, 'high': h, 'low': l, 'close': cl, 'volume': v,
                        }
                        replaced_count += 1

            # sort + limit to INITIAL_CANDLES
            merged = sorted(candle_map.values(), key=lambda x: x['time'])[-INITIAL_CANDLES:]
            # fill remaining gaps with flat candles (max_gap=1440 = full day)
            merged = _fill_missing_slots(merged, PERIOD_SECONDS, max_gap=1440)
            state['candles'] = merged

            # write HST
            self.write_to_file(derived_symbol, period, merged)

            # update asset_obj.candles (for live price display)
            asset_obj.candles = merged
            if merged:
                asset_obj.price = merged[-1]['close']

            # 9) mark gap as filled
            self._gap_filled[derived_symbol] = True
            self._gap_filled_at[derived_symbol] = now_ts
            # 10) persist candles to the SQLite store (so the next restart
            # loads them from the DB instead of re-fetching from the API).
            self.save_snapshot(derived_symbol, merged)
            # 11) set the permanent freeze flag - subsequent fill_gap_once
            # calls for this asset will return immediately without touching
            # the candles. This is the entire fix for the 'flicker' symptom.
            self.candle_store.set_gap_filled(derived_symbol, True, now_ts)
        except Exception as e:
            err_str = str(e).lower()
            if not any(x in err_str for x in ['winerror', 'permission', 'access', 'closed', 'connection']):
                pass

MT4_WRITER = MT4Writer()

async def mt4_gap_filler():
    global GAP_FILL_SUMMARY, GAP_FILL_ACTIVE
    # Skip entirely for subsecond mode — no gap filler for 5s/10s/15s/30s
    if IS_SUBSECOND:
        GAP_FILL_SUMMARY = "GAP FILL: disabled (subsecond mode)"
        GAP_FILL_ACTIVE = False
        return
    total = len(ALL_STREAMING_ASSETS)
    GAP_FILL_SUMMARY = f"GAP FILL: waiting 60s before starting ({total} assets)..."
    await asyncio.sleep(60)
    cycle = 0
    while True:
        cycle += 1
        if not ALL_STREAMING_ASSETS:
            GAP_FILL_SUMMARY = "GAP FILL: no assets to fill"
            GAP_FILL_ACTIVE = False
            await asyncio.sleep(GAP_FILL_REFRESH_INTERVAL)
            continue
        GAP_FILL_ACTIVE = True
        filled_count = 0
        skipped_count = 0
        failed_count = 0
        failed_assets = []
        t0 = time.time()
        for i, asset in enumerate(ALL_STREAMING_ASSETS, 1):
            if not CLIENT or not CLIENT.api:
                GAP_FILL_SUMMARY = f"GAP FILL: ABORTED (connection lost) | {filled_count}/{total} filled | {skipped_count} skipped"
                GAP_FILL_ACTIVE = False
                await asyncio.sleep(5)
                break
            try:
                await MT4_WRITER.fill_gap_once(CLIENT, asset, PERIOD)
                if MT4_WRITER._gap_filled.get(asset.symbol, False):
                    filled_count += 1
                else:
                    skipped_count += 1
                await asyncio.sleep(0.3)
            except Exception:
                skipped_count += 1
                failed_count += 1
                failed_assets.append(asset.symbol)
            # live progress update in banner
            GAP_FILL_SUMMARY = (
                f"GAP FILL c{cycle}: {i}/{total} done | {filled_count} filled | "
                f"{skipped_count} skipped | {failed_count} failed | {time.time()-t0:.1f}s"
            )
        else:
            # loop completed normally (no connection loss break)
            elapsed = time.time() - t0
            fail_str = f" | Failed: {', '.join(failed_assets[:5])}" if failed_assets else ""
            GAP_FILL_SUMMARY = (
                f"GAP FILL c{cycle}: COMPLETE in {elapsed:.1f}s | {filled_count}/{total} filled | "
                f"{skipped_count} skipped{fail_str} | next in {GAP_FILL_REFRESH_INTERVAL}s"
            )
            GAP_FILL_ACTIVE = False
            await asyncio.sleep(GAP_FILL_REFRESH_INTERVAL)
            total = len(ALL_STREAMING_ASSETS)
            continue
        # reached here only on connection loss (break)
        GAP_FILL_ACTIVE = False
        await asyncio.sleep(GAP_FILL_REFRESH_INTERVAL)
        total = len(ALL_STREAMING_ASSETS)


WEB_PUSH_INTERVAL = 30  # seconds between full candle re-push to web dashboard

async def web_candle_refresher():
    """Every 30 seconds: re-fetch full candle history for ALL streaming assets
    and push to the web dashboard so the chart always shows fresh, complete data.
    Uses the same fetch_candles_with_retry path as the initial load.
    Skips assets if connection is down (retries next cycle).
    """
    global GAP_FILL_SUMMARY
    # Wait for initial load to complete before first push
    await asyncio.sleep(35)
    cycle = 0
    while True:
        cycle += 1
        assets = list(ALL_STREAMING_ASSETS)
        total = len(assets)
        if total == 0 or not CONNECTION_ALIVE or CLIENT is None:
            GAP_FILL_SUMMARY = f"WEB PUSH c{cycle}: waiting for connection... (next in {WEB_PUSH_INTERVAL}s)"
            await asyncio.sleep(WEB_PUSH_INTERVAL)
            continue

        pushed = 0
        skipped = 0
        t0 = time.time()
        GAP_FILL_SUMMARY = f"WEB PUSH c{cycle}: refreshing {total} assets..."

        for asset in assets:
            if not CONNECTION_ALIVE or CLIENT is None:
                GAP_FILL_SUMMARY = f"WEB PUSH c{cycle}: ABORTED (connection lost) — {pushed}/{total} pushed"
                skipped = total - pushed
                break
            try:
                candles_count, _ = await fetch_candles_with_retry(
                    asset, max_retries=3, idx=pushed+1, total=total
                )
                if candles_count > 0:
                    try:
                        _web_update_asset(asset, full_resync=True)
                    except Exception:
                        pass
                    pushed += 1
                else:
                    skipped += 1
            except Exception:
                skipped += 1
            # Small delay between assets to avoid hammering the server
            await asyncio.sleep(0.2)

        elapsed = time.time() - t0
        GAP_FILL_SUMMARY = (
            f"WEB PUSH c{cycle}: {pushed}/{total} pushed ({elapsed:.1f}s) | "
            f"{skipped} skipped | next in {WEB_PUSH_INTERVAL}s"
        )
        await asyncio.sleep(WEB_PUSH_INTERVAL)

# ==============================================================================
# WEB SERVER — Live chart dashboard (ap.py style, embedded)
# Runs on http://localhost:8765  — pairs click -> live chart
# ==============================================================================
WEB_SERVER_PORT = 8765
WEB_SERVER_HOST = "127.0.0.1"
AUTO_OPEN_BROWSER = False  # v3.0.1 (أمر المالك: «تغير الشارت بشارت التطبيق») — الشارت
                           # داخل التطبيق نفسه؛ لا متصفح يُفتح وكل شيء آخر كما هو

# Shared candle store for web server (populated by realtime_stream + fetch)
_web_candle_store = {}          # pair_name -> {"candles": [...], "lastUpdate": ms, "digits": int}
_web_candle_lock = threading.RLock()
_web_push_stats = {"total_pushes": 0, "last_push_time": 0, "start_time": time.time()}

def _web_pair_name(api_symbol):
    """Convert api_symbol (e.g. AUDCAD_otc) -> display pair name (AUDCAD-OTCq)."""
    s = api_symbol.strip()
    if s.lower().endswith("_otc"):
        return s[:-4].upper() + "-OTCq"
    return s.upper()

_web_latest_tick = {}   # pair_name -> {"price": float, "time": int, "digits": int, "ts": ms}

# ==============================================================================
# ===== CHART DATA VALIDATION GATE (لا تُرسَل الشموع إلى الشارت قبل التحقق) =====
# ==============================================================================
# User report: "أرى الشموع بطريقة غريبة — اجعله لا يرسلها إلى الشارت حتى
# يتأكد أنه حمّلها". Root cause: realtime_stream pushes a full-resync to the
# web store as soon as ONE live candle closes -- BEFORE the historical fetch
# finishes. The chart then renders 1-3 sparse live candles (+ flat gap
# fillers) which look strange, and only later gets the real history.
# Fix (double gate):
#   1) SERVER: /api/candles refuses to serve a pair until its data passes
#      _validate_chart_candles() (complete history, sane OHLC, aligned stamps).
#   2) CLIENT: fetchFullCandles() re-checks sanity before chart.setData().
CHART_VALIDATE_ENABLED = True
CHART_VALIDATE_MIN_CANDLES = 50       # never serve a pair below this candle count
CHART_VALIDATE_MAX_BAD_RATIO = 0.02   # max fraction of structurally-broken candles
CHART_VALIDATE_MAX_GAP_RATIO = 0.30   # max fraction of missing periods inside the span
CHART_VALIDATE_GAP_TOLERANCE = 1800   # holes bigger than this = market closed, not gaps

def _validate_chart_candles(candles, period_seconds=None, min_count=None):
    """Verify candle data is complete and sane BEFORE it goes to the chart.

    Returns (ok, reason, cleaned):
      ok      -- True when the dataset may be rendered on the chart
      reason  -- rejection reason string (for the log / status line)
      cleaned -- sorted, de-duplicated, structurally-valid candles (when ok)
    """
    try:
        p = int(period_seconds) if period_seconds else int(PERIOD_SECONDS)
    except Exception:
        p = 60
    if not CHART_VALIDATE_ENABLED:
        return True, "disabled", list(candles or [])
    if not candles:
        return False, "empty", []
    # 1) per-candle structural sanity: positive OHLC + high/low envelope
    good, bad = [], 0
    for c in candles:
        try:
            t = int(float(c.get("time", 0)))
            o = float(c.get("open", 0)); h = float(c.get("high", 0))
            l = float(c.get("low", 0)); cl = float(c.get("close", 0))
        except Exception:
            bad += 1; continue
        if t <= 0 or o <= 0 or h <= 0 or l <= 0 or cl <= 0:
            bad += 1; continue
        # v3.0.17 (fix 4, أمر المالك): بيانات Quotex تحوي أحيانًا high أقل
        # من open/close أو low أكبر منهما بفارق طفيف — كانت الشمعة تُحذف
        # بصمت (bad += 1; continue) فتختفي من الرسم دون أثر. التصحيح بدل
        # الحذف: h = max(h, o, cl) و l = min(l, o, cl)
        h = max(h, o, cl)
        l = min(l, o, cl)
        good.append({"time": t, "open": o, "high": h, "low": l, "close": cl,
                     "volume": c.get("volume", 1)})
    if not good:
        return False, "all candles structurally invalid", []
    if bad / max(len(good) + bad, 1) > CHART_VALIDATE_MAX_BAD_RATIO:
        return False, f"too many malformed candles ({bad})", []
    # 2) sort + de-duplicate by timestamp
    good.sort(key=lambda x: x["time"])
    seen, dedup = set(), []
    for c in good:
        if c["time"] in seen:
            continue
        seen.add(c["time"])
        dedup.append(c)
    # 3) minimum candle count (a couple of live candles is NOT chart-ready)
    #    v3.0.38 (أمر المالك: الأيام تنزل حتى 0.01 يوم — «0.8 0,6 0,5 0,4 0,1
    #    0,01 اقصى شيئ»): الحد الأدنى يتكيف مع امتداد البيانات نفسها — عمق
    #    صريح صغير (0.01 يوم على 1m = 14 شمعة مثلًا) يجب أن يُعرض كاملًا ولا
    #    يرفضه حد الـ50؛ والقاعدة 50 تبقى للامتداد الطبيعي كما هي.
    mn = int(min_count) if min_count else CHART_VALIDATE_MIN_CANDLES
    try:
        if len(dedup) > 1 and p > 0:
            _imp = (dedup[-1]["time"] - dedup[0]["time"]) // p + 1
            if _imp < mn:
                mn = max(1, int(_imp * 0.8))     # تسامح شمعة/فجوة عند حدود الطلب الصغير
    except Exception:
        pass
    if len(dedup) < mn:
        return False, f"only {len(dedup)} candles (need {mn})", []
    # 4) timestamps aligned to period boundaries (98% tolerance)
    try:
        tz = _get_tz_offset()
    except Exception:
        tz = 0
    aligned = sum(1 for c in dedup if (c["time"] % p == 0) or ((c["time"] + tz) % p == 0))
    if aligned / len(dedup) < 0.98:
        return False, f"timestamps misaligned ({aligned}/{len(dedup)})", []
    # 5) gap coverage: missing periods inside the covered span. Holes larger
    #    than GAP_TOLERANCE (market closed / session break) are excluded from
    #    BOTH the expected count and the missing count.
    if p > 0:
        span = dedup[-1]["time"] - dedup[0]["time"]
        if span > 0:
            tol = max(CHART_VALIDATE_GAP_TOLERANCE, 30 * p)
            big_hole_slots = 0
            for i in range(1, len(dedup)):
                d = dedup[i]["time"] - dedup[i - 1]["time"]
                if d - p > tol:
                    big_hole_slots += (d - p) // p
            expected = span // p + 1 - big_hole_slots
            missing = expected - len(dedup)
            if expected > 0 and missing / expected > CHART_VALIDATE_MAX_GAP_RATIO:
                return False, f"too many missing candles ({missing}/{expected})", []
    return True, "ok", dedup

def _web_pair_validated(pair):
    """True when the stored entry for `pair` passed chart validation."""
    with _web_candle_lock:
        entry = _web_candle_store.get(pair)
        if entry is None:
            pl = pair.lower()
            for k, v in _web_candle_store.items():
                if k.lower() == pl:
                    entry = v
                    break
        if not entry:
            return False
        candles = entry.get("candles", [])
        flag = entry.get("validated", None)
        if flag is None:            # legacy entry without the flag: validate now
            ok, _r, _c = _validate_chart_candles(candles)
            return ok
        return bool(flag)

def _web_update_asset(asset, full_resync=False):
    """Called after every candle update -- pushes data to web candle store.

    v9.0: OPTIMIZED for max-speed live ticks.
      - Default (full_resync=False): only updates _web_latest_tick (cheap, ~1µs).
        Used by realtime_stream on every tick. Does NOT copy the full candle list.
      - full_resync=True: refreshes the full _web_candle_store[pair] entry.
        Used after initial historical fetch and on candle close (new candle started).

    v11.1 COUNTDOWN FIX (العداد التنازلي الثابت):
      Internal candle stamps carry the local TZ offset (_align_time adds it for
      the MT4/HST local-time convention). The browser countdown in BADI-CHARTS
      (drawCountdown) computes remaining = last.time + tf - Date.now()/1000,
      and Date.now() is TRUE UTC -- so TZ-shifted stamps pinned the countdown
      at a constant number (e.g. "60"/"61" on UTC+1, "06" on UTC+6) instead of
      counting down 59..00. Convert stamps back to true UTC at this web
      boundary: the chart then shows the correct local time on the axis AND a
      live per-second countdown. The MT4/HST path keeps its shifted stamps.

    v3.0.28 — قيد المحو (wipe guard): بعد حفظ عمق جديد من بطاقة الإعدادات يُمسح
      المخزن، وهذه الدالة كانت تعيد بناءه فورًا من كائن العملة القديم (بثها ما
      زال حيًّا / web_candle_refresher / كاتب MT4) فيعود الشارت القديم قبل
      اكتمال الجلب الجديد («لماذا ضغطت مازلت اراها»). الآن: كاتب يحمل رمز الجلب
      الجديد (معلَّم في _load_on_demand_asset) يُسمح له ويُرفع القيد، وأي كاتب
      آخر يُحجب حتى يصل المالك أو تنقضي مهلة الأمان — الشارت يبقى ممحوًّا مع
      دائرة التحميل مثل الوضع الافتراضي حرفيًا.
    """
    if not asset.candles:
        return
    pair = _web_pair_name(asset.api_symbol)
    if not _wipe_guard_ok(pair.lower(), getattr(asset, "_badi_wipe_tok", "")):
        return                 # قيد المحو نشط — كاتب قديم، لا عودة للشموع القديمة (v3.0.28)
    try:
        digits = asset.digits(asset.price) if asset.price else 5
    except Exception:
        digits = 5
    last_c = asset.candles[-1]
    now_ms = int(time.time() * 1000)
    try:
        tz_off = int(_get_tz_offset())
    except Exception:
        tz_off = 0

    # Always update the lightweight tick cache (fast path for /api/last-tick).
    # This is what the chart polls at 50ms — must be O(1).
    with _web_candle_lock:
        _web_latest_tick[pair] = {
            "price": float(asset.price) if asset.price else float(last_c.get("close", 0)),
            "time": int(last_c.get("time", 0)) - tz_off,
            "open": float(last_c.get("open", 0)),
            "high": float(last_c.get("high", 0)),
            "low": float(last_c.get("low", 0)),
            "close": float(last_c.get("close", 0)),
            "digits": digits,
            "ts": now_ms,
        }
        _web_push_stats["total_pushes"] += 1
        _web_push_stats["last_push_time"] = now_ms

    # Only do the heavy full-candle copy when explicitly requested.
    # realtime_stream calls _web_update_asset(asset, full_resync=True) only on
    # candle CLOSE (new candle started), not on every tick.
    if full_resync:
        # v11.1: convert shifted stamps to true UTC for the web chart (see
        # COUNTDOWN FIX note above). TZ offsets are always whole minutes, so
        # period alignment is preserved for every supported timeframe.
        candles_copy = []
        for c in asset.candles[-3000:]:
            d = dict(c)
            d["time"] = int(c.get("time", 0)) - tz_off
            candles_copy.append(d)
        # v11.0 validation gate: mark the entry chart-ready ONLY when the
        # candle set passes completeness/sanity checks. Until then /api/candles
        # keeps the chart page on the loading overlay instead of drawing
        # strange partial data.
        ok, reason, cleaned = _validate_chart_candles(candles_copy)
        with _web_candle_lock:
            _web_candle_store[pair] = {
                "pair": pair,
                "digits": digits,
                "candles": cleaned if ok else candles_copy,
                "validated": ok,
                "validateReason": None if ok else reason,
                "lastUpdate": now_ms,
            }
        if not ok:
            logmsg(f"[web:{pair}] candles NOT chart-ready yet: {reason} "
                   f"({len(candles_copy)} candles) -- holding them back from the chart")

# ==============================================================================
# v12.0 MULTI-TIMEFRAME BACKGROUND LOADER (5S / 1M / 5M)
# ==============================================================================
# User request: "عندما يتم تحميل فريم 1 دقيقة للعملة تلك نذهب الى تحميل فريم
# 5 ثواني وفريم 5 دقائق في الخلفية ... بخصوص فريم 5 ثواني نريد تحميل 1 يوم
# ... ولا تنسى يمكننا تنزيل شموع تلك على شكل ملف جيسون"
#
# Flow:
#   1) The M1 flow loads an asset exactly as before (startup or on-demand).
#   2) As soon as the M1 store entry passes chart validation, the asset is
#      enqueued for TWO background jobs:
#        - 5S: 1 full day of 5-second candles (86,400s -> ~17,280 candles)
#        - 5M: TF_5M_CANDLES 5-minute candles (default 700 ~= 2.4 days)
#      ONE background worker on ASYNC_LOOP processes them serially so the
#      broker WebSocket is never hammered by parallel history requests.
#   3) Live ticks from the asset's running stream feed in-memory per-timeframe
#      builders (same shifted-clock convention as asset.candles; _align_time).
#   4) /api/candles?tf=5S|5M, /api/last-tick?tf=..., /api/tf-status serve the
#      extra timeframes; /api/export downloads the FULL dataset as JSON file.
#   5) Candle stamps are converted back to true UTC at the web boundary
#      (same v11.1 countdown fix as _web_update_asset).
# ==============================================================================
TF_ACTIVE_SECONDS = (5, 10, 15, 30, 300, 600, 900, 1800, 3600, 14400)
                                     # v3.0.1 (أمر المالك: «تضيف الفريمات التي في
                                     # التطبيق»): 5s·5m كالأصل + فريمات شريط التطبيق
                                     # 10m·15m·30m·1H — و1m هو المقياس الأساسي نفسه
                                     # (PERIOD_SECONDS=60).
                                     # v3.0.55 (أمر المالك 2026-11-23: «ضف فريم 10
                                     # ثواني وفريم 15 ثانية وفريم 30 ثانية وفريم 4
                                     # ساعات»): فريمات الثواني 10s·15s·30s بنفس طريقة
                                     # 5s تمامًا (فرعها الخاص)، و4H بالطريقة الموحّدة
                                     # العادية مثل 1m.
TF_5S_HISTORY_DAYS = 1.0               # 5S: load 1 day (user request)   [verbatim]
TF_5S_CANDLES = 2000                   # v3.0.17 (أمر المالك: «ضع سحب شموع 5 ثواني
                                       # 2000 وليس 700 اوق»): عمق فريم 5S حرفيًا
                                       # بالشموع عبر طريقتها الخاصة (كان 700 في
                                       # v3.0.16، وقبلها أرضية 0.25 يوم = 21600s)
TF_5M_CANDLES = 700                    # 5M: same default depth as M1 (INITIAL_CANDLES)
TF_SERVE_MAX = 5000                    # /api/candles serves at most this many tf candles
TF_SERVE_HARD_MAX = 250000             # &limit= cap (v12.1: full N-day views)
TF_KEEP_MAX = {5: 40000, 10: 20000, 15: 13000, 30: 7000, 300: 3000, 14400: 3000}
                                       # engine memory caps (>= 2 days of each tf;
                                       # v3.0.55: the same >= 2-day span for the new
                                       # seconds frames, 4H like 5M)
TF_DAYS_MIN = 0.01                     # v12.1: minimum days accepted by /api/tf-load —
                                       # v3.0.38 (أمر المالك: «يمكنه ان ينزل تحت 1 يوم مثلا
                                       # 0.8 0,6 0,5 0,4 0,1 0,01 اقصى شيئ»): الحد الأدنى
                                       # 0.01 يوم بدل 0.25 — طريقة التحميل نفسها حرفيًا
TF_DAYS_DEFAULT = {5: 1.0, 10: 1.0, 15: 1.0, 30: 1.0, 300: 3.0}
                                       # v12.1: dialog default per timeframe (v3.0.55:
                                       # the seconds frames default 1 day like 5S)
TF_DAYS_LIMITS = {5: 1.0, 10: 1.0, 15: 1.0, 30: 1.0, 300: 180.0}
                                       # v12.2: dialog max per tf — 5S capped at 1 day
                                       # (user request); v3.0.55: 10s/15s/30s the same
                                       # 1-day cap (the 5S way), 4H stays on the
                                       # unified 30-day default exactly like 1M
TF_ENGINE_HARD_CAP = 250000            # v12.1: absolute builder cap per (sym, tf)
TF_REVALIDATE_INTERVAL = 300.0         # re-run the chart gate every 5 min per tf entry
_TF_BG_STATE = {}                      # api_symbol -> {"requested": bool, "5"/"300": {...}}
_TF_BG_LOCK = threading.RLock()
_TF_CANDLES = {}                       # (api_symbol, tf_sec) -> [candles, internal clock]
_TF_LAST_PRICE = {}                    # (api_symbol, tf_sec) -> last tick price
_TF_CAPS = {}                          # v12.1: (api_symbol, tf_sec) -> live-builder cap
_TF_BG_QUEUE = None                    # asyncio.Queue (created inside the worker loop)
_TF_BG_WORKER = None
_TF_BG_QUEUE_EVT = threading.Event()
_web_tf_store = {}                     # "pair|sec" -> store entry (M1 entry shape + periodSeconds)
_web_tf_tick = {}                      # "pair|sec" -> tick cache (same shape as _web_latest_tick)

def _tf_label(sec):
    """5 -> '5S', 60 -> '1M', 300 -> '5M', 3600 -> '1H'."""
    sec = int(sec)
    if sec < 60: return f"{sec}S"
    if sec % 3600 == 0: return f"{sec // 3600}H"
    return f"{sec // 60}M"

def _tf_seconds_from_label(label):
    """'5S'/'1M'/'5M'/'1H'/... -> seconds (None when unparsable)."""
    s = (label or "").strip().upper()
    if not s: return None
    try:
        if s.endswith("S"): return max(1, int(s[:-1]))
        if s.endswith("M"): return max(1, int(s[:-1])) * 60
        if s.endswith("H"): return max(1, int(s[:-1])) * 3600
        return int(s)
    except Exception:
        return None

def _tf_store_key(pair, tf_sec):
    return f"{pair}|{int(tf_sec)}"

def _wipe_guard_ok(key_lower, tok=""):
    """v3.0.28 — فحص قيد المحو (wipe guard) لكاتب مخزن الويب.

    يعيد True = الكتابة مسموحة، False = محجوبة (بيانات قديمة يجب ألا تعود).
      • لا قيد مفعّل للمفتاح → مسموح.
      • القيد مفعّل والكاتب يحمل رمزه (مالك الجلب الجديد) → مسموح والقيد يُرفع.
      • القيد مفعّل وكاتب بلا رمز (بث قديم/refresher/كاتب MT4/باني فريم) →
        محجوب حتى يصل المالك أو تنقضي مهلة الأمان _WEB_WIPE_TTL."""
    g = _WEB_WIPE.get(str(key_lower or ""))
    if not g:
        return True
    tok = str(tok or "")
    if tok and str(g.get("tok") or "") == tok:
        _WEB_WIPE.pop(str(key_lower or ""), None)
        return True
    try:
        expired = (time.time() - float(g.get("ts") or 0.0)) > float(_WEB_WIPE_TTL)
    except Exception:
        expired = True
    if expired:
        _WEB_WIPE.pop(str(key_lower or ""), None)
        return True
    return False

def _wipe_guard_start(key_lower, tok):
    """تفعيل قيد المحو على مفتاح مخزن (يُستدعى من applyHist عند الحفظ)."""
    if not key_lower or not tok:
        return
    _WEB_WIPE[str(key_lower)] = {"tok": str(tok), "ts": time.time()}

def _tf_set_state(sym, tf_sec, **kw):
    with _TF_BG_LOCK:
        st = _TF_BG_STATE.setdefault(sym, {})
        sub = st.setdefault(str(int(tf_sec)), {})
        sub.update(kw)
        return sub

def _tf_get_state(sym, tf_sec):
    with _TF_BG_LOCK:
        return dict(_TF_BG_STATE.get(sym, {}).get(str(int(tf_sec)), {}) or {})

def _tf_update_tick(api_symbol, tf_sec, ts, price):
    """Feed ONE tick into the in-memory builder (internal shifted clock).

    Returns True when a NEW candle was appended (caller should full_resync);
    False for in-place updates / late ticks / no change."""
    key = (api_symbol, int(tf_sec))
    try:
        aligned = _align_time(int(ts), int(tf_sec))
        price = float(price)
    except Exception:
        return False
    if aligned <= 0 or price <= 0:
        return False
    with _TF_BG_LOCK:
        cs = _TF_CANDLES.get(key)
        appended = False
        if cs is None:
            cs = []
            _TF_CANDLES[key] = cs
        if cs:
            last = cs[-1]
            if aligned < last["time"]:
                return False                      # late tick for a closed candle
            if aligned == last["time"]:
                if price == _TF_LAST_PRICE.get(key):
                    return False                  # unchanged price -> no push needed
                if price > last["high"]: last["high"] = price
                if price < last["low"]: last["low"] = price
                last["close"] = price
                last["volume"] += 1
            else:
                cs.append({"time": aligned, "open": price, "high": price,
                           "low": price, "close": price, "volume": 1})
                appended = True
                cap = _TF_CAPS.get(key) or TF_KEEP_MAX.get(int(tf_sec), 5000)
                if len(cs) > cap:
                    del cs[:len(cs) - cap]
        else:
            cs.append({"time": aligned, "open": price, "high": price,
                       "low": price, "close": price, "volume": 1})
            appended = True
        _TF_LAST_PRICE[key] = price
    return appended

def _web_tf_validated(pair, tf_sec):
    """True when the per-tf store entry passed chart validation."""
    with _web_candle_lock:
        entry = _web_tf_store.get(_tf_store_key(pair, tf_sec))
        if entry is None:
            pl = pair.lower()
            for k, v in _web_tf_store.items():
                if k.endswith(f"|{int(tf_sec)}") and k.split("|")[0].lower() == pl:
                    entry = v
                    break
    return bool(entry and entry.get("validated"))

def _web_update_tf(api_symbol, tf_sec, full_resync=False, days=None, wipe_tok=""):
    """Push a timeframe builder's candles into the per-tf web store.

    Same v11.1 countdown convention as _web_update_asset: internal shifted
    stamps are converted back to true UTC at this boundary, so the browser
    countdown counts down correctly for 5S/5M candles too.
    The FULL dataset is stored (for /api/export); /api/candles serves the
    newest TF_SERVE_MAX candles to keep the 500ms poll light.
    v12.1: `days` records the requested history depth on the store entry so
    the chart page can detect a depth change and refetch the full set.
    v3.0.28: `wipe_tok` — رمز قيد المحو: كاتب بلا رمز (باني فريم قديم) يُحجب
    بينما قيد المحو نشط على مخزن هذا الفريم، ومالك الجلب الجديد (الرمز معه
    من _load_tf_history) يُسمح له ويُرفع القيد عند أول كتابة له."""
    sym = (api_symbol or "").strip()
    if not sym:
        return
    tf_sec = int(tf_sec)
    pair = _web_pair_name(sym)
    key = _tf_store_key(pair, tf_sec)
    # v3.0.28: رمز الكاتب = الرمز المُمرَّر صراحةً أو رمز المالك المُسجَّل من
    # _load_tf_history لهذا (العملة، الفريم) — الكتّاب الآخرون بلا رمز يُحجبون.
    _wg_tok = str(wipe_tok or "") or str(_TF_WIPE_OWNER.get((sym, tf_sec), "") or "")
    if not _wipe_guard_ok(key.lower(), _wg_tok):
        return                 # قيد المحو نشط — لا عودة للشموع القديمة (v3.0.28)
    if _wg_tok and str(_TF_WIPE_OWNER.get((sym, tf_sec), "") or "") == _wg_tok:
        try:
            _TF_WIPE_OWNER.pop((sym, tf_sec), None)   # المالك كتب — السجل انتهى
        except Exception:
            pass
    try:
        tz_off = int(_get_tz_offset())
    except Exception:
        tz_off = 0
    now_ms = int(time.time() * 1000)
    with _TF_BG_LOCK:
        cs = _TF_CANDLES.get((sym, tf_sec))
        if not cs:
            return
        snap = list(cs)
        price = _TF_LAST_PRICE.get((sym, tf_sec)) or float(snap[-1]["close"])
    try:
        digits = _resolve_digits(sym, price)
    except Exception:
        digits = 5
    with _web_candle_lock:
        _web_tf_tick[key] = {
            "price": float(price),
            "time": int(snap[-1]["time"]) - tz_off,
            "open": float(snap[-1]["open"]), "high": float(snap[-1]["high"]),
            "low": float(snap[-1]["low"]), "close": float(snap[-1]["close"]),
            "digits": digits, "ts": now_ms,
        }
        _web_push_stats["total_pushes"] += 1
        _web_push_stats["last_push_time"] = now_ms
        if full_resync:
            entry = _web_tf_store.get(key)
            already_ok = bool(entry and entry.get("validated"))
            need_reval = (not already_ok) or (
                now_ms - (entry.get("lastValidateMs") or 0) > TF_REVALIDATE_INTERVAL * 1000)
            candles_copy = []
            for c in snap:
                d = dict(c)
                d["time"] = int(c.get("time", 0)) - tz_off
                candles_copy.append(d)
            if need_reval:
                ok, reason, cleaned = _validate_chart_candles(candles_copy, period_seconds=tf_sec)
            else:
                ok, reason, cleaned = True, "ok", candles_copy
            _web_tf_store[key] = {
                "pair": pair,
                "digits": digits,
                "candles": cleaned if ok else candles_copy,
                "validated": bool(ok),
                "validateReason": None if ok else reason,
                "lastUpdate": now_ms,
                "lastValidateMs": now_ms if need_reval else (entry.get("lastValidateMs") or 0),
                "periodSeconds": tf_sec,
                "timeframe": _tf_label(tf_sec),
                "days": days if days is not None else (entry.get("days") if entry else None),
            }
            if not ok:
                logmsg(f"[web-tf:{pair}:{_tf_label(tf_sec)}] candles NOT chart-ready: "
                       f"{reason} ({len(candles_copy)}) -- holding them back")

async def _tf_bg_worker_loop():
    """Single background worker: process TF history loads one at a time."""
    global _TF_BG_QUEUE
    _TF_BG_QUEUE = asyncio.Queue()
    _TF_BG_QUEUE_EVT.set()
    while True:
        try:
            job = await _TF_BG_QUEUE.get()
        except asyncio.CancelledError:
            raise
        if not job:
            continue
        # v12.1: jobs are (sym, tf_sec) for the default loads or
        # (sym, tf_sec, days) when the chart page asks for a specific depth.
        # v3.0.17: (sym, tf_sec, None, candles) = طريقة 5S الخاصة — عمق حرفي
        # بالشموع (2000 — أمر المالك) بلا أرضية أيام.
        # v3.0.28: (sym, tf_sec, days, candles, tok) — العنصر الخامس اختياري:
        # رمز قيد المحو (wipe token) — يُسمح بكتابة مخزن الفريم لهذا الطلب فقط
        # بينما القيد نشط (يمنع عودة الشموع القديمة بعد حفظ عمق جديد).
        sym, tf_sec = job[0], int(job[1])
        days = None
        candles = None
        _wipe_tok = ""
        if len(job) > 2:
            try:
                days = float(job[2])
            except (TypeError, ValueError):
                days = None
        if len(job) > 3:
            try:
                candles = int(job[3])
            except (TypeError, ValueError):
                candles = None
        if len(job) > 4:
            try:
                _wipe_tok = str(job[4] or "")
            except Exception:
                _wipe_tok = ""
        try:
            await _load_tf_history(sym, tf_sec, days, candles, _wipe_tok)
        except Exception as e:
            log_exception(f"tf-bg:{sym}:{_tf_label(tf_sec)}", e)
            _tf_set_state(sym, tf_sec, status="error", error=str(e))
        await asyncio.sleep(0.3)

def _ensure_tf_bg_worker():
    """Start the single TF background worker on ASYNC_LOOP (idempotent)."""
    global _TF_BG_WORKER
    if ASYNC_LOOP is None or ASYNC_LOOP.is_closed():
        return False
    w = _TF_BG_WORKER
    if w is not None and not w.done():
        return True
    try:
        _TF_BG_QUEUE_EVT.clear()
        _TF_BG_WORKER = asyncio.run_coroutine_threadsafe(_tf_bg_worker_loop(), ASYNC_LOOP)
        return _TF_BG_QUEUE_EVT.wait(3.0)
    except Exception:
        return False

def _maybe_start_tf_background(api_symbol):
    """Fire-and-forget trigger: once M1 for this asset is chart-ready, enqueue
    the default background 5S (1 day) + 5M loads for any timeframe that was
    never scheduled. Safe to call on every tick.
    v12.1: per-timeframe scheduling -- a depth requested earlier from the
    chart page (/api/tf-load) is never overwritten or duplicated here."""
    sym = (api_symbol or "").strip()
    if not sym:
        return
    if PERIOD_SECONDS != 60:
        return                      # multi-tf background is an M1-run feature
    if ASYNC_LOOP is None or ASYNC_LOOP.is_closed() or CLIENT is None:
        return
    with _TF_BG_LOCK:
        st = _TF_BG_STATE.setdefault(sym, {})
        pending = []
        for tf_sec in TF_ACTIVE_SECONDS:
            if tf_sec == PERIOD_SECONDS:
                continue
            sub = st.get(str(tf_sec))
            if not sub or not sub.get("status"):
                pending.append(tf_sec)
        if not pending:
            return                  # every tf already scheduled (defaults or web)
    if not _web_pair_validated(_web_pair_name(sym)):
        return                      # M1 not chart-ready yet
    with _TF_BG_LOCK:
        st["requested"] = True
        for tf_sec in pending:
            sub = st.setdefault(str(tf_sec), {})
            if not sub.get("status"):
                sub.update({"status": "queued", "candles": 0})
    if not _ensure_tf_bg_worker():
        with _TF_BG_LOCK:
            for tf_sec in pending:
                sub = st.get(str(tf_sec)) or {}
                if sub.get("status") == "queued":
                    sub.update({"status": "error", "error": "worker unavailable"})
        return
    for tf_sec in pending:
        try:
            _TF_BG_QUEUE.put_nowait((sym, tf_sec))
        except Exception as e:
            _tf_set_state(sym, tf_sec, status="error", error=str(e))
    logmsg(f"[tf:{sym}] M1 chart-ready -> default background load: "
           f"seconds frames 5S/10S/15S/30S ({TF_5S_CANDLES} candles each, the 5S "
           f"own method) + 1m+ frames ({TF_5M_CANDLES} candles each, unified)")

def _tf_stream_tick(api_symbol, ts, price, new_candle=False):
    """Per-tick hook from realtime_stream: feed builders + push the web store.
    Zero-cost when the asset has no background timeframes registered."""
    with _TF_BG_LOCK:
        st = _TF_BG_STATE.get(api_symbol)
        if not st or not st.get("requested"):
            return
    for tf_sec in TF_ACTIVE_SECONDS:
        if tf_sec == PERIOD_SECONDS:
            continue
        try:
            appended = _tf_update_tick(api_symbol, tf_sec, ts, price)
            _web_update_tf(api_symbol, tf_sec, full_resync=(appended or new_candle))
        except Exception:
            pass

async def _load_tf_history(api_symbol, tf_sec, days=None, candles=None, wipe_tok=""):
    """Fetch one timeframe's history in the background and seed its builder.

    v12.1: `days` (from the chart page dialog /api/tf-load) sets the history
    depth directly:
        5S: days * 86400 seconds back
        5M: days * 86400 seconds back   (default TF_5M_CANDLES candles)
    The live-builder memory cap is widened to hold the requested depth
    (bounded by TF_ENGINE_HARD_CAP).
    v3.0.17 (أمر المالك: «ضع سحب شموع 5 ثواني 2000 وليس 700» + «طريقة 5S
    لديها طريقتها الخاصة لا تغيرها»): `candles` يعطي عمق 5S حرفيًا
    بالشموع عبر طريقتها الخاصة نفسها — 1m فما فوق تبقى بمسار الأيام كما هو:
    5S: TF_5S_CANDLES (2000) via its OWN special method — the same machinery
        as fetch_subsecond_history(target_candles): secs_back = target × sec
        × 1.05, the browser-style chunked fetch (native period=5, fallback:
        1s fetch + local aggregation), then exactly the last `target` candles.
    5M: TF_5M_CANDLES candles via the same chunked fetch (period=300).
    Broker stamps are true UTC -> moved onto the internal shifted clock and
    aligned to the tf boundary, exactly like the live tick path.
    v3.0.45 (أمر المالك: «لكل الفريمات من 1 دقيقة الى 1 ساعة تكون طريقة الجلب
    نفسها … ويجب ان تجلب 700 شمعة فقط وليس 2000»): `candles` صار يخدم أيضًا
    الفريمات 1m–1h بالطلب الموحّد — نفس المعادلة حرفيًا (target×sec×1.05
    seconds back) وبنفس الجلب الموازي لفريم الدقيقة (v3.0.26) وبالقصّ النهائي
    آخر `target` شمعة بالضبط — فكل الفريمات تُطلب بالطريقة نفسها وبالعدد نفسه
    (700)، و5S بطريقتها الخاصة 2000 كما هي حرفيًا لم تُمَس.
    v3.0.28: `wipe_tok` — رمز قيد المحو المُمرَّر مع الطلب: قبل الكتابة النهائية
    في مخزن الفريم يُسجَّل كمالك مُصرَّح له، فتُطلق سران المخزن عند وصول بيانات
    هذا الطلب تحديدًا (قيد المحو يمنع كل الكتّاب القدامى قبله)."""
    sym = (api_symbol or "").strip()
    tf_sec = int(tf_sec)
    label = _tf_label(tf_sec)
    if CLIENT is None or CLIENT.api is None:
        _tf_set_state(sym, tf_sec, status="error", error="not connected")
        return
    try:
        days = float(days) if days is not None else None
    except (TypeError, ValueError):
        days = None
    try:
        candles = int(candles) if candles is not None else None
    except (TypeError, ValueError):
        candles = None
    target = None
    if candles is not None and candles > 0:
        # v3.0.17 (أمر المالك: «طريقة تحميل شموع 5 ثواني لديها طريقتها الخاصة
        # لا تغيرها» + «ضع سحب شموع 5 ثواني 2000 وليس 700 اوق»): عمق 5S حرفي
        # بالشموع بنفس معادلة الطريقة الخاصة fetch_subsecond_history حرفيًا
        # (secs_back = target × sec × 1.05) — بلا أرضية أيام: كانت تُقلَّص إلى
        # TF_DAYS_MIN=0.25 يوم = 21600s، وفي v3.0.16 كانت 700 — الآن 2000
        target = candles
        seconds_back = int(target * tf_sec * 1.05)
        days = round(seconds_back / 86400.0, 3)
    elif days is not None and days > 0:
        days = max(TF_DAYS_MIN, min(days, TF_DAYS_LIMITS.get(tf_sec, 30.0)))
        seconds_back = int(days * 86400)
        cap = min(int(seconds_back / tf_sec) + 2000, TF_ENGINE_HARD_CAP)
        with _TF_BG_LOCK:
            _TF_CAPS[(sym, tf_sec)] = cap
    elif tf_sec < 60:
        # v3.0.17: العمق الافتراضي لـ5S أيضًا بالطريقة الخاصة نفسها — 2000 شمعة
        # (كان 1 يوم ثم 700 — أمر المالك الآن: 2000)
        target = TF_5S_CANDLES
        seconds_back = int(target * tf_sec * 1.05)
        days = round(seconds_back / 86400.0, 3)
    else:
        seconds_back = int(TF_5M_CANDLES * tf_sec * 1.1)
        days = round(TF_5M_CANDLES * tf_sec / 86400, 2)
    _tf_set_state(sym, tf_sec, status="loading", seconds_back=seconds_back,
                  error=None, candles=0, days=days)
    logmsg(f"[tf:{sym}:{label}] background history fetch: {seconds_back}s "
           f"({days} day(s), {seconds_back / 86400:.2f}d)")
    raw = []
    if tf_sec >= 60:
        # v3.0.26 (أمر المالك: «طريقة تحميل فريم 5 دقائق وفريم 10 وفريم 15
        # وفريم 30 وفريم 1 ساعة يجب ان يكون مثل فريم 1 دقيقة … من المفترض
        # 4 ثواني مثل فريم 1 دقيقة»): الفريمات من 1m فما فوق تُحمَّل بطريقة
        # فريم 1 دقيقة نفسها — الجلب الموازي بـ 5 عمال (نفس دفعة
        # period×FETCH_CHUNK_SIZE ونفس الإيقاع) فيُنجز أي عمق في ثوانٍ
        # بدل العامل المسلسل الواحد. بلا اشتراك — البث الحي لا يُلمس.
        try:
            raw = await _parallel_tf_history(sym, tf_sec, seconds_back)
        except Exception as e:
            logmsg(f"[tf:{sym}:{label}] parallel (1m-method) fetch failed: {e}")
            raw = []
    if not raw:
        # المسار القديم يبقى احتياطًا كما هو حرفيًا (والفريمات دون الدقيقة
        # — 5S — تمر هنا فقط بطريقتها الخاصة كما هي، لم تُمَس إطلاقًا).
        try:
            # subscribe=False: the asset's M1 stream is already running -- a second
            # stream subscription would disturb the live feed.
            raw = await browser_style_history(sym, tf_sec, seconds_back, subscribe=False)
        except Exception as e:
            logmsg(f"[tf:{sym}:{label}] native {label} fetch failed: {e}")
            raw = []
    if not raw and tf_sec < 60:
        # Fallback: fetch 1s candles and aggregate locally (subsecond pattern).
        try:
            one_s = await browser_style_history(sym, 1, seconds_back, subscribe=False)
            raw = _aggregate_sub_minute(one_s, tf_sec) if one_s else []
        except Exception as e:
            logmsg(f"[tf:{sym}:{label}] 1s fallback failed: {e}")
            raw = []
    if not raw:
        _tf_set_state(sym, tf_sec, status="error", error="no history returned")
        logmsg(f"[tf:{sym}:{label}] no history returned (market closed or fetch failed)")
        return
    for c in raw:
        try:
            c["time"] = _align_time(int(c["time"]), tf_sec)
        except Exception:
            pass
    raw.sort(key=lambda x: x["time"])
    seen, dedup = set(), []
    for c in raw:
        if c["time"] in seen:
            continue
        seen.add(c["time"])
        dedup.append(c)
    # v3.0.17: عقد الطريقة الخاصة (fetch_subsecond_history): آخر target شمعة
    # بالضبط — 5S تصل بعمقها الحرفي (2000)، والفريمات الأخرى target=None
    # فلا قصّ عليها (سلوكها كما هو حرفيًا)
    if target is not None and len(dedup) > target:
        dedup = dedup[-target:]
    # Merge with any live candles the builder collected while fetching
    # (live data wins on the same timestamp).
    key = (sym, tf_sec)
    with _TF_BG_LOCK:
        live = list(_TF_CANDLES.get(key, []))
        by_time = {c["time"]: c for c in dedup}
        by_time.update({c["time"]: c for c in live})
        merged = [by_time[t] for t in sorted(by_time)]
        cap = _TF_CAPS.get(key) or TF_KEEP_MAX.get(tf_sec, 5000)
        if len(merged) > cap:
            merged = merged[-cap:]
        _TF_CANDLES[key] = merged
    # v3.0.28: هذا الطلب هو مالك كتابة مخزن الفريم إن كان قيد المحو نشطًا له
    # (الرمز يصل مع الطلب من _request_tf) — الكتابة التالية (_web_update_tf
    # أسفل مباشرة) تُطلق سران المخزن وتُنهي قيد المحو لهذا الفريم فقط.
    try:
        if str(wipe_tok or ""):
            _TF_WIPE_OWNER[(sym, tf_sec)] = str(wipe_tok)
    except Exception:
        pass
    _web_update_tf(sym, tf_sec, full_resync=True, days=days)
    n = len(merged)
    ok = _web_tf_validated(_web_pair_name(sym), tf_sec)
    _tf_set_state(sym, tf_sec, status=("ready" if ok else "loading"),
                  candles=n, days=days, error=None)
    logmsg(f"[tf:{sym}:{label}] done: {n} candles ({days} day(s)) "
           f"({'ready' if ok else 'verification-pending'})")

# == ON-DEMAND ASSETS (web dashboard click-to-load) ============================
# When the user clicks an asset in the dashboard that is NOT part of the
# startup ASSET_LIST, it is loaded EXACTLY like the default asset:
#   1) live stream first (realtime_stream / subsecond_stream)
#   2) M1: 1s -> 1m bridge fetch (same as the default asset flow)
#   3) historical fetch with retry (fetch_candles_with_retry)
#   4) REPLACE/APPEND merge of the newest bridge candles (same as main loop)
#   5) full web resync -> the chart page picks the data up automatically
# All on-demand loads are serialized through ONE asyncio worker so the broker's
# WebSocket is never hammered by parallel history requests.
_on_demand_state = {}      # api_symbol -> {"status","started","last_requested","error","asset","candles"}
_on_demand_lock = threading.RLock()
_ON_DEMAND_MAX = 30        # hard cap of tracked on-demand assets per session
_on_demand_queue = None    # asyncio.Queue (created inside the worker loop)
_on_demand_worker = None   # concurrent.futures.Future handle
_on_demand_queue_evt = threading.Event()

_web_assets_cache = {"entries": [], "fetched_at": 0.0, "last_attempt": 0.0}
_web_assets_lock = threading.RLock()

def _pair_name_to_api(pair_name):
    """Reverse of _web_pair_name: 'USDDZD-OTCq' -> 'USDDZD_otc'."""
    s = (pair_name or "").strip()
    if s.endswith("-OTCq"):
        return s[:-5] + "_otc"
    if s.endswith("-OTC"):
        return s[:-4] + "_otc"
    return s

def _od_set_state(sym, **kw):
    with _on_demand_lock:
        st = _on_demand_state.setdefault(sym, {})
        st.update(kw)
        return st

async def _on_demand_worker_loop():
    """Single worker: process on-demand asset loads one at a time."""
    global _on_demand_queue
    _on_demand_queue = asyncio.Queue()
    _on_demand_queue_evt.set()
    while True:
        try:
            sym = await _on_demand_queue.get()
        except asyncio.CancelledError:
            raise
        if not sym:
            continue
        try:
            await _load_on_demand_asset(sym)
        except Exception as e:
            log_exception("_on_demand_worker", e)
            _od_set_state(sym, status="error", error=str(e))
        await asyncio.sleep(0.3)

async def _on_demand_enqueue(sym):
    await _on_demand_queue.put(sym)

def _ensure_on_demand_worker():
    """Start the single on-demand worker on ASYNC_LOOP (idempotent)."""
    global _on_demand_worker
    if ASYNC_LOOP is None or ASYNC_LOOP.is_closed():
        return False
    w = _on_demand_worker
    if w is not None and not w.done():
        return True
    try:
        _on_demand_queue_evt.clear()
        _on_demand_worker = asyncio.run_coroutine_threadsafe(_on_demand_worker_loop(), ASYNC_LOOP)
        return _on_demand_queue_evt.wait(3.0)
    except Exception:
        return False

def _request_on_demand_asset(api_symbol):
    """Called from Flask threads: queue an asset for the same-as-default load."""
    sym = (api_symbol or "").strip()
    if not sym:
        return {"status": "ERROR", "error": "empty asset code"}
    if ASYNC_LOOP is None or ASYNC_LOOP.is_closed():
        return {"status": "ERROR", "error": "engine not ready (not connected yet)"}
    with _on_demand_lock:
        st = _on_demand_state.get(sym)
        if st is not None and st.get("status") in ("queued", "loading"):
            st["last_requested"] = time.time()
            return {"status": st.get("status"), "asset": sym}
        if sym not in _on_demand_state and len(_on_demand_state) >= _ON_DEMAND_MAX:
            return {"status": "ERROR",
                    "error": f"on-demand cache full ({_ON_DEMAND_MAX} assets) -- restart the bot to clear"}
        _od_set_state(sym, status="queued", started=time.time(),
                      last_requested=time.time(), error=None, asset=None, candles=0)
    if not _ensure_on_demand_worker():
        _od_set_state(sym, status="error", error="engine not ready")
        return {"status": "ERROR", "error": "engine not ready (event loop unavailable)"}
    try:
        asyncio.run_coroutine_threadsafe(_on_demand_enqueue(sym), ASYNC_LOOP).result(timeout=5)
    except Exception as e:
        _od_set_state(sym, status="error", error=str(e))
        return {"status": "ERROR", "error": str(e)}
    return {"status": "queued", "asset": sym}

async def _load_on_demand_asset(api_symbol):
    """Load ONE asset exactly like the default asset (same fetch machinery)."""
    sym = (api_symbol or "").strip()
    _od_set_state(sym, status="loading", started=time.time(), error=None)
    logmsg(f"[on-demand:{sym}] loading candles (same engine as default asset)")
    asset = Asset(sym)
    # v3.0.28 — قيد المحو: إن كان هناك حفظ عمق جديد معلّق لهذه العملة (رمز
    # wipe_token في حالة on-demand) فهذا الكائن هو مالك الجلب الجديد — يُسمح
    # لكتابته في مخزن الويب وتُرفع القيد عند أول كتابة له، وكل الكتّاب القدامى
    # (بث العملة القديم / refresher / كاتب MT4) يبقون محجوبين حتى ذلك الحين.
    # الرمز يبقى في الحالة (لا يُستهلك) — أي إعادة محاولة للجلب تحمل الرمز
    # نفسه فتفتح القيد بأول بيانات صحيحة ولو بعد فشل أول محاولة.
    try:
        _st = _on_demand_state.get(sym) or {}
        _wtok = str(_st.get("wipe_token", "") or "")
        if _wtok:
            try:
                asset._badi_wipe_tok = _wtok
            except Exception:
                pass
    except Exception:
        pass
    _od_set_state(sym, asset=asset)
    ALL_STREAMING_ASSETS.append(asset)
    try:
        if IS_SUBSECOND:
            # Same dispatch as the main loop: subsecond_stream schedules its own
            # background history fetch (fetch_subsecond_history).
            asset.stream_task = asyncio.ensure_future(subsecond_stream(asset))
            deadline = time.time() + float(_subsecond_fetch_timeout()) + 5.0
            while time.time() < deadline:
                bg = getattr(asset, "_bg_tasks", None)
                if bg is not None and len(bg) == 0:
                    break
                if len(getattr(asset, "candles", [])) >= SUBSECOND_HISTORY_CANDLES:
                    break
                if not CONNECTION_ALIVE:
                    break
                await asyncio.sleep(0.5)
        else:
            # 1) live stream FIRST (same order as the default asset)
            asset.stream_task = asyncio.ensure_future(realtime_stream(asset))
            await asyncio.sleep(0.1)
            # 2) M1: 1s -> 1m bridge (same as default asset flow)
            _is_m1_bridge = (PERIOD_SECONDS == 60 and M1_USE_1S_BRIDGE and not M1_TEST_1S_ONLY)
            bridge_1m_candles, n_1s = [], 0
            # 3) historical fetch with retry (same as default asset). In M1
            #    bridge mode the internal recent-candle bridge is disabled,
            #    exactly like the main loop does.
            # v11.0: run bridge + historical in PARALLEL (default) -- same
            # speedup as the startup loop (~8s -> ~4s).
            _saved_bridge = BRIDGE_FETCH_ENABLED
            _need_seq_hist = True
            if _is_m1_bridge and M1_PARALLEL_FETCH:
                # v3.0.42 (أمر المالك: «يجب ان يكون كل شيئ سريع»): دفع مبكر —
                # الشموع التاريخية تُدفع للشارت لحظة وصولها ولا انتظار لجسر 1s
                # حتى مهلته M1_BRIDGE_TIMEOUT=30 ثانية، والجسر يندمج لاحقًا في
                # خطوة الدمج نفسها أدناه مع الدفع الثاني (_web_update_asset).
                def _push_od_hist_now():
                    try:
                        if asset.candles:
                            if not asset.price:
                                asset.price = asset.candles[-1]["close"]
                            _web_update_asset(asset, full_resync=True)
                            logmsg(f"[on-demand:{sym}] early push: "
                                   f"{len(asset.candles)} candles on chart (1s bridge still running)")
                    except Exception:
                        pass
                try:
                    bridge_1m_candles, n_1s, _cnt, _att = await _m1_bridge_and_history_parallel(
                        asset, idx=1, total=1, on_hist=_push_od_hist_now)
                    logmsg(f"[on-demand:{sym}] parallel load: {n_1s} 1s -> "
                           f"{len(bridge_1m_candles)} 1m bridge + {_cnt} historical")
                    _need_seq_hist = False
                except Exception as e:
                    logmsg(f"[on-demand:{sym}] parallel load failed -> sequential fallback: {e}")
                    bridge_1m_candles, n_1s = [], 0
            if _need_seq_hist:
                if _is_m1_bridge:
                    try:
                        bridge_1m_candles, n_1s = await fetch_1s_and_aggregate_to_1m(asset, idx=1, total=1)
                    except Exception as e:
                        logmsg(f"[on-demand:{sym}] 1s->1m bridge failed (non-fatal): {e}")
                        bridge_1m_candles = []
                if _is_m1_bridge:
                    globals()["BRIDGE_FETCH_ENABLED"] = False
                try:
                    await fetch_candles_with_retry(asset, max_retries=MAX_FETCH_RETRIES, idx=1, total=1)
                finally:
                    if _is_m1_bridge:
                        globals()["BRIDGE_FETCH_ENABLED"] = _saved_bridge
            # 4) REPLACE/APPEND merge of the newest bridge candles (main-loop logic)
            if bridge_1m_candles and asset.candles:
                bridge_for_merge = bridge_1m_candles[-M1_BRIDGE_REPLACE_COUNT:]
                bridge_by_time = {c["time"]: c for c in bridge_for_merge}
                merged_list = []
                for c in asset.candles:
                    if c["time"] in bridge_by_time:
                        merged_list.append(bridge_by_time.pop(c["time"]))
                    else:
                        merged_list.append(c)
                merged_list.extend(bridge_by_time.values())
                seen, deduped = set(), []
                for c in sorted(merged_list, key=lambda x: x["time"]):
                    if c["time"] not in seen:
                        seen.add(c["time"])
                        deduped.append(c)
                asset.candles = deduped
                logmsg(f"[on-demand:{sym}] merged 1s->1m bridge: {len(bridge_for_merge)} candles (from {n_1s} 1s)")
        if asset.candles:
            asset.price = asset.candles[-1]["close"]
        # 5) full web resync -- the chart page polls /api/candles
        _web_update_asset(asset, full_resync=True)
        n = len(asset.candles)
        # v11.0: "ready" ONLY when the stored candles passed chart validation.
        # If validation failed the chart would otherwise draw the strange
        # partial dataset -- the page stays on the overlay and gets a clear
        # error instead.
        _chart_ok = _web_pair_validated(_web_pair_name(sym))
        if n > 0 and _chart_ok:
            _od_set_state(sym, status="ready", candles=n, error=None)
        elif n > 0:
            _reason = None
            with _web_candle_lock:
                _entry = _web_candle_store.get(_web_pair_name(sym)) or {}
                _reason = _entry.get("validateReason")
            _err = f"candles failed chart verification: {_reason or 'unknown'}"
            _od_set_state(sym, status="error", candles=n, error=_err)
            logmsg(f"[on-demand:{sym}] NOT chart-ready: {_err}")
        else:
            _od_set_state(sym, status="error", candles=0,
                          error="no candles returned (market closed or fetch failed)")
        logmsg(f"[on-demand:{sym}] done: {n} candles "
               f"({'ready' if (n > 0 and _chart_ok) else ('error' if n == 0 else 'verification-failed')})")
    except Exception as e:
        log_exception(f"_load_on_demand_asset:{sym}", e)
        _od_set_state(sym, status="error", error=str(e),
                      candles=len(getattr(asset, "candles", [])))

