# ---------------------------------------------------------------- Python helpers for indicators
def _sma(v, p):
    out, s = [None] * len(v), 0.0
    for i, x in enumerate(v):
        s += x
        if i >= p:
            s -= v[i - p]
        if i >= p - 1:
            out[i] = s / p
    return out


def _ema(v, p):
    out, k = [None] * len(v), 2.0 / (p + 1)
    prev = None
    for i, x in enumerate(v):
        prev = x if prev is None else x * k + prev * (1 - k)
        out[i] = prev if i >= p - 1 else None
    return out


def _rsi(v, p):
    out = [None] * len(v)
    if len(v) <= p:
        return out
    g, l = 0.0, 0.0
    for i in range(1, p + 1):
        d = v[i] - v[i - 1]
        g += max(d, 0)
        l += max(-d, 0)
    ag, al = g / p, l / p
    out[p] = 100.0 - 100.0 / (1 + ag / al) if al else 100.0
    for i in range(p + 1, len(v)):
        d = v[i] - v[i - 1]
        ag = (ag * (p - 1) + max(d, 0)) / p
        al = (al * (p - 1) + max(-d, 0)) / p
        out[i] = 100.0 - 100.0 / (1 + ag / al) if al else 100.0
    return out


# ───── v3.0.28: مساعدات مؤشرات بايثون الجديدة (داخل الصندوق المغلق) ─────
# أمر المالك: «ضع للمؤشرات يمكنها طلب شموع عملات اخرى لكي تعمل بها … اقصى عدد
# 200 شمعة لكل عملة … ويتم جلبهم بالتسلسل» + «وضع لهم كود صغير لكي عندما يشغله
# الكود كمؤشر يطبع له قائمة العملات في الكونسول» — log() هي التي تطبع في كونسول
# المحرر (نفس log() في مؤشرات جافاسكربت) وrequest_candles() تطلب شموع عملة
# أخرى بنفس طريقة التطبيق حرفيًا حسب الفريم. الصندوق يبقى مغلقًا: لا import
# ولا ملفات ولا شبكة — هاتان الدالتان فقط عبر وسيط التطبيق نفسه.
_PY_IND_DATA_HOOK = None     # يُضبط من Backend: (symbol, count, tf) → شموع أو None
_PY_LOG_SINK = None          # يُضبط من Backend: (text) → كونسول المحرر


def _py_log(*args):
    """log() داخل مؤشر بايثون — يطبع في كونسول المحرر."""
    try:
        msg = " ".join("" if a is None else str(a) for a in args)
    except Exception:
        msg = ""
    msg = msg.strip()
    if not msg:
        return
    sink = _PY_LOG_SINK
    if sink:
        try:
            sink(msg[:500])
        except Exception:
            pass


def _py_request_candles(symbol, count=200, tf=None, days=None):
    """request_candles(symbol, count, tf, days=None) داخل مؤشر بايثون — شموع
    عملة أخرى بنفس طريقة التطبيق حرفيًا حسب الفريم (on-demand نفسه / مخزن
    الدقيقة نفسه / نفس طابور الفريمات ونفس طريقة 5S الخاصة). تُجلب بالتسلسل
    — طلب واحد نشط ثم الذي بعده — count بحد 200 شمعة لكل عملة.
      symbol : كود النظام كما هو («USDDZD_otc» — ليس اسم الواجهة «USD/DZD OTC»)
      count  : عدد الشموع (1..200)
      tf     : '5s'|'10s'|'15s'|'30s'|'1m'|'5m'|'10m'|'15m'|'30m'|'1H'|'4H' — الافتراضي فريم الشارت
      days   : v3.0.38 (أمر المالك: «المؤشر يستطيع طلب الشموع») — عمق بالأيام
               الكسرية 0.01..30 مثل عدّاد بطاقة الإعدادات حرفيًا: الشموع تُحسب
               من الأيام حسب الفريم (0.5 يوم على 1m = 720 شمعة) بحد 43,000،
               وتُقبل الفاصلة العادية والعربية، وdays تُسبق count إذا كُتبت معًا.
    تعيد None وهي قيد الجلب — calculate() يُعاد نداؤه تلقائيًا كل ثانية فتحصل
    على النتيجة في نداء لاحق — وعند التجهيز: [{t,o,h,l,c,v}, ...] (أحدث شمعة
    أخيرًا)، أو None إن كان الكود غير معروف (شغّل مثال قائمة العملات في الدليل)."""
    hook = _PY_IND_DATA_HOOK
    if hook is None:
        return None
    try:
        return hook(str(symbol), int(count), tf, days)
    except Exception:
        return None


