# ═══════════════════════════════════════════════════════════════════════════════
# قرار المالك الحرفي (2026-11-18): «انزع السرفر كليا من الكود» — لا بوابات ولا أعلام
# تعطيل: كل كود السرفر حُذف من الملف حرفيًا (الأرشيف الكامل في QX_server_archive.py).
# الثوابت أعلاه وقوائم العملات والأعلام وساعة السوق تبقى كما هي لسهولة الربط لاحقًا.
# ═══════════════════════════════════════════════════════════════════════════════


# ── ساعة السوق المحلية (بلا شبكة): مفتوح/مغلق لكل عملة + الجلسة الحالية + الوقت للتغيير ──
# نفس قواعد الصفحة حرفيًا (badiMarketOpen): OTC والكريبتو مفتوح دائمًا، والفوركس
# من الأحد 22:00 إلى الجمعة 22:00 UTC — والمعادن تتبع ساعات الفوركس.
_MARKET_CRYPTO = ("BTC", "ETH", "XRP", "LTC", "BCH", "SOL", "ADA", "DOGE", "TRX", "TON")
_MARKET_METALS = ("XAU", "XAG", "XPT", "XPD")


def _market_class(name: str) -> str:
    """تصنيف العملة من الاسم فقط بلا أي شبكة: otc | crypto | metal | fx."""
    n = str(name or "").upper()
    if "OTC" in n or n.endswith("_OTC"):
        return "otc"
    for _c in _MARKET_CRYPTO:
        if _c in n:
            return "crypto"
    for _m in _MARKET_METALS:
        if _m in n:
            return "metal"
    return "fx"


def _fx_session_name(now):
    """الجلسة الفعالة الآن بالـ UTC: سيدني/طوكيو/لندن/نيويورك (الأولى الفعالة تُعاد)."""
    h = now.hour + now.minute / 60.0
    for _nm, _a, _b in (("سيدني", 21, 6), ("طوكيو", 0, 9), ("لندن", 7, 16), ("نيويورك", 12, 21)):
        if ((h >= _a or h < _b) if _a > _b else (_a <= h < _b)):
            return _nm
    return ""


def _next_weekday_utc(now, weekday, hour):
    """أقرب لحظة قادمة ليوم أسبوعي وساعة محددين بالـ UTC (weekday: 0=الاثنين … 6=الأحد)."""
    ahead = (weekday - now.weekday()) % 7
    if ahead == 0 and (now.hour, now.minute, now.second, now.microsecond) >= (hour, 0, 0, 0):
        ahead = 7
    return (now + timedelta(days=ahead)).replace(hour=hour, minute=0, second=0, microsecond=0)


def market_status(name, now=None):
    """حالة السوق الكاملة لعملة واحدة — من ساعة السوق المحلية بلا أي اتصال:
    {name, open, label, session, next_in} — label بالعربية («مفتوح»/«مغلق») على
    لسان طلب المالك، وnext_in = {verb, secs} حتى التغيير القادم (None = مفتوح دائمًا)."""
    now = now or datetime.now(timezone.utc)
    cls = _market_class(name)
    if cls in ("otc", "crypto"):
        return {"name": name, "open": True, "label": "مفتوح",
                "session": "OTC" if cls == "otc" else "24/7", "next_in": None}
    js_day = (now.weekday() + 1) % 7                 # الأحد=0 … السبت=6 — نفس getUTCDay في الصفحة
    hour = now.hour + now.minute / 60.0
    open_ = not (js_day == 6 or (js_day == 5 and hour >= 22) or (js_day == 0 and hour < 22))
    if open_:
        nxt = _next_weekday_utc(now, 4, 22)          # الإغلاق الأسبوعي: الجمعة 22:00 UTC
        label, verb, session = "مفتوح", "يغلق", _fx_session_name(now)
    else:
        nxt = _next_weekday_utc(now, 6, 22)          # الافتتاح الأسبوعي: الأحد 22:00 UTC
        label, verb, session = "مغلق", "يفتح", ""
    return {"name": name, "open": open_, "label": label, "session": session,
            "next_in": {"verb": verb, "secs": max(0, int((nxt - now).total_seconds()))}}


# ── مساعدو الواجهة (من HTML المالك): الأعلام واللوحة والأرقام — عرض فقط، ليست بروتوكول ──
# الأرقام العشرية — نفس قواعد السرفر (_resolve_digits، بلا ملف mt4)
# ==============================================================================
def qx_digits(symbol: str, price: float = 0.0) -> int:
    sym_upper = str(symbol or "").upper()
    if "JPY" in sym_upper: return 3
    if price and price > 0:
        if price < 0.5:  return 6
        if price < 1:    return 5
        if price < 5:    return 5
        if price < 10:   return 4
        if price < 50:   return 4
        if price < 100:  return 3
        return 3
    if any(x in sym_upper for x in ["IDR", "COP", "ARS", "NGN", "PKR", "DZD", "EGP", "MXN", "PHP", "INR", "BDT", "ZAR", "BRL"]):
        return 3
    return 5

