# رمزيات الرقمية المحلية: قرص بلون العلامة + الحرف الأول (تُرسَم دومًا بلا شبكة)
_QX_COIN_LOCAL = {
    'LTC': ('#345d9d', 'L'), 'XRP': ('#23292f', 'X'), 'SOL': ('#9945ff', 'S'),
    'DOT': ('#e6007a', 'D'), 'BNB': ('#f3ba2f', 'B'), 'BCH': ('#8dc351', 'B'),
    'ETC': ('#328332', 'E'), 'DAS': ('#008ce7', 'D'), 'ZEC': ('#f4b728', 'Z'),
    'TON': ('#0098ea', 'T'), 'LIN': ('#2a5ada', 'L'), 'AXS': ('#00501e', 'A'),
    'ATU': ('#2e3148', 'A'), 'AVA': ('#e84142', 'A'), 'TRU': ('#1c60ff', 'T'),
}


def _flag_body_uri(body):
    """يغلف جسم علم 20x14 بالإطار الرمادي داخل SVG كامل → data-URI محلي 100%."""
    svg = ('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 14">' + body + _RIM_GRAY + '</svg>')
    return "data:image/svg+xml;utf8," + urllib.parse.quote(svg)


def _qx_coin_uri(sym):
    """رمزية رقمية محلية: قرص بلون العلامة + الحرف الأول."""
    c, letter = _QX_COIN_LOCAL[sym]
    svg = ('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 14">'
           f'<circle cx="10" cy="7" r="6.4" fill="{c}"/>'
           f'<text x="10" y="10.4" font-size="9" font-weight="bold" text-anchor="middle" '
           f'fill="#fff" font-family="Arial,sans-serif">{letter}</text></svg>')
    return "data:image/svg+xml;utf8," + urllib.parse.quote(svg)


def qx_flag_body(iso):
    """جسم علم محلي (viewBox 20x14) لكود دولة: الأعلام المبسطة المخصصة أولًا (رسمها
    الأغنى — كالجزائر بهلالها) ثم أجسام FLAGS (القاموسان منفصلان ما عدا إضافات
    قائمة الشريط الجديدة كـ DZD، فالأولوية المقلوبة لا تغير أي علم سابق)."""
    iso = str(iso or "").lower()
    body = _QX_LOCAL_STRIP.get(iso, "")
    if body:
        return body
    ccy = _QX_CC_INV.get(iso)
    if ccy and ccy in FLAGS:
        return FLAGS[ccy]
    return ""


def qx_local_flags(code, name=""):
    """علمان محليان (data-URI SVG) لأي كود أصل — يرسمان دومًا بلا أي طلب شبكة.
    يُعاد ("","") فقط عند رموز السلع/المؤشرات الخاصة أو الرموز المجهولة —
    عندها تُجرَّب مسارات القِدم (السلع المحلية ثم الاحتياطات البعيدة) بلا حذف."""
    clean = str(code or "")
    if clean.lower().endswith("_otc"):
        clean = clean[:-4]
    if clean in _QX_SPECIAL_SVG:      # الذهب/الفضة/النفط/المؤشرات: رسومها المحلية الأصلية أفضل
        return ("", "")
    base = clean.upper()
    if base in _QX_CRYPTO_ICON:       # الرقمية: BTC وETH بأجسام FLAGS الأصلية والبقية أقراص محلية
        if base == "BTCUSD" and "BTC" in FLAGS:
            return (_flag_body_uri(FLAGS["BTC"]), "")
        if base == "ETHUSD" and "ETH" in FLAGS:
            return (_flag_body_uri(FLAGS["ETH"]), "")
        if base[:3] in _QX_COIN_LOCAL:
            return (_qx_coin_uri(base[:3]), "")
        return ("", "")
    if len(clean) >= 6 and clean.isalpha():     # زوج عملات: علم الأساسي + علم الثانوي
        i1 = _QX_CC.get(clean[:3].upper())
        i2 = _QX_CC.get(clean[3:6].upper())
        b1 = qx_flag_body(i1) if i1 else ""
        b2 = qx_flag_body(i2) if i2 else ""
        if b1 and b2:
            return (_flag_body_uri(b1), _flag_body_uri(b2))
        if b1:
            return (_flag_body_uri(b1), "")
        if b2:
            return (_flag_body_uri(b2), "")
        return ("", "")
    if len(clean) == 3 and clean.isalpha():     # عملة مفردة
        b1 = qx_flag_body(_QX_CC.get(clean.upper()))
        if b1:
            return (_flag_body_uri(b1), "")
    return ("", "")


def _qx_svg_uri(svg):
    return "data:image/svg+xml;utf8," + urllib.parse.quote(svg)


def qx_asset_flags(code, name=""):
    """علمان العملة (الأساسي + الثانوي) أو أيقونتها الخاصة — نفس منطق ملف HTML."""
    clean = str(code or "")
    if clean.lower().endswith("_otc"):
        clean = clean[:-4]
    local1, local2 = qx_local_flags(clean)   # قرار المالك: علم محلي يُرسَم دائمًا — لا شبكة
    if local1:
        return (local1, local2)
    icon = _QX_CRYPTO_ICON.get(clean)
    if icon:
        return (_QX_CRYPTO_BASE + icon + ".png", "")
    special = _QX_SPECIAL_SVG.get(clean)
    if special:
        return (_qx_svg_uri(special), "")
    if len(clean) >= 6 and clean.isalpha():
        c1 = _QX_CC.get(clean[:3].upper())
        c2 = _QX_CC.get(clean[3:6].upper())
        if c1 and c2:
            return (_QX_FLAG_BASE + c1 + ".png", _QX_FLAG_BASE + c2 + ".png")
        if c1:
            return (_QX_FLAG_BASE + c1 + ".png", "")
        if c2:
            return (_QX_FLAG_BASE + c2 + ".png", "")
    return (_qx_svg_uri(_QX_UNKNOWN_SVG), "")


_QX_SPECIAL_SVG = {
    'XAUUSD': _QX_GOLD_SVG, 'XAGUSD': _QX_SILVER_SVG,
    'UKBrent': _QX_BRENT_SVG, 'USCrude': _QX_WTI_SVG,
}
_QX_SPECIAL_SVG.update(_QX_INDEX_SVGS)


def qx_build_board(instruments):
    """قائمة الأصول الكاملة من صفوف instruments — نفس مواضع السرفر:
    i[1]=الكود  i[2]=الاسم المعروض  i[5]=الدفع  i[14]=الحالة  i[-9]=دفع 1M."""
    rows = []
    seen = set()
    for i in instruments or []:
        try:
            if not isinstance(i, (list, tuple)) or len(i) < 6:
                continue
            code = str(i[1] or "").strip()
            name = str(i[2] or "").replace("\n", " ").strip()
            if not code or not name or code.lower() in ("none", "null"):
                continue
            if code in seen:
                continue
            payout = 0
            for cand in ((i[-9] if len(i) >= 10 else None), (i[5] if len(i) > 5 else None)):
                try:
                    v = float(str(cand).replace("%", "").strip())
                    if v > 0:
                        payout = int(round(v))
                        break
                except Exception:
                    continue
            open_ = True
            try:
                open_ = bool(i[14])
            except Exception:
                pass
            seen.add(code)
            flag, flag2 = qx_asset_flags(code, name)
            rows.append({"name": name, "code": code, "payout": payout, "open": open_,
                         "otc": code.lower().endswith("_otc"), "flag": flag, "flag2": flag2})
        except Exception:
            continue
    # v3.0.12 (أمر المالك: «المغلقة دائما يجب ان تكون في اخر القائمة وليس معا
    # الاوائل») — المفتوحة أولًا (الأعلى نسبة دفع، وOTC تفضيل عند تساوي الدفع)
    # ثم كل المغلقة في الأسفل — OTC المغلقة لم تعد تتقدم على المفتوحة
    rows.sort(key=lambda a: (1 if not a["open"] else 0, -a["payout"], 0 if a["otc"] else 1, a["name"]))
    return rows[:QX_BOARD_MAX]


# ═══════════════════════════════════════════════════════════════════════════════
# ═══════════════════════════════════════════════════════════════════════════════
# قرار المالك (2026-11-18): «انزع السرفر كليا من الكود» — محرك الشموع وثوابت إعادة
# الاتصال أُنزعا بالكامل (الأرشيف الحرفي في QX_server_archive.py). الأدوات المحلية
# فوق (الأعلام والقائمة وساعة السوق وبناء اللوحة) تبقى كما هي لسهولة الربط لاحقًا.
# ═══════════════════════════════════════════════════════════════════════════════

class Backend(QObject):
    langChanged = Signal()
    darkChanged = Signal()
    filesChanged = Signal()
    candlesChanged = Signal()
    histChanged = Signal()
    liveSigChanged = Signal()   # a live signal fired or a pending one settled (Signals page cards)
    consoleMsg = Signal(str, str)          # kind, text
    pyValues = Signal(str, str, str)       # id, seriesJson, rangeJson
    testResult = Signal(bool, str)
    shotSaved = Signal(bool, str)          # ok, path
    liveChanged = Signal()
    addedChanged = Signal()                # Added-currencies list changed (settings panel)
    sigResult = Signal(str)                # Signal result (WIN/LOSS) after the duration ends
    myIndsChanged = Signal()               # My-indicators list on the indicators page changed (user request)
    notifChanged = Signal()                # Notification card changed (user request)
    paidCmd = Signal(str)                  # Valid remote control command: enable/disable a paid indicator (user request)
    pyStopped = Signal(str)                # BSE: a violating Python indicator was disabled — page removes its series
    boardChanged = Signal()                # the currency board data changed (board/boardJson notify)
    qxStateChanged = Signal()              # candles-server state: noserver/connecting/auth/online/lost (v3.0.1)
    qxEngineState = Signal(str)            # BRIDGE → Backend state relay (thread-safe queue)
    boardReady = Signal(str)               # BRIDGE → Backend: raw platform instruments (JSON)
    candlesReady = Signal(str)             # BRIDGE → Backend: candles for the current pair/tf (JSON)
    tickReady = Signal(str)                # v3.0.14: BRIDGE → Backend: instant live tick (JSON)
    candleRolledNow = Signal()             # BRIDGE → Backend: a new candle STARTED (one-shot — v3.0.3)
    loginDone = Signal(bool, str)          # BRIDGE → Backend: the sign-in attempt settled (ok, msg)
    logLine = Signal(str, str)             # BRIDGE → Backend: console lines (kind, text)
    qxBusyChanged = Signal()               # a sign-in attempt is running (the دخول spinner — v3.0.1)
    qxErrorChanged = Signal()              # the sign-in error line changed (v3.0.1)
    indDataReady = Signal(str)             # v3.0.28: candles of OTHER assets for indicators (JSON)

    def __init__(self):
        super().__init__()
        cfg = _read_json(CFG_FILE, {})
        self._lang = cfg.get("lang", "en")
        self._dark = bool(cfg.get("dark", True))
        # v3.0.12 (أمر المالك): عمق الجلب الافتراضي محفوظ — عدد الشموع (الأيام
        # تُشتق منه حسب الفريم الحالي عند الحفظ) ويقود APP_CANDLE_LIMIT فعليًا
        # v3.0.18: أرضية 700 عند الإقلاع — قيمة hist محفوظة قديمة (180 مثلًا)
        # كانت تجعل كل الفريمات 180 شمعة من أول إقلاع
        # v3.0.45 (أمر المالك: «ويجب ان تجلب 700 شمعة فقط وليس 2000»): عمق
        # الإقلاع مثبت 700 لكل الفريمات — قيمة hist محفوظة قديمة (2000 مثلًا من
        # جلسات سابقة) لم تعد ترفع العمق الافتراضي وتضخّم جلب كل فريم؛ الأعمق
        # من 700 يأتي فقط من طلب بطاقة الإعدادات الصريح (الأيام) داخل الجلسة،
        # والبطاقة ما زالت تعمل كما هي (نصاها المحفوظان يظهران كما كُتبا).
        self._hist_candles = int(APP_CANDLE_LIMIT)
        globals()["APP_CANDLE_LIMIT"] = int(self._hist_candles)
        # v3.0.28: النصان المكتوبان يُقرآن كما حُفظا — البطاقة تُظهر ما كتبه
        # المستخدم حرفيًا ولا يُمحى حتى يمحيه هو (histC/histD في config.json).
        # (عمق آخر جلسة يبقى محفوظًا ويقود طلبات الفريمات عبر APP_CANDLE_LIMIT؛
        # جلب إقلاع السرفر نفسه كما هو حرفيًا — لا لمس للسرفر.)
        try:
            self._hist_c_text = str(cfg.get("histC") or "")
        except Exception:
            self._hist_c_text = ""
        try:
            self._hist_d_text = str(cfg.get("histD") or "")
        except Exception:
            self._hist_d_text = ""
        self._market = "real"        # Real/demo account section removed — the market tag remains for OTC currencies only
        # قرار المالك: USDDZD_otc هي الافتراضية عند الدخول — في وضع بلا سرفر المكافئ
        # المحلي هو USD/DZD OTC (نفس الزوج بأسماء القائمة المحلية) مع EUR/USD احتياطًا.
        # v3.0.5 (أمر المالك الحرفي: «يفتح شارت العملة الافتراضية USDDZD وليس EURUSD»):
        # الإقلاع يفتح USDDZD دائمًا — العملة المحفوظة من جلسة قديمة (EUR/USD) لا تُقرأ
        # عند الإقلاع، وإلا انتظرت الواجهة EURUSD بينما يجلب الترمنال USDDZD ويُسقط
        # حارس الدفعات كل شموع USDDZD فيبقى الشارت فارغًا ينتظر.
        self._asset = "USD/DZD OTC"
        self._tf = cfg.get("tf", "1m")
        if self._tf not in dict(TFS):
            # a saved frame that was removed (15s/30s/2m/3m/10s/4H/1D) falls back to 1m
            self._tf = "1m"
        if not any(a["name"] == self._asset for a in ASSETS["real"] + ASSETS["otc"]):
            self._asset = "USD/DZD OTC" if any(a["name"] == "USD/DZD OTC" for a in ASSETS["otc"]) else "EUR/USD"
        board_names = [b["name"] for b in BOARD]
        saved_added = [n for n in (cfg.get("added") or []) if isinstance(n, str) and n in board_names]
        # v3.0.46 (أمر المالك: «عملة EURUSD لماذا هي تفتح تلقايا معا العملة
        # الافتراضية ابقي العملة الافتراضية فقط»): الثلاثي (USD/DZD OTC + EUR/USD
        # + BTC/USD) لم يختره المستخدم — كان زرعًا تلقائيًا من الإصدارات القديمة
        # يُكتب في config.json فيُفتح EUR/USD تلقائيًا مع الافتراضية كل إقلاع.
        # الثلاثي المزروع بالضبط (بأي ترتيب) يُطوى إلى الافتراضية فقط، وقائمة
        # المستخدم الحقيقية (أسماء أضافها أو أزالها بنفسه) تبقى كما هي حرفيًا.
        if saved_added and set(saved_added) == {"USD/DZD OTC", "EUR/USD", "BTC/USD"}:
            saved_added = []
        if not saved_added:
            saved_added = [self._asset] if self._asset in board_names else board_names[:1]
        self._added = list(dict.fromkeys(saved_added))
        # v3.0.5: العملة الافتراضية أولًا في الشريط عند الإقلاع (الافتراضية USDDZD)
        if self._asset in board_names:
            self._added = [self._asset] + [n for n in self._added if n != self._asset]
        self._live = True        # Live feed always runs directly — candles animate with no button (user request)
        self._tick = 0
        # قرار المالك الحرفي («انزع الشموع الوهمية»): الإقلاع يبدأ برسم فارغ صادق —
        # الشموع الحقيقية فقط من سرفر الشموع (المولّد القديم للاختبار عبر BADI_DEMO_CANDLES=1)
        self._candles = generate_candles(self._asset, self._tf) if DEMO_CANDLES_OK else []
        self._files = self._load_files()
        _ensure_badi_dirs()
        self.syncDiskFiles(emit=False)     # Import any files the user dropped into the BadiCharts folder
        # ── Watching both BadiCharts folders: any file the user drops is detected instantly and shows on
        #    the indicators page directly, without a restart (user request) ──
        self._watcher = QFileSystemWatcher(self)
        self._watcher.addPath(BADI_IND_DIR)
        self._watcher.addPath(BADI_TOOL_DIR)
        self._watcher.directoryChanged.connect(self._on_dir_changed)
        self._hist = _read_json(os.path.join(CFG_DIR, "signals.json"), [])
        self._closing = False    # stop_all() flips it — guards signals into a dying engine
        self._paidBusy = False   # one paid-poll network worker at a time
        self._sigpend = []       # Signals waiting for their result (WIN/LOSS after the timeframe duration)
        # ── Chart appearance: not stored anymore — the chart always wears the app theme colors
        #    (user request). An old "chart_theme" key in config.json is ignored and dropped on
        #    the next save. ──
        self._py_mods = {}       # id -> module dict
        self._py_err = {}        # id -> count
        self._py_names = {}      # id -> fileName
        self._py_slow = {}       # id -> (last slow-call time, strikes) — BSE per-call CPU budget
        self._pending = None     # Signal waiting for its screenshot
        os.makedirs(SHOTS_DIR, exist_ok=True)

        # ── Paid indicators: notification card (no ready-made notifications — the developer sends them from his server)
        #    + the developer control channel through his server with allow-listed commands only (user request) ──
        self._notifs = []            # Card notifications: text only — never any files through this channel
        self._paid_block = {}        # Server exceeded the limits → temporary 10-minute ban (hardened protection)
        self._paidT = QTimer(self)
        self._paidT.setInterval(15 * 60 * 1000)
        self._paidT.timeout.connect(self._paid_poll)
        self._paidT.start()
        QTimer.singleShot(6000, self._paid_poll)
        self._paidW = QTimer(self)
        self._paidW.setInterval(60 * 60 * 1000)
        self._paidW.timeout.connect(self._paid_watch)
        self._paidW.start()
        QTimer.singleShot(7000, self._paid_watch)
        self._timer = QTimer(self)
        # v3.0.14 (أمر المالك: «تحديث السعر ضعيف … يجب ان يكون بكل تيكس يصل وليس
        # كل 1 ثانية»): نبض المحاكاة بدل 1000ms — السعر يتحرك مع كل نبضة،
        # والعمل الثقيل (مؤشرات بايثون) يبقى كل ثانية عبر بوابة زمنية — لا ثمن CPU
        # v3.0.15 (أمر المالك: «لنغيره الى 100 ميلي ثانية كافية»): النبض 100ms
        self._timer.setInterval(100)
        self._timer.timeout.connect(self._on_tick)
        # Actually start the timer — without this line the live-candle engine stayed completely off
        # and that is why no new candles appeared in the app (the chart was frozen)
        self._timer.start()
        # Worker-thread results land back on the GUI thread through these queued signals —
        # the GUI thread never waits on a network socket (crash/freeze fix, user request)
        self.tgDelivered.connect(self._tg_delivered)
        self.paidFetched.connect(self._paid_fetched)

        # ── سرفر الشموع داخل التطبيق (v3.0.1 — «كما هو»): الدخول من واجهة التطبيق ──
        # السرفر نفسه (server_main في الجزء الثالث) يُشغَّل كما هو عبر BRIDGE،
        # والقنوات الأربع (لوحة/شموع/حالة/سجل) تصل إشارات Qt آليًا بين الخيوط.
        self._qx_state = "noserver"
        self._qx_busy = False
        self._qx_error = ""
        self._board = list(BOARD)            # اللوحة: محلية قبل الدخول ثم قائمة المنصة الحقيقية
        self._board_codes = {}               # name -> كود المنصة (مثال: USD/DZD OTC -> USDDZD_otc)
        self._dec_live = 0                   # digits من السرفر للعملة الحالية (0 = من الإعداد المحلي)
        BRIDGE.board_cb = self.boardReady.emit
        BRIDGE.candle_cb = self.candlesReady.emit
        BRIDGE.tick_cb = self.tickReady.emit    # v3.0.14: كل تيك يصل → دفع فوري للصفحة
        BRIDGE.state_cb = self.qxEngineState.emit
        BRIDGE.log_cb = lambda msg: self.logLine.emit("info", str(msg))
        BRIDGE.result_cb = self.loginDone.emit
        self.boardReady.connect(self._engine_board)
        self.candlesReady.connect(self._engine_candles)
        self.tickReady.connect(self._engine_tick)   # v3.0.14: التيك الحي يصل للصفحة فورًا
        self.qxEngineState.connect(self._engine_state)
        self.loginDone.connect(self._engine_login_done)
        self.logLine.connect(self._engine_log)

        # v3.0.23 (2، أمر المالك): دمج نبضات التيك بمؤقت 40ms — كل تيك كان يطلق
        # candlesChanged ثم pushTick ثم runSignals على الصفحة؛ وعند انشغال خيط
        # الواجهة تتراكم النبضات وتُفرّغ دفعة واحدة فتركض الشمعة. الآن الإطلاق
        # مرة كل 40ms على الأكثر (السعر يتحرك 25 مرة/ثانية) والنبضات المتراكمة
        # تُدمج في إطلاق واحد بلا أي تراكم في الطابور.
        self._tick_dirty = False
        self._flush_timer = QTimer(self)
        self._flush_timer.setInterval(40)
        self._flush_timer.timeout.connect(self._flush_tick)
        self._flush_timer.start()

        # ── v3.0.28: مؤشرات تطلب شموع عملات أخرى — طابور متسلسل واحد ──
        # «يضع 10 عملات او 20 عملة … اقصى عدد 200 شمعة لكل عملة … ويتم جلبهم
        # بالتسلسل اوك عندما يجلب واحدة يذهب الى الاخرى» — طلب واحد نشط في كل
        # لحظة، وكل الطلبات (جافاسكربت وبايثون) تمر من هنا.
        self._ind_q = []             # الطلبات المنتظرة (قواميس)
        self._ind_active = None      # الطلب الجاري الآن
        self._ind_cache = {}         # ck → {"candles": [...], "ts": float}
        self._ind_err = {}           # ck → {"error": str, "ts": float}
        self._indT = QTimer(self)
        self._indT.setInterval(300)
        self._indT.timeout.connect(self._ind_pump)
        self._indT.start()
        # مساعدتا الصندوق البايثوني (request_candles / log) يعملان عبر هذين الوسيطين
        try:
            globals()["_PY_IND_DATA_HOOK"] = self.indPyRequest
        except Exception:
            pass
        try:
            globals()["_PY_LOG_SINK"] = lambda msg: self._log("info", str(msg))
        except Exception:
            pass

