    # ---------- Internal helpers ----------
    def _asset_cfg(self, asset=None):
        name = str(asset or self._asset or "")
        row = self._board_row(name)
        if row is not None and (row.get("code") or self._qx_state == "online"):
            # صف من المنصة: عدد الخانات من السرفر إن وصل، وإلا قاعدة الأرقام نفسها
            dec = self._dec_live if (self._dec_live and name == self._asset) else 0
            if not dec:
                dec = qx_digits(str(row.get("code") or name))
            return {"name": name, "base": 0.0, "vol": 0.0012, "dec": int(dec or 5)}
        for a in ASSETS["real"] + ASSETS["otc"]:
            if a["name"] == name:
                return a
        return ASSETS["real"][0]

    def _tf_sec(self):
        return dict(TFS).get(self._tf, 60)

    def _paid_ntext(self, kind, name, left=None):
        """Subscription notification text per UI language (owner request): bn/hi/es get
        their own text, ur joins ar in the RTL family, everything else falls back to en."""
        if kind == "ended":
            txt = {
                "en": "Subscription of " + name + " ended — renew to use it again",
                "ar": "انتهى اشتراك مؤشر " + name + " — يجب التجديد لاستخدامه من جديد",
                "bn": "ইন্ডিকেটর " + name + "-এর সাবস্ক্রিপশন শেষ হয়েছে — আবার ব্যবহার করতে নবায়ন করুন",
                "hi": "इंडिकेटर " + name + " की सदस्यता समाप्त हो गई — दोबारा उपयोग के लिए नवीनीकृत करें",
                "es": "La suscripción del indicador " + name + " terminó — renuévala para usarlo de nuevo",
                "ur": "انڈیکیٹر " + name + " کی سبسکرپشن ختم ہو گئی — دوبارہ استعمال کے لیے تجدید کریں",
            }
        else:
            days = str(max(0, int(left or 0)))
            txt = {
                "en": "Subscription of " + name + " ends in " + days + " day(s) — renew",
                "ar": "ينتهي اشتراك مؤشر " + name + " بعد " + days + " يوم — يجب التجديد",
                "bn": "ইন্ডিকেটর " + name + "-এর সাবস্ক্রিপশন " + days + " দিনের মধ্যে শেষ হবে — নবায়ন করুন",
                "hi": "इंडिकेटर " + name + " की सदस्यता " + days + " दिन में समाप्त होगी — नवीनीकृत करें",
                "es": "La suscripción del indicador " + name + " termina en " + days + " día(s) — renuévala",
                "ur": "انڈیکیٹر " + name + " کی سبسکرپشن " + days + " دن میں ختم ہوگی — تجدید کریں",
            }
        return txt.get(self._lang) or txt["en"]

    # ═══ v3.0.12 (أمر المالك): بطاقة الإعدادات — «كم يحمل الشموع الافتراضية
    # التي يريدها» — حقلان مكتوبان (عدد الشموع أو عدد الأيام، بلا قوائم) وزر
    # حفظ يصفّر الشارت ويبدأ الجلب من جديد. حد الفريمات يُحترم دائمًا:
    # فريمات الثواني (5s·10s·15s·30s) = يوم واحد كحد أقصى (TF_DAYS_LIMITS). ═══
    @Slot(str)
    def _engine_tick(self, js):
        """v3.0.14 (أمر المالك: «تحديث السعر ضعيف … يجب ان يكون بكل تيكس يصل
        وليس كل 1 ثانية»): تيك حي وصل من معالج رسالة الويبسوك نفسه — يُدمج في
        الشمعة الجارية ويُدفع للصفحة فورًا (pushTick خفيف بلا إعادة رسم كاملة).
        لفّ الشمعة وتجميع النافذة يبقى لمسار الشموع (البولر) — هذا المسار للسعر
        الحي فقط، ومطابقة العملة نفس المطابقة الطبيعية في _engine_candles."""
        try:
            d = json.loads(js)
        except Exception:
            return
        a = str(d.get("asset") or "")
        if not a:
            return

        def _nnx(s):
            return re.sub(r"[\s/_\-()]+", "", str(s or "")).lower()

        ok = _nnx(a) == _nnx(self._asset)
        if not ok:
            try:
                ok = _nnx(_pair_name_to_api(a)) == _nnx(self._asset)
            except Exception:
                ok = False
        if not ok:
            return              # تيك عملة أخرى — الشارت الحالي لا يتأثر
        try:
            price = float(d.get("price") or 0)
            ts = int(d.get("ts") or 0)
        except Exception:
            return
        if price <= 0 or ts <= 0 or not self._candles:
            return
        tf_sec = max(1, self._tf_sec())
        last = self._candles[-1]
        w0 = int(last["t"])
        if not (w0 <= ts < w0 + tf_sec):
            return              # لفّ الشمعة أو تيك خارج النافذة — مسار الشموع يتكفل
        c0 = float(last.get("c", 0) or 0)
        h0 = float(last.get("h", price) or 0)
        l0 = float(last.get("l", price) or 0)
        if price == c0 and l0 <= price <= h0:
            return              # لا تغيير فعلي في السعر — لا سبام
        last["c"] = price
        last["h"] = max(h0, price)
        last["l"] = min(l0, price)
        self._tick_dirty = True     # v3.0.23: الإطلاق عبر مؤقت الدمج 40ms (_flush_tick)

    def _flush_tick(self):
        """v3.0.23 (2، أمر المالك): مؤشر دمج نبضات التيك — candlesChanged يُطلق
        مرة واحدة كل 40ms على الأكثر حتى لو وصلت تيكات متتالية؛ النبضات المتراكمة
        عند انشغال خيط الواجهة تُدمج في إطلاق واحد بدل انفجار الطابور."""
        if self._tick_dirty:
            self._tick_dirty = False
            self.candlesChanged.emit()

    @Property(int, notify=candlesChanged)
    def histCandles(self):
        return int(getattr(self, "_hist_candles", 0) or 0)

    # v3.0.28 — النصان المكتوبان كما هما («عندما يكتب الرقم تبعو يجب ان يبقا
    # محفوض ولا يمحى حتا يمحيه هو») — البطاقة تملأ منهما عند كل فتح.
    # v3.0.37 — بطاقة الإعدادات صارت تملأ حقل الأيام فقط (histDText)؛ histCText
    # بقي مكشوفًا للتوافق لكن لا حقل يقرأه بعد إزالة (عدد الشموع) من البطاقة،
    # وعند أول حفظ جديد يُكتب histC="" في config.json فيُمحى النص القديم.
    @Property(str, notify=histChanged)
    def histCText(self):
        return str(getattr(self, "_hist_c_text", "") or "")

    @Property(str, notify=histChanged)
    def histDText(self):
        return str(getattr(self, "_hist_d_text", "") or "")

    @Slot(str, str, result=bool)
    def applyHist(self, candles_txt, days_txt):
        """v3.0.28 — تطبيق عمق الجلب من بطاقة الإعدادات (أمر المالك):
        1) الحد الموحّد: 30 يومًا و43,000 شمعة لأي فريم — بلا حدود فريمات أخرى
           (حد 5 ثواني = يوم واحد السابق وحد 300 ألف شمعة أُنزعا).
        2) النصان المكتوبان يُحفظان كما هما ولا يُمحيان بعد الحفظ.
        3) محو فوري حقيقي للشارت: قيد محو يمنع عودة الشموع القديمة من كتّاب
           المخازن القدامى حتى وصول الجلب الجديد نفسه — دائرة التحميل تظهر
           (syncFull نفسه) وتُرسل الشموع مع أول دفعة مثل الوضع الافتراضي حرفيًا.
        4) العمق يقود الجلب فعليًا لكل فريم بطريقته نفسها: 1m عبر
           INITIAL_CANDLES/HISTORY_DAYS/FETCH_DURATION_SECONDS، و5m فما فوق
           بطلب أيام /api/tf-load نفسه، و5S بطريقتها الخاصة بعمق حرفي.
        v3.0.37 — البطاقة تستدعي applyHist("", الأيام) بعد إزالة حقل
           (عدد الشموع): مسار الأيام نفسه حرفيًا (الأيام تحسب الشموع حسب
           الفريم أدناه)، وc_txt="" يمحو نص histC القديم المحفوظ عند الحفظ.
        v3.0.38 — أمر المالك: «يمكنه ان ينزل تحت 1 يوم مثلا 0.8 0,6 0,5 0,4
           0,1 0,01 اقصى شيئ» — الأيام الكسرية: تُقرأ float بعد توحيد الفاصلة
           (النقطة والفاصلة والفاصلة العربية كلها تُقبل)، الحد 0.01..30،
           الشموع = أيام×86400÷ثواني الفريم بأرضية شمعة واحدة، وأرضية الفريم
           700 لم تُرفَع فوق الطلب الصريح الصغير (فالأرضية تحمي الإقلاع فقط —
           في __init__ كما هي) فيُعرض العمق الصغير فعلًا."""
        c_txt = str(candles_txt or "").strip()
        # v3.0.38: الفاصلة العربية «،» والفاصلة العشرية العربية «٫» والفاصلة اللاتينية — كلها فاصلة عشرية
        d_txt = str(days_txt or "").strip().replace("\u066b", ".").replace("\u060c", ".").replace(",", ".")
        try:
            c = int(c_txt or "0")
        except Exception:
            c = 0
        try:
            d = float(d_txt or "0")
        except Exception:
            d = 0.0
        if c <= 0 and d <= 0:
            return False
        tf_label = str(self._tf or "1m")
        tf_sec = APP_TFS.get(tf_label, 60)
        # v3.0.54 (أمر المالك: «عند اختيار عدد الايام تبع الشموع لا تنسى فريم 5
        # ثواني يجب ان يعمل بطريقته وليس ب طريقة فريمات الاخرى»): فريم 5 ثواني
        # (كل فريم تحت الدقيقة) يُعالَج هنا بطريقته الخاصة حرفيًا — سقف أيامه هو
        # سقفه هو (TF_DAYS_LIMITS: يوم واحد لـ5S، نفس سقف بطاقة أيام صفحة الشارت
        # TF_DAYS_MAX ونفس سقف /api/tf-load)، وتحويل الأيام إلى شموع بثواني
        # الفريم نفسه، وبلا سقفَي الفريمات الأخرى إطلاقًا (لا 30 يومًا ولا 43 ألف
        # شمعة). الجلب نفسه يبقى بعد ذلك في فرع 5S الخاص داخل _request_tf (عمق
        # حرفي بطريقتها الخاصة بأرضية 2000) كما هو — لم يُمَس إطلاقًا.
        # فريمات الدقيقة فما فوق: المسار الموحّد نفسه كما هو حرفيًا.
        # v3.0.28: الحد الموحّد — 30 يومًا و43,000 شمعة (لفريمات الدقيقة فما فوق)
        # v3.0.38: الأيام الكسرية — 0.01 أدنى حد («اقصى شيئ») وأرضية شمعة واحدة
        _own_days_cap = float(TF_DAYS_LIMITS.get(int(tf_sec), float(HIST_MAX_DAYS))) \
            if int(tf_sec) < 60 else 0.0
        if d > 0:
            if int(tf_sec) < 60:
                # طريقة 5S الخاصة: سقف أيامه هو (يوم واحد لـ5S) وليس 30 يومًا
                d = max(TF_DAYS_MIN, min(float(d), _own_days_cap))
                c = max(1, int(d * 86400 / max(1, int(tf_sec))))
            else:
                d = max(0.01, min(float(d), float(HIST_MAX_DAYS)))
                c = max(1, int(d * 86400 / max(1, int(tf_sec))))
        if c > 0:
            if int(tf_sec) < 60:
                # سقف شموع 5S الخاص (يوم 5S = 86400 ÷ 5 = 17,280 شمعة) — سقفه هو
                # حرفيًا بحد أدنى شمعة واحدة، بلا حد 43 ألف شمعة الخاص بالفريمات الأخرى
                c = max(1, min(int(c),
                               max(1, int(_own_days_cap * 86400 / max(1, int(tf_sec))))))
            else:
                if (c * tf_sec / 86400.0) > float(HIST_MAX_DAYS):
                    c = max(1, int(HIST_MAX_DAYS * 86400 / tf_sec))
                c = max(1, min(int(c), int(HIST_MAX_CANDLES)))
            # v3.0.18 (أرضية 700/2000) انزعت من هنا بأمر v3.0.38: أرضية الإقلاع
            # تبقى في __init__ (حماية قيم hist القديمة المحفوظة)، لكن الطلب
            # الصريح الصغير من البطاقة يُحترم كما هو — والعامل الذي يحصر عرض
            # الفريمات (_app_frame_limit في مسار الدفع) لا يقطع تحت العمق المطلوب
            # لأنه حد أقصى للقصّ لا حد أدنى للعمق.
        # كود الجلب الفعلي (مفتاح المخزن) من آخر تبديل — اسم العرض لا يفتح المخزن
        code = str(self._asset or "")
        try:
            code = str(BRIDGE._cur[0] or code)
        except Exception:
            pass
        globals()["APP_CANDLE_LIMIT"] = int(c)
        # v3.0.28: عمق فريم الدقيقة يقود جلبه فعليًا — كان APP_CANDLE_LIMIT
        # يقود طلبات الفريمات فقط، فطلب «10 أيام» على 1m كان يُجلب 700 شمعة
        # كما هي. الآن نفس ثوابت جلب الدقيقة تُضبط من العمق المطلوب.
        try:
            if int(tf_sec) == 60:
                globals()["INITIAL_CANDLES"] = int(c)
                globals()["HISTORY_DAYS"] = (int(c) * 60) / 86400.0 * 1.15
                globals()["FETCH_DURATION_SECONDS"] = int(86400 * globals()["HISTORY_DAYS"])
        except Exception:
            pass
        self._hist_candles = int(c)
        # v3.0.28: النصان كما كتبهما المستخدم — يبقيان ظاهرين حتى يمحوهما هو
        self._hist_c_text = c_txt
        self._hist_d_text = d_txt
        self.histChanged.emit()
        self._save_cfg()
        # تصفير الشارت: الشموع المحلية + مخزن الجلب (الشمعي والفريمات) ثم إشارة فارغة
        pair = _web_pair_name(code)
        pl = pair.lower()
        # v3.0.28 — قيد المحو: من لحظة الحفظ لا كاتب قديم يعيد بناء المخازن
        # (بث العملة نفسها / web_candle_refresher كل 30 ثانية / كاتب MT4 /
        # بناة الفريمات) — الجلب الجديد فقط (مالك الرمز) يفتح القيد عند أول
        # كتابة له، فإما الشموع الجديدة أو الشارت فارغ بدائرة التحميل.
        _tok = "w" + str(time.time_ns())
        _wipe_guard_start(pl, _tok)
        if int(tf_sec) != 60:
            _wipe_guard_start(pl + "|" + str(int(tf_sec)), _tok)
            try:
                _WEB_TF_WIPE_TOK[(str(code or "").strip().lower(), int(tf_sec))] = _tok
            except Exception:
                pass
        try:
            _od_set_state(str(code or "").strip(), wipe_token=_tok)
        except Exception:
            pass
        with _web_candle_lock:
            for k in [k for k in _web_candle_store if k.lower() == pl]:
                _web_candle_store.pop(k, None)
            for k in [k for k in _web_latest_tick if k.lower() == pl]:
                _web_latest_tick.pop(k, None)
            for k in [k for k in _web_tf_store if k.split("|")[0].lower() == pl]:
                _web_tf_store.pop(k, None)
            for k in [k for k in _web_tf_tick if k.split("|")[0].lower() == pl]:
                _web_tf_tick.pop(k, None)
        self._candles = []
        self.candlesChanged.emit()
        # إعادة الجلب من جديد: نفس نداء التبديل (on-demand + طلب الفريم الحالي)
        try:
            BRIDGE.app_switch(code, tf_label, self._asset)
        except Exception:
            pass
        self._log("ok", f"[hist] fetch depth = {c} candles ({tf_label}) — الشارت مُحِي فورًا (قيد محو نشط) والجلب من جديد بالعمق المطلوب")
        return True

    def _save_cfg(self):
        # v3.0.31 (إصلاح جذري — سبب «اختفاء الواجهة»): هذه الدالة كانت تكتب config.json
        # بالكتابة الساقعة (8 مفاتيح فقط) فتمحو التوكن وقائمة البوتات (bots) وattach
        # وbotOn وchats وtmpl كل مرة يبدّل فيها المستخدم الزوج أو اللغة أو الوضع الداكن
        # أو عمق الشموع — فتختفي البوتات المحفوظة من صفحة بوت تلجرام بالكامل.
        # الإصلاح: اقرأ الإعدادات الحالية أولًا وادمج فوقها — كل مفاتيح تيليجرام
        # (token/bots/attach/botOn/chats/tmpl/shareChat) وكل مفاتيح أخرى تبقى محفوظة.
        cfg = _read_json(CFG_FILE, {})
        cfg.update({"lang": self._lang, "dark": self._dark,
                    "asset": self._asset, "tf": self._tf,
                    "added": self._added,
                    "hist": int(getattr(self, "_hist_candles", 0) or APP_CANDLE_LIMIT),
                    # v3.0.28: ما كتبه المستخدم حرفيًا يبقى محفوظًا
                    "histC": str(getattr(self, "_hist_c_text", "") or ""),
                    "histD": str(getattr(self, "_hist_d_text", "") or "")})
        _write_json(CFG_FILE, cfg)

    # ═════════ v3.0.28: مؤشرات تطلب شموع عملات أخرى ═════════
    # أمر المالك: «ضع للمؤشرات يمكنها طلب شموع عملات اخرى لكي تعمل بها …
    # المستخدم يضع 10 عملات او 20 عملة عدد الشموع التي يريدها اقصى عدد 200
    # شمعة لكل عملة … ويتم جلبهم بالتسلسل اوك عندما يجلب واحدة يذهب الى
    # الاخرى … بخصوص العملة يجب ان يكتبها في المؤشر كما هي في النضام وليس في
    # الواجهة … بخصوص طريقة طلب المؤشر مثل الطريقة التي في التطبيق اوك حسب
    # الفريم نفس الطريقة تماما لا تخطا اوك».
    # طابور واحد متسلسل يخدم مؤشرات جافاسكربت وبايثون معًا (طلب واحد نشط ثم
    # الذي بعده)، والجلب نفسه عبر طرق التطبيق الحرفية: on-demand نفسه للمحمّلة،
    # مخزن الدقيقة نفسه لـ 1m، وطابور الفريمات الخلفية ونفس _load_tf_history
    # لـ 5m/10m/15m/30m/1H، وطريقة 5S الخاصة بعمقها الحرفي لـ 5s.

    def _ind_resolve_symbol(self, s):
        """رمز النظام فقط — «العملة يجب ان يكتبها في المؤشر كما هي في النضام
        وليس في الواجهة»: مطابقة كود المنصة (USDDZD_otc) أولًا بنفس الأحرف ثم
        غير حساسة للأحرف، وإن لم تطابق فمطابقة طبيعية لاسم العرض (USD/DZD OTC
        ≡ USDDZD_otc — راحة للمطور، والدليل يوثّق كود النظام). قبل وصول قائمة
        المنصة يُقبل النص كما هو."""
        s = str(s or "").strip()
        if not s:
            return ""
        rows = self._board if isinstance(self._board, list) else []
        if rows:
            for r in rows:
                if isinstance(r, dict) and str(r.get("code") or "") == s:
                    return s
            sl = s.lower()
            for r in rows:
                if isinstance(r, dict) and str(r.get("code") or "").lower() == sl:
                    return str(r.get("code") or "")

            def _nn(x):
                return re.sub(r"[\s/_\-()]+", "", str(x or "")).lower()
            sn = _nn(s)
            for r in rows:
                if isinstance(r, dict) and (_nn(r.get("code")) == sn or _nn(r.get("name")) == sn):
                    return str(r.get("code") or "")
            return ""          # ليس في قائمة المنصة — لا اختراع أسماء
        return s

    def _ind_norm_tf(self, tf):
        """فريمات التطبيق نفسها فقط: '5s'|'10s'|'15s'|'30s'|'1m'|'5m'|'10m'|'15m'|
        '30m'|'1H'|'4H' (أو ثوانيها) — None لأي فريم أجنبي، والافتراضي فريم
        الشارت الحالي. v3.0.55: فريمات الثواني الجديدة و4H دخلت القائمة."""
        if tf in (None, "", 0):
            return int(APP_TFS.get(str(self._tf or "1m"), 60))
        try:
            if isinstance(tf, bool):
                return None
            if isinstance(tf, (int, float)):
                v = int(tf)
            else:
                m = {str(k).lower(): int(v2) for k, v2 in APP_TFS.items()}
                v = m.get(str(tf).strip().lower())
                if v is None:
                    v = int(float(str(tf).strip()))
        except Exception:
            return None
        v = int(v)
        return v if v in (5, 10, 15, 30, 60, 300, 600, 900, 1800, 3600, 14400) else None

    @staticmethod
    def _ind_read_cstore(pair):
        """قراءة مخزن الدقيقة (نفس قراءة /api/candles — مطابقة غير حساسة للأحرف)."""
        pl = str(pair or "").lower()
        with _web_candle_lock:
            e = _web_candle_store.get(pair)
            if e is None:
                for k, v in _web_candle_store.items():
                    if k.lower() == pl:
                        e = v
                        break
            return dict(e) if e else None

    @staticmethod
    def _ind_read_tfstore(pair, tfs):
        """قراءة مخزن الفريم (نفس قراءة _tf_serve_candles — مطابقة غير حساسة)."""
        key = _tf_store_key(pair, tfs)
        pl, sk = str(pair or "").lower(), f"|{int(tfs)}"
        with _web_candle_lock:
            e = _web_tf_store.get(key)
            if e is None:
                for k, v in _web_tf_store.items():
                    if k.endswith(sk) and k.split("|")[0].lower() == pl:
                        e = v
                        break
            return dict(e) if e else None

    @Slot(str)
    def indDataReq(self, js):
        """v3.0.28 — طلب شموع عملة أخرى من مؤشر جافاسكربت عبر جسر الصفحة
        (BADI::datareq): {key, sym, tf, n} — يدخل الطابور المتسلسل نفسه."""
        try:
            d = json.loads(str(js or ""))
        except Exception:
            return
        if not isinstance(d, dict):
            return
        self._ind_enqueue(str(d.get("sym") or ""), str(d.get("key") or ""),
                          d.get("tf"), d.get("n"))

    def indPyRequest(self, symbol, count=200, tf=None, days=None):
        """وسيط request_candles() لمؤشرات بايثون — الطابور المتسلسل نفسه.
        يعيد شموع {t,o,h,l,c,v} عند التجهيز أو None وهي قيد الجلب.
        v3.0.38: days — عمق بالأيام الكسرية 0.01..30 (أمر المالك: «المؤشر
        يستطيع طلب الشموع» — نفس طريقة عدّاد بطاقة الإعدادات حرفيًا)."""
        sym_raw = str(symbol or "").strip()
        tfs = self._ind_norm_tf(tf)
        if tfs is None:
            return None
        sym = self._ind_resolve_symbol(sym_raw)
        if not sym:
            if not hasattr(self, "_ind_py_warned"):
                self._ind_py_warned = set()
            if sym_raw and sym_raw not in self._ind_py_warned:
                self._ind_py_warned.add(sym_raw)
                self._log("err", f"[ind-data] unknown asset code '{sym_raw}' — اكتب العملة كما هي في النظام (شغّل مثال قائمة العملات من دليل البرمجة)")
            return None
        try:
            n = max(1, min(int(count), int(IND_DATA_MAX_CANDLES)))
        except Exception:
            n = int(IND_DATA_MAX_CANDLES)
        # v3.0.38: الأيام الكسرية تحسب الشموع حسب الفريم (0.01..30 يومًا —
        # حد 43,000 مثل بطاقة الإعدادات) وتُسبق count إذا كُتبت معًا
        if days is not None and str(days).strip() != "":
            try:
                d_txt = str(days).strip().replace("\u066b", ".").replace("\u060c", ".").replace(",", ".")
                d_val = float(d_txt)
                d_val = max(0.01, min(30.0, d_val))
                tf_sec = max(1, int(tfs))     # _ind_norm_tf يعيد الثواني مباشرة
                n = max(1, min(int(HIST_MAX_CANDLES), int(round(d_val * 86400 / tf_sec))))
            except Exception:
                pass
        ck = f"{sym}|{tfs}|{n}"
        cc = self._ind_cache.get(ck)
        if cc:
            return [{"t": int(c["time"]), "o": float(c["open"]), "h": float(c["high"]),
                     "l": float(c["low"]), "c": float(c["close"]),
                     "v": float(c.get("volume") or 0)} for c in (cc.get("candles") or [])]
        ce = self._ind_err.get(ck)
        if ce and time.time() - float(ce.get("ts") or 0) < IND_DATA_ERR_TTL:
            return None
        self._ind_enqueue(sym_raw, "py|" + ck, tfs, n)
        return None

    def _ind_enqueue(self, sym_raw, rkey, tf, n):
        """إدخال طلب في الطابور المتسلسل (من الصفحة أو من بايثون). المطابقة
        بكود النظام، والتكرار يُدمج، والجاهز من الكاش يُسلَّم فورًا."""
        rkey = str(rkey or "")
        try:
            n = int(n)
        except Exception:
            n = int(IND_DATA_MAX_CANDLES)
        # v3.0.38: السقف الخلفي أصبح 43,000 (حد بطاقة الإعدادات الموحّد) —
        # قاعدة «اقصى 200 شمعة» تُفرض في طبقة واجهة Indicators.data (count)،
        # ومسار days الجديد يحسب الشموع من الأيام الكسرية حتى 30 يومًا
        n = max(1, min(n, int(HIST_MAX_CANDLES)))
        sym = self._ind_resolve_symbol(sym_raw)
        if not sym:
            self._ind_fail_one(rkey, f"unknown asset code '{sym_raw}' — write it as in the system (USDDZD_otc style); run the asset-list example in the guide")
            return
        tfs = self._ind_norm_tf(tf)
        if tfs is None:
            self._ind_fail_one(rkey, f"unknown timeframe '{tf}' — use 5s/10s/15s/30s/1m/5m/10m/15m/30m/1H/4H")
            return
        ck = f"{sym}|{tfs}|{n}"
        cc = self._ind_cache.get(ck)
        if cc:
            try:
                self.indDataReady.emit(json.dumps(
                    {"ok": True, "key": rkey, "sym": sym, "tf": tfs,
                     "n": len(cc.get("candles") or []), "candles": cc.get("candles") or []},
                    ensure_ascii=False))
            except Exception:
                pass
            return
        ce = self._ind_err.get(ck)
        if ce and time.time() - float(ce.get("ts") or 0) < IND_DATA_ERR_TTL:
            self._ind_fail_one(rkey, str(ce.get("error") or "unavailable"))
            return
        for r in ([self._ind_active] if self._ind_active else []) + self._ind_q:
            if r and r.get("ck") == ck:
                if rkey and rkey not in (r.get("rkeys") or []):
                    r.setdefault("rkeys", []).append(rkey)
                return
        if len(self._ind_q) >= int(IND_DATA_QUEUE_MAX):
            self._ind_fail_one(rkey, "data queue full — too many pending requests")
            return
        self._ind_q.append({"ck": ck, "sym": sym, "tf": tfs, "n": n,
                            "rkeys": [rkey] if rkey else [],
                            "started": 0.0, "od_req": False, "tf_req": False})

    def _ind_fail_one(self, key, err):
        try:
            self.indDataReady.emit(json.dumps({"ok": False, "key": str(key), "error": str(err)[:200]}))
        except Exception:
            pass

    def _ind_finish(self, r, candles, err):
        """إنهاء الطلب النشط: تسليم كل المفتاحين المنتظرين ثم الانتقال للتالي
        («عندما يجلب واحدة يذهب الى الاخرى» — التسلسل حرفيًا)."""
        self._ind_active = None
        ck = str(r.get("ck") or "")
        if candles is not None:
            self._ind_cache[ck] = {"candles": candles, "ts": time.time()}
            if len(self._ind_cache) > 80:
                try:
                    old = sorted(self._ind_cache.keys(),
                                 key=lambda k: float(self._ind_cache[k].get("ts") or 0.0))
                    for k in old[:-80]:
                        self._ind_cache.pop(k, None)
                except Exception:
                    pass
        else:
            self._ind_err[ck] = {"error": str(err or "error")[:200], "ts": time.time()}
        for k in (r.get("rkeys") or []):
            try:
                if candles is not None:
                    self.indDataReady.emit(json.dumps(
                        {"ok": True, "key": k, "sym": r.get("sym"), "tf": r.get("tf"),
                         "n": len(candles), "candles": candles}, ensure_ascii=False))
                else:
                    self.indDataReady.emit(json.dumps(
                        {"ok": False, "key": k, "error": str(err or "error")[:200]}))
            except Exception:
                pass

    def _ind_pump(self):
        """مضخة الطلبات (مؤقّت 300ms): طلب واحد نشط في كل لحظة — التسلسل
        الحرفي — وبنفس طريقة التطبيق تمامًا حسب الفريم:
          • العملة غير محمّلة → نفس تحميل on-demand (نفس محرك العملة الافتراضية).
          • 1m → نفس مخزن الدقيقة الذي تقرؤه /api/candles وبنفس بوابة التحقق.
          • 5m/10m/15m/30m/1H → نفس طابور الفريمات الخلفية ونفس
            _load_tf_history (الطلب يُطلق عبر BRIDGE._request_tf نفسه).
          • 5s → طريقتها الخاصة بعمق حرفي عبر نفس الطابور.
        مهلة الطلب الواحد 90 ثانية ثم يُعلن الخطأ ويبدأ التالي."""
        now = time.time()
        if self._ind_active is None:
            if not self._ind_q:
                return
            self._ind_active = self._ind_q.pop(0)
            self._ind_active["started"] = now
        r = self._ind_active
        if now - float(r.get("started") or 0.0) > float(IND_DATA_TIMEOUT_SEC):
            self._ind_finish(r, None, "timeout waiting for candles (asset unavailable or market closed)")
            return
        sym = str(r.get("sym") or "")
        tfs = int(r.get("tf") or 60)
        n = int(r.get("n") or int(IND_DATA_MAX_CANDLES))
        pair = _web_pair_name(sym)
        try:
            e = self._ind_read_cstore(pair)
        except Exception:
            e = None
        m1_ok = False
        m1_candles = []
        if e and e.get("candles"):
            validated = e.get("validated", None)
            m1_candles = list(e.get("candles") or [])
            if validated is None:
                try:
                    ok, _why, cleaned = _validate_chart_candles(m1_candles, period_seconds=60)
                    validated = ok
                    if ok:
                        m1_candles = list(cleaned or [])
                except Exception:
                    validated = True
            m1_ok = bool(validated)
        if not m1_ok:
            # العملة نفسها غير جاهزة → نفس on-demand (مرة واحدة لكل طلب؛
            # عامل on-demand يسلسل الطلبات بنفسه ولا تتخما الاتصال)
            if not r.get("od_req"):
                r["od_req"] = True
                try:
                    _request_on_demand_asset(sym)
                except Exception:
                    pass
            if tfs == 60:
                return              # انتظر جلب الدقيقة — نفس بوابة التحقق نفسها
        if tfs == 60:
            if m1_ok and m1_candles:
                self._ind_finish(r, m1_candles[-n:], "")
            return
        # فريم آخر → مخزن الفريمات (نفس مصدر /api/candles?tf=...)
        try:
            te = self._ind_read_tfstore(pair, tfs)
        except Exception:
            te = None
        tf_candles = list((te or {}).get("candles") or []) if te else []
        tf_val = bool((te or {}).get("validated", False))
        status = str(_tf_get_state(sym, tfs).get("status") or "")
        if tf_candles and (tf_val or status in ("ready", "error")):
            self._ind_finish(r, tf_candles[-n:], "")
            return
        if m1_ok and not r.get("tf_req"):
            with _TF_BG_LOCK:
                st_all = _TF_BG_STATE.get(sym) or {}
                sub = st_all.get(str(tfs)) or {}
                already = bool(st_all.get("requested")) and bool(sub)
            if not already:
                r["tf_req"] = True
                # الطلب بنفس طريقة التطبيق حرفيًا (نفس الصيغة والسجل والحالة):
                # 5s بعمقها الحرفي عبر طريقتها الخاصة، والبقية بطلب أيام
                # /api/tf-load نفسه — عبر نفس طابور العامل المتسلسل.
                try:
                    BRIDGE._request_tf(sym, tfs)
                except Exception:
                    pass

    def _load_files(self):
        data = _read_json(FILES_FILE, None)
        if isinstance(data, dict) and isinstance(data.get("files"), list):
            data = data["files"]
        out = []
        base_names = {"js": "My Indicator", "py": "Python Indicator", "jstool": "My Tool"}
        for s in SEEDS:
            sfx = random_suffix(6)
            ext = "py" if s["kind"] == "py" else "js"
            out.append({"id": s["kind"] + "_" + sfx.lower(),
                        "fileName": f"{base_names[s['kind']]}.{ext}", "kind": s["kind"],
                        "code": s["code"], "enabled": False})
        if isinstance(data, list) and data:
            # Migrate the guide name to English (user request): ignore the old entry with the Arabic name
            # so the sync does not write it back to disk after deletion
            out = [f for f in data if isinstance(f, dict)
                   and str(f.get("fileName") or "") not in LEGACY_GUIDE_FILES]
        return out

    def _log(self, kind, text):
        if self._closing:
            return
        self.consoleMsg.emit(kind, text)

    # ---------- BadiCharts folder: save indicators to disk and sync them ----------
    # Every indicator/tool created in the app is written as a real file inside BadiCharts/Indicators
    # or BadiCharts/Tools — and any file the user drops there is imported automatically.
    @staticmethod
    def _norm_kind(k):
        k = str(k or "").lower()
        if k in ("js", "indicator"):
            return "indicator"
        if k in ("jstool", "tool"):
            return "tool"
        if k == "py":
            return "py"
        if k == "badi":
            return "badi"
        return "indicator"

    @staticmethod
    def _new_file_id(kind):
        pfx = {"indicator": "ind", "tool": "tool", "py": "py", "badi": "badi"}.get(kind, "ind")
        return pfx + "_" + random_suffix(6).lower()

    def _disk_scan(self):
        """Scan both BadiCharts folders: indicator/tool files + encrypted .badi files."""
        _ensure_badi_dirs()
        items = []
        for d, exts in ((BADI_IND_DIR, ("js", "py")), (BADI_TOOL_DIR, ("js",))):
            try:
                names = sorted(os.listdir(d))
            except Exception:
                continue
            for n in names:
                p = os.path.join(d, n)
                if not os.path.isfile(p) or n.endswith(".tmp"):
                    continue
                ext = n.rsplit(".", 1)[-1].lower() if "." in n else ""
                if ext in exts:
                    code = _read_text_file(p)
                    if code is None:
                        continue
                    kind = "py" if ext == "py" else ("tool" if d == BADI_TOOL_DIR else "indicator")
                    items.append({"fileName": n, "kind": kind, "code": code, "path": p})
                elif ext == "badi":
                    items.append({"fileName": n, "kind": "badi", "code": "", "path": p})
        return items

    def _write_entry_to_disk(self, f):
        """Write a user file code to its real path in BadiCharts — returns the path or None."""
        kind = self._norm_kind(f.get("kind"))
        name = _safe_file_name(f.get("fileName"))
        if not name or kind == "badi" or not str(f.get("code") or "").strip():
            return None
        path = os.path.join(_disk_dir_for(kind), name)
        return path if _write_text_file(path, f.get("code", "")) else None

    def _delete_entry_from_disk(self, f):
        """Delete a user file from disk (its source or its encrypted file)."""
        kind = self._norm_kind(f.get("kind"))
        name = _safe_file_name(f.get("fileName"))
        if not name:
            return
        p = f.get("path") if kind == "badi" else os.path.join(_disk_dir_for(kind), name)
        for cand in (p, os.path.join(BADI_IND_DIR, name), os.path.join(BADI_TOOL_DIR, name)):
            try:
                if cand and os.path.isfile(cand):
                    os.remove(cand)
                    break
            except Exception:
                pass

    def syncDiskFiles(self, emit=True):
        """Sync the file list with the BadiCharts folder:
        imports manually dropped files, updates changed code, adopts legacy files,
        pairs .badi files next to their originals, and removes what was deleted from the folder."""
        _ensure_badi_dirs()
        disk = self._disk_scan()
        changed = False
        # Disk index: (clean name, kind) → item
        disk_map = {}
        for it in disk:
            disk_map[(it["fileName"].lower(), it["kind"])] = it
        # 1) Adopt/update user files already in the list
        for f in self._files:
            kind = self._norm_kind(f.get("kind"))
            if kind == "badi":
                continue
            name = _safe_file_name(f.get("fileName"))
            if not name:
                continue
            it = disk_map.get((name.lower(), kind))
            if it is not None:
                if f.get("code") != it["code"]:      # The disk is the reference (external edit)
                    f["code"] = it["code"]
                    changed = True
            elif str(f.get("code") or "").strip():
                self._write_entry_to_disk(f)          # Adopt: a legacy file not on disk yet
        # 2) Import new files from the folder (files the user dropped manually)
        have = set()
        for f in self._files:
            have.add((_safe_file_name(f.get("fileName")).lower(), self._norm_kind(f.get("kind"))))
        for (nl, kind), it in disk_map.items():
            if (nl, kind) in have:
                continue
            self._files.append({"id": self._new_file_id(kind), "fileName": it["fileName"],
                                "kind": kind, "code": it.get("code", ""), "enabled": False,
                                "createdAt": int(time.time() * 1000), "path": it.get("path", "")})
            changed = True
        # 3) Remove what no longer exists on disk (manual deletion from the folder)
        keep = []
        for f in self._files:
            kind = self._norm_kind(f.get("kind"))
            name = _safe_file_name(f.get("fileName"))
            if kind == "badi":
                p = f.get("path") or ""
                if p and not os.path.isfile(p) and not os.path.isfile(os.path.join(BADI_IND_DIR, name)):
                    changed = True
                    continue
            else:
                if name and not any(os.path.isfile(os.path.join(d, name))
                                    for d in (BADI_IND_DIR, BADI_TOOL_DIR)):
                    changed = True
                    continue
            keep.append(f)
        self._files = keep
        # 4) Ordering: a .badi file shows right next to its original (like MetaTrader) — the rest keep their order
        twins = {}
        rest = []
        for f in self._files:
            if self._norm_kind(f.get("kind")) == "badi":
                base = _safe_file_name(f.get("fileName")).rsplit(".", 1)[0].lower()
                twins.setdefault(base, []).append(f)
            else:
                rest.append(f)
        ordered = []
        for f in rest:
            ordered.append(f)
            base = _safe_file_name(f.get("fileName")).rsplit(".", 1)[0].lower()
            if base in twins:
                ordered.extend(twins.pop(base))
        for v in twins.values():
            ordered.extend(v)
        if ordered != self._files:
            self._files = ordered
            changed = True
        if changed:
            _write_json(FILES_FILE, self._files)
            if emit:
                self.filesChanged.emit()
            self.myIndsChanged.emit()          # Update "my indicators" on the indicators page
        return changed

    # ---------- Files ----------
    @Slot(str)
    def saveFiles(self, files_json):
        try:
            data = json.loads(files_json)
            if isinstance(data, dict) and isinstance(data.get("files"), list):
                data = data["files"]          # The page report arrives wrapped as {v, files}
            if not isinstance(data, list):
                return
            old = {f.get("id"): f for f in self._files if isinstance(f, dict)}
            new = []
            for f in data:
                if not isinstance(f, dict) or not isinstance(f.get("id"), str):
                    continue
                f = dict(f)
                f["kind"] = self._norm_kind(f.get("kind"))
                f["fileName"] = _safe_file_name(f.get("fileName"))
                new.append(f)
            # Delete from disk: files that vanished from the list or were renamed
            new_ids = {f["id"] for f in new}
            for fid, of in old.items():
                if fid in new_ids:
                    nf = next((x for x in new if x["id"] == fid), None)
                    if nf and _safe_file_name(nf.get("fileName")) != _safe_file_name(of.get("fileName")):
                        self._delete_entry_from_disk(of)   # Renamed → delete the old name
                else:
                    self._delete_entry_from_disk(of)       # Deleted from the editor → delete from disk
            # Write every file to its real path (only when the code changed — to avoid redundant writes)
            for f in new:
                p = _disk_path_for(f) if self._norm_kind(f.get("kind")) != "badi" else None
                if p:
                    old_code = _read_text_file(p)
                    if old_code != f.get("code", ""):
                        self._write_entry_to_disk(f)
            self._files = new
            _write_json(FILES_FILE, self._files)
            self.myIndsChanged.emit()          # Update "my indicators" on the indicators page
        except Exception as e:
            self._log("err", f"save: {e}")

    @Slot()
    def rescanFiles(self):
        """Scan the BadiCharts folder and import any new files the user dropped manually."""
        if self.syncDiskFiles():
            self._log("info", "BadiCharts folder synced — indicators/tools reloaded")
        self.myIndsChanged.emit()

