    def _on_dir_changed(self, _path):
        """The user added/removed a file in the BadiCharts folder — instant detection (user request).
        A short delay lets the copy finish, then a rescan updates the indicators page."""
        try:
            self._watcher.addPath(BADI_IND_DIR)
            self._watcher.addPath(BADI_TOOL_DIR)
        except Exception:
            pass
        QTimer.singleShot(450, self._rescan_after_change)

    def _rescan_after_change(self):
        changed = self.syncDiskFiles()
        if changed:
            self._log("info", "BadiCharts folder synced — indicators/tools reloaded")
        self.myIndsChanged.emit()

    # ---------- My indicators on the indicators page + thumbnails (user request) ----------
    def _thumb_index(self):
        """Thumbnail index: indicator name without extension (lowercase) → image path."""
        idx = {}
        try:
            for n in os.listdir(BADI_THUMB_DIR):
                base, ext = os.path.splitext(n)
                if ext.lower() in (".jpg", ".jpeg", ".png"):
                    idx[base.lower()] = os.path.join(BADI_THUMB_DIR, n)
        except Exception:
            pass
        return idx

    @Property(str, notify=myIndsChanged)
    def myIndsJson(self):
        """All your indicators and tools (encrypted .badi too) — shown on the indicators page."""
        items = []
        thumbs = self._thumb_index()
        for f in self._files:
            kind = self._norm_kind(f.get("kind"))
            name = _safe_file_name(f.get("fileName"))
            if not name:
                continue
            base = name.rsplit(".", 1)[0].lower()
            items.append({"fileName": name, "kind": kind, "enc": kind == "badi",
                          "thumb": thumbs.get(base, "")})
        return json.dumps(items, ensure_ascii=False)

    @Slot(str, str)
    def saveIndThumb(self, file_name, data_url):
        """Indicator screenshot: saved on explicit save/run and refreshed every time (user request).
        Never captured unless the user actually saved/ran the indicator."""
        try:
            base = _safe_file_name(file_name).rsplit(".", 1)[0]
            if not base or not isinstance(data_url, str):
                return
            if ";base64," not in data_url or "," not in data_url:
                return
            raw = base64.b64decode(data_url.split(",", 1)[1], validate=False)
            if len(raw) < 512 or len(raw) > 2_000_000:   # High-resolution compressed screenshot — the cap was raised with the resolution
                return
            os.makedirs(BADI_THUMB_DIR, exist_ok=True)
            path = os.path.join(BADI_THUMB_DIR, base + ".jpg")
            tmp = path + ".tmp"
            with open(tmp, "wb") as fh:
                fh.write(raw)
            os.replace(tmp, path)
            self.myIndsChanged.emit()
        except Exception:
            pass

    @Slot(str)
    def delMy(self, file_name):
        """Delete an indicator from the my-indicators cards (trash icon beside the name — user request):
        deletes the file from disk with its sibling .badi and the thumbnail, then syncs the list."""
        try:
            name = _safe_file_name(str(file_name))
            if not name:
                return
            base = name.rsplit(".", 1)[0].lower()
            removed = False
            for d in (BADI_IND_DIR, BADI_TOOL_DIR, BADI_DIR):
                try:
                    if not os.path.isdir(d):
                        continue
                    for n in os.listdir(d):
                        low = n.lower()
                        if low == name.lower() or (os.path.splitext(n)[0].lower() == base and low.endswith(".badi")):
                            try:
                                os.remove(os.path.join(d, n))
                                removed = True
                            except Exception:
                                pass
                except Exception:
                    pass
            try:
                if os.path.isdir(BADI_THUMB_DIR):
                    for n in os.listdir(BADI_THUMB_DIR):
                        if os.path.splitext(n)[0].lower() == base:
                            try:
                                os.remove(os.path.join(BADI_THUMB_DIR, n))
                            except Exception:
                                pass
            except Exception:
                pass
            if removed:
                # Strike the entry from the list before syncing so syncDiskFiles does not write it back to disk
                try:
                    self._files = [f for f in self._files
                                   if not (_safe_file_name(f.get("fileName")).lower() == name.lower()
                                           or (_safe_file_name(f.get("fileName")).rsplit(".", 1)[0].lower() == base
                                               and self._norm_kind(f.get("kind")) == "badi"))]
                except Exception:
                    pass
                self.syncDiskFiles()
                self.myIndsChanged.emit()
                self.filesChanged.emit()
                self._log("info", "🗑 Deleted indicator: " + name)
        except Exception:
            pass

    @Slot(str, str, result=str)
    def shareIndicator(self, file_name, chat_id):
        """Send button (owner plan v2): the indicator file itself goes through the bot —
        Telegram sendDocument to the chat id typed in the share card; the last used
        chat id is remembered and pre-filled next time."""
        try:
            name = _safe_file_name(file_name)
            ent = next((f for f in self._files
                        if _safe_file_name(f.get("fileName")).lower() == name.lower()), None)
            kind = self._norm_kind((ent or {}).get("kind"))
            path = ""
            if kind == "badi":
                p = (ent or {}).get("path") or ""
                if p and os.path.isfile(p):
                    path = p
            if not path:
                for d in (BADI_IND_DIR, BADI_TOOL_DIR):
                    cand = os.path.join(d, name)
                    if os.path.isfile(cand):
                        path = cand
                        break
            if not path and ent is not None and kind != "badi" and str(ent.get("code") or "").strip():
                if self._write_entry_to_disk(ent):
                    path = os.path.join(_disk_dir_for(kind), name)
            if not path or not os.path.isfile(path):
                return json.dumps({"ok": False, "error": BADI_MSGS[self._lang]["short"]})

            cfg = _read_json(CFG_FILE, {})
            token = cfg.get("token", "")
            chat_id = str(chat_id or "").strip()
            if not token:
                return json.dumps({"ok": False, "error": "telegram not configured — save the bot token first"})
            if not chat_id:
                return json.dumps({"ok": False, "error": "chat id is empty"})

            # Remember the last chat id (pre-filled by the share card next time)
            cfg["shareChat"] = chat_id
            _write_json(CFG_FILE, cfg)

            def run():
                try:
                    n, errs = _tg_send_document(token, chat_id, path, os.path.basename(path))
                    self._log("ok", f"Indicator file → Telegram ({n} chat)")
                except Exception as e:
                    self._log("err", f"share: {str(e)[:100]}")
            threading.Thread(target=run, daemon=True).start()
            return json.dumps({"ok": True, "path": path})
        except Exception as e:
            return json.dumps({"ok": False, "error": str(e)[:120]})

    @Slot(result=str)
    def lastShareChat(self):
        return str(_read_json(CFG_FILE, {}).get("shareChat", ""))

    @Slot(result=str)
    def badiDirPath(self):
        """BadiCharts folder path for display in Settings."""
        return BADI_DIR

    @Slot(str, result=str)
    def makeFile(self, kind):
        sfx = random_suffix(6)
        ext = "py" if kind == "py" else "js"
        code = {"js": JS_IND_TEMPLATE, "py": PY_IND_TEMPLATE, "jstool": JS_TOOL_TEMPLATE}[kind]
        base = {"js": "My Indicator", "py": "Python Indicator", "jstool": "My Tool"}[kind]
        norm = self._norm_kind(kind)
        # Unique name within the same kind — so two files with the same name never collide on disk
        taken = {(str(f.get("fileName") or "").lower(), self._norm_kind(f.get("kind")))
                 for f in self._files}
        fname, n = f"{base}.{ext}", 2
        while (fname.lower(), norm) in taken:
            fname = f"{base} ({n}).{ext}"
            n += 1
        f = {"id": kind + "_" + sfx.lower(), "fileName": fname,
             "kind": norm, "code": code, "enabled": False}
        self._write_entry_to_disk(f)          # Saved immediately into the BadiCharts folder
        self._files.append(f)
        self.filesChanged.emit()
        self.myIndsChanged.emit()
        _write_json(FILES_FILE, self._files)
        return json.dumps(f)

    @Slot(str, result=str)
    def addFromLib(self, key):
        """Add a library indicator: a new file named after the library entry + immediate run."""
        item = next((l for l in LIB if l["key"] == key), None)
        if not item:
            return "{}"
        sfx = random_suffix(6)
        f = {"id": "js_" + sfx.lower(), "fileName": f"{item['name']}.js",
             "kind": "indicator", "code": item["code"], "enabled": False}
        self._write_entry_to_disk(f)          # Saved immediately into the BadiCharts folder
        self._files.append(f)
        self.filesChanged.emit()
        self.myIndsChanged.emit()
        _write_json(FILES_FILE, self._files)
        return json.dumps(f)

    @Slot()
    def saveAll(self):
        _write_json(FILES_FILE, self._files)
        self._log("ok", T[self._lang]["savedall"])

    # ---------- Symbol / timeframe / feed ----------
    @Slot(str, str)
    def switch(self, asset, tf):
        # v3.0.8 (أمر المالك: «الشارت الذي تنشاه مجهول الهوية يجب ان تتبع شروط
        # التطبيق»): ضغطة العملة في الصفحة تمر بشروط فتح التطبيق نفسها — الاسم
        # يُحلّ عبر اللوحة (حرفي → طبيعي → كود) مثل مطابقة وصول اللوحة، فتُفتح
        # شارت العملة في التطبيق فعليًا وتصل الشموع عبر syncFull. بلا مطابقة
        # تبقى هوية التطبيق الحالية هي المرجع (لا هوية مجهولة).
        resolved = self._resolve_board_name(asset)
        if resolved:
            self._asset = resolved
        self._tf = tf if tf in dict(TFS) else self._tf
        self._market = "otc" if "OTC" in self._asset else "real"
        self._save_cfg()
        self._dec_live = 0
        # v3.0.0 (الدمج): متصلًا يجلب المحرك شموع المنصة الحقيقية للعملة/الفريم
        # (700 شمعة افتراضيًا)؛ وبلا اتصال يفرغ الرسم برسالة صادقة (المولّد القديم
        # يبقى للاختبار فقط عبر BADI_DEMO_CANDLES=1)
        self._candles = generate_candles(self._asset, self._tf) if DEMO_CANDLES_OK else []
        self._tick = 0
        if self._engine_online():
            row = self._board_row(self._asset)
            if row and row.get("code"):
                # نفس آلية صفحة المتصفح: on-demand للعملة + عمق الفريم (700 شمعة)
                BRIDGE.app_switch(str(row.get("code")), self._tf, self._asset)
        elif not DEMO_CANDLES_OK:
            self._log("info", "سجّل الدخول لجلب الشموع الحقيقية من المنصة"
                      if self._lang == "ar" else
                      "Sign in to load real candles from the platform")
        # Recalculate every active Python indicator on the new candles immediately
        # (instead of waiting for the first tick — otherwise the line vanished because the old values fell outside the new price range)
        # Order matters: values first, then push — indicator values arrive with the candles in the same instant
        # v3.0.56: بوابات الدفعات تُصفَّر هنا — أول دفعة حقيقية للعملة/الفريم
        # الجديدين تحسب فورًا لا بعد ثانية (البوابة نفسها من v3.0.56 باقية)
        self._py_batch_gate = 0.0
        if self._py_mods:
            self._compute_py()
        self.candlesChanged.emit()

    @Slot(str, result=str)
    def assetsFor(self, market):
        """Currency names by market: the live platform board when connected (OTC per row),
        the local lists before that."""
        if self._board and any(r.get("code") for r in self._board):
            names = [r["name"] for r in self._board
                     if (market == "otc") == bool(r.get("otc") or str(r.get("code", "")).lower().endswith("_otc"))]
            if names:
                return json.dumps(names)
        return json.dumps([a["name"] for a in ASSETS.get(market, [])])

    # ---------- سرفر الشموع المدمج: الدخول والخروج ووصول الشموع (v3.0.1) ----------
    # خريطة القنوات (QML ↔ Backend ↔ BRIDGE) — كل سهم باتجاه واحد ولا يلمس خيط
    # الواجهة شبكة ولا مخازن أبدًا (الجسر في نهاية الجزء الثالث، والسرفر نفسه
    # لم يُمس — أمر المالك: «تدمج هذا كما هو»):
    #   QML (واجهة الدخول) ── qxLogin/qxPinCode/qxLogout ──► Backend ──► BRIDGE
    #   BRIDGE ── result_cb ──► loginDone ──► _engine_login_done ──► سطر الخطأ/فتح الاستوديو
    #   BRIDGE ── board_cb  ──► boardReady ──► _engine_board ──► boardChanged ──► الصفحة setBoard
    #   BRIDGE ── candle_cb ──► candlesReady ──► _engine_candles ──► candlesChanged ──► QML onCandlesWeb
    #   BRIDGE ── state_cb  ──► qxEngineState ──► _engine_state ──► الصفحة + الشريط
    #   BRIDGE ── log_cb    ──► logLine ──► _engine_log ──► consoleMsg ──► كونسول التطبيق
    _QX_ERR_AR = {
        "The candles server session dropped — sign in again":
            "انقطعت جلسة سرفر الشموع — سجّل الدخول من جديد",
        "Sign-in failed — check your email and password":
            "فشل الدخول — تحقق من البريد وكلمة المرور",
        "PIN code required (sent to your email)":
            "مطلوب رمز التحقق — أُرسل إلى بريدك الإلكتروني",
        "PIN code wrong or expired — enter the code and sign in again":
            "الرمز غير صحيح أو انتهت مهلته — أدخل الرمز وأعد الدخول",
    }
    def _engine_online(self):
        return self._qx_state in ("online", "lost")

    def _sync_watchlist(self):
        """أبلغ الجسر بعملات الشريط — تحميل on-demand لمن ليس لديه بيانات فقط
        (نفس آلية صفحة المتصفح، بحد حماية ENGINE_WATCH_MAX)."""
        if self._engine_online():
            codes = []
            for n in self._added:
                row = self._board_row(n)
                if row and row.get("code"):
                    codes.append(str(row["code"]))
            try:
                BRIDGE.set_watchlist(codes)
            except Exception:
                pass

    @Slot(str, str, bool)
    def qxLogin(self, email, password, remember):
        """واجهة الدخول كما هي (أمر المالك) — تشغّل السرفر نفسه (server_main) بالبيانات."""
        if self._qx_busy:
            return
        self._qx_error = ""
        self._qx_busy = True
        self.qxBusyChanged.emit()
        self.qxErrorChanged.emit()
        try:
            BRIDGE.app_login(str(email or "").strip(), str(password or ""), bool(remember))
        except Exception as e:
            self._qx_busy = False
            self.qxBusyChanged.emit()
            self._engine_login_done(False, "Sign-in failed — " + str(e)[:120])

    @Slot(str)
    def qxPinCode(self, code):
        """رمز الجهاز الجديد: يصل بالإيميل ويُسلّم لمحاولة الدخول المنتظرة نفسها."""
        if self._qx_busy:
            return
        self._qx_error = ""
        self._qx_busy = True
        self.qxBusyChanged.emit()
        self.qxErrorChanged.emit()
        try:
            BRIDGE.submit_pin(str(code or "").strip())
        except Exception as e:
            self._qx_busy = False
            self.qxBusyChanged.emit()
            self._engine_login_done(False, "Sign-in failed — " + str(e)[:120])

    @Slot()
    def qxLogout(self):
        """الخروج: إيقاف دفع الشموع والعودة إلى اللوحة المحلية — اتصال السرفر
        يبقى كما هو (السرفر الأصلي بلا دالة قطع — لا شيء يتغير في كوده)."""
        try:
            BRIDGE.app_logout()
        except Exception:
            pass
        self._qx_error = ""
        self.qxErrorChanged.emit()
        # v3.0.9 (أمر المالك: «عندما نسجل الخروج لا يمكننا تسجيل دخول مرة
        # اخرى لماذا»): الخروج كان يترك آلة الدخول كما هي — محاولة معلّقة
        # (busy=True) تعطّل زر «دخول» للأبد، وحالة auth قديمة تحوّل النموذج
        # إلى حقل الرمز بلا منتظر. الآن يصفر الخروج الحالة كاملة: الزر حر
        # والواجهة جاهزة لدخول جديد من أول ضغطة.
        self._qx_busy = False
        self._qx_state = "noserver"
        self.qxBusyChanged.emit()
        self.qxStateChanged.emit()
        self._board = list(BOARD)
        self._board_codes = {}
        self._dec_live = 0
        self._candles = generate_candles(self._asset, self._tf) if DEMO_CANDLES_OK else []
        self._tick = 0
        self.boardChanged.emit()
        self.candlesChanged.emit()

    def _engine_log(self, kind, text):
        self._log(str(kind or "info"), str(text))

    def _engine_state(self, st):
        st = str(st or "noserver")
        if st != self._qx_state:
            self._qx_state = st
            self.qxStateChanged.emit()

    def _engine_login_done(self, ok, err):
        self._qx_busy = False
        self.qxBusyChanged.emit()
        if ok:
            self._qx_error = ""
            self._log("ok", "تم الدخول — سرفر الشموع يعمل داخل التطبيق"
                      if self._lang == "ar" else
                      "Signed in — the candles server runs inside the app")
        else:
            err = str(err or "Sign-in failed")
            if self._lang == "ar":
                err = _QX_ERR_AR.get(err, err)
            self._qx_error = err
            self.qxErrorChanged.emit()

    def _engine_board(self, js):
        """وصلت قائمة العملات من السرفر (أمر المالك: «تضيف ارسال قائمة العملات الى
        قائمة التطبيق»): صفوف instruments الخام → qx_build_board (الاسم + الكود +
        نسبة الدفع + مفتوح/مغلق + العلمان) ثم تحل محل اللوحة المحلية."""
        try:
            instruments = json.loads(js)
        except Exception:
            return
        if not isinstance(instruments, list) or not instruments:
            return
        try:
            rows = qx_build_board(instruments)
        except Exception:
            rows = []
        if not rows:
            return
        self._board = rows
        self._board_codes = {r["name"]: r.get("code", "") for r in rows if isinstance(r, dict)}
        # v3.0.6 (أمر المالك): USDDZD_otc أولًا في اللوحة الحقيقية أيضًا — هي شارت
        # الإقلاع الافتراضي والشريط يرتب حسب ترتيب اللوحة
        for _i, _r in enumerate(rows):
            if str(_r.get("code", "")).lower() == "usddzd_otc" and _i:
                rows.insert(0, rows.pop(_i))
                break
        # مطابقة طبيعية (بلا فراغات/فواصل/أقواس/حالة أحرف): "USD/DZD OTC" ≡
        # "USDDZD_otc" — وإن لم توجد تطابقًا فالاحتياط الثابت صف USDDZD_otc
        # (أمر المالك: «يجب ان يفتح على USDDZD_otc ذالك هو لي اخر جلب شموع»)
        if self._asset not in self._board_codes:
            def _nn(s):
                return re.sub(r"[\s/_\-()]+", "", str(s or "")).lower()
            want = _nn(self._asset)
            row2 = next((r for r in rows if _nn(r.get("name")) == want), None)
            if row2 is None and want == _nn("USD/DZD OTC"):
                row2 = next((r for r in rows if str(r.get("code", "")).lower() == "usddzd_otc"), None)
            if row2 is None:
                row2 = next((r for r in rows if r.get("otc")), None)
            if row2 is not None:
                self._asset = row2["name"]
        # الشريط يبقى صالحًا مع القائمة الحية + العملة الحالية أولًا فيه
        self._added = [n for n in self._added if n in self._board_codes]
        if self._asset and self._asset not in self._added:
            self._added = [self._asset] + self._added
        self._save_cfg()
        self.boardChanged.emit()
        self.addedChanged.emit()
        # تشغيل فوري: العملة الحالية + عملات الشريط (تحميل on-demand بنفس آلية
        # صفحة المتصفح) — والعملة الافتراضية USDDZD_otc تجلبها حلقة الجلب الأصلية.
        # v3.0.10: بلا شرط الحالة — ترتيب إشارتَي «online» ووصول اللوحة بين
        # الخيوط غير مضمون (قد تسبق اللوحة فيبقى التبديل بلا أثر والشارت
        # فارغًا حتى ضغطة يدوية). app_switch يحدّث تسمية البولر أولًا ثم
        # يتحقق من الاتصال الحقيقي قبل أي طلب، و_sync_watchlist يتحقق
        # داخليًا — فالنداء هنا آمن في كل حالة.
        row = self._board_row(self._asset)
        if row and row.get("code"):
            BRIDGE.app_switch(str(row.get("code")), self._tf, self._asset)
        self._sync_watchlist()
        self._log("info", f"[board] rows={len(rows)} asset={self._asset!r} "
                  f"switch={'yes' if (row and row.get('code')) else 'no'}")

    def _engine_candles(self, js):
        """وصلت شموع حقيقية من الجسر — تُرسم إن كانت للعملة/الفريم الحاليين.
        العلم nc (من الجسر): هذه الدفعة بدأت شمعة جديدة (لفّ الشمعة) — إشارة
        أحادية candleRolledNow تُطلق مرة واحدة هنا فقط، فتعيد الصفحة رسم النافذة
        كاملة مع حفظ العرض. (v3.0.3: لا علم لاصق — العلم اللاصق مع انبعاث المؤقت
        كل ثانية كان يغرق الصفحة باستبدال كامل كل ثانية فيتجمد السعر الحي.)"""
        try:
            BRIDGE._cb_pending = 0.0     # v3.0.23: الدفعة استُهلكت — البولر يرسل التالية
        except Exception:
            pass
        try:
            d = json.loads(js)
        except Exception:
            return
        # v3.0.10 (أمر المالك: «لم يفتح شارت عملة USDDZD OTC … زر البطاقة ليس
        # ازرق»): بعد الدخول كان الفتح التلقائي يتجمد — لوحة المنصة الحقيقية
        # تصل بأسماء غير اسم العرض المحلي، وإن سبقت إشارةَ «online» بقي
        # البولر يدفع بتسمية الإقلاع الافتراضية بينما صار اسم العملة الحالية
        # هو اسم الصف الحقيقي، فتُرفض كل دفعة ويبقى الشارت فارغًا والبطاقة
        # بلا أزرق حتى ضغطة يدوية. الآن: الدفعة التي لعبة أخرى بالتطابق
        # الطبيعي (بلا فراغات/فواصل/حالة أحرف) تُقبل كأنها للعملة نفسها —
        # فتصل الشموع ويشتغل syncFull وتضيء البطاقة تلقائيًا كأن المستخدم
        # ضغطها.
        def _nnx(s):
            return re.sub(r"[\s/_\-()]+", "", str(s or "")).lower()
        if str(d.get("tf")) != self._tf:
            return          # شموع فريم آخر — الرسم الحالي لا يتأثر
        if str(d.get("asset")) != self._asset and _nnx(d.get("asset")) != _nnx(self._asset):
            # v3.0.11: تسمية الدفعة قد تكون مفتاح المخزن (USDDZD-OTCq) حين يغيب اسم
            # العرض — قارن عبر عكس تحويل الكود قبل الرفض، وسجّل سبب الرفض مرة واحدة
            try:
                _lbl_api = _pair_name_to_api(str(d.get("asset") or ""))
            except Exception:
                _lbl_api = ""
            if _nnx(_lbl_api) != _nnx(self._asset):
                _rk = (str(d.get("asset")), str(self._asset), str(d.get("tf")))
                if getattr(self, "_last_rej", None) != _rk:
                    self._last_rej = _rk
                    self._log("info", f"[candles] rejected: label={_rk[0]!r} tf={_rk[2]} ≠ asset={_rk[1]!r}")
                return      # شموع عملة أخرى فعلًا — الرسم الحالي لا يتأثر
        candles = d.get("candles") or []
        if not candles:
            return
        self._dec_live = int(d.get("digits") or 0)
        self._candles = candles
        # v3.0.56 (owner request: «التطبيق لا يستطيع العمل تحت السرعة مثلا المستخدم
        # حرك الفارة بسرعة الى زر ما ذلك لا يعمل في تلك اللحضة وقد يحدث بلوك نحن
        # نريده ان يكون خفيف في الاستخدام دون ما يحدث لاج»): مؤشرات بايثون كانت
        # تُحسب مع كل دفعة جسر (حتى 20 مرة/ثانية عند حركة OTC السريعة) على خيط
        # الواجهة — العكس التام لبوابة v3.0.14 نفسها («المؤشرات عمل ثقيل — كل
        # ثانية واحدة عبر بوابة زمنية — لا ثمن CPU») المطبقة في _on_tick. البوابة
        # نفسها هنا: أول دفعة تحسب فورًا، ثم مرة كل ثانية كحد أقصى — القيم على
        # الشارت تبقى حية بإيقاع الثانية (تصميم v3.0.14) وإشارات _maybe_fire
        # تحتفظ بإيقاعها عبر _on_tick. بلا مؤشرات بايثون: لا شيء يتغير إطلاقًا.
        if self._py_mods and (time.monotonic() - getattr(self, "_py_batch_gate", 0.0) >= 1.0):
            self._py_batch_gate = time.monotonic()
            self._compute_py()
        self.candlesChanged.emit()
        if d.get("nc"):
            self.candleRolledNow.emit()   # مرة واحدة عند بدء الشمعة الجديدة فقط

    @Slot(bool)
    def setLive(self, on):
        # Live feed is now permanent (user request) — it cannot be stopped from the page
        if not self._live:
            self._live = True
            self.liveChanged.emit()
            self._log("info", "Live feed started — " + self._asset + " " + self._tf)

    def _on_tick(self):
        # Live feeding runs only while live is on; signal/trade settlements always run
        if self._live:
            if DEMO_CANDLES_OK:     # قرار المالك: بلا سرفر ولا BADI_DEMO_CANDLES=1 لا محاكاة إطلاقًا
                cfg = self._asset_cfg()
                tf = max(5, self._tf_sec())
                # New candle when the timeframe boundary passes in real time, not by tick count since boot —
                # drifting off real minute boundaries used to stick the countdown at 00
                # for the rest of the minute (it worked on the first candle then stopped — user note)
                now = int(time.time())
                boundary = now - (now % tf)
                cur = self._candles[-1]
                if cur["t"] < boundary:
                    # The timeframe really ended — close the candle and open a candle at the true boundary,
                    # and fill any gap if a tick arrived late (system sleep/suspend), capped at 500 candles
                    gap = min(int((boundary - cur["t"]) // tf), 500)
                    for _ in range(gap):
                        self._candles.append(new_candle(self._candles[-1], tf, cfg["vol"]))
                    if len(self._candles) > 1500:
                        self._candles = self._candles[-1200:]
                else:
                    self._candles[-1] = step_candle(cur, cfg["vol"])
            # v3.0.3: لا انبعاث candlesChanged كل ثانية هنا — دفعات الجسر الحقيقية
            # (وإشارة لفّ الشمعة الأحادية candleRolledNow) هي التي تحرّك الشارت.
            # الانبعاث الدوري كان يعيد دفع آخر شمعة كل ثانية حتى بلا تغيير.
            # v3.0.14: المؤشرات عمل ثقيل — كل ثانية واحدة عبر بوابة زمنية
            _now_mono = time.monotonic()
            if _now_mono - getattr(self, "_last_slow_tick", 0.0) >= 1.0:
                self._last_slow_tick = _now_mono
                if self._candles:
                    self._compute_py()
        self._check_sig_results()

    # ---------- Python indicators ----------
    _SAFE_BUILTINS = {"abs": abs, "min": min, "max": max, "len": len, "range": range,
                      "float": float, "int": int, "round": round, "sum": sum, "enumerate": enumerate,
                      "zip": zip, "list": list, "dict": dict, "sorted": sorted, "pow": pow,
                      "True": True, "False": False, "None": None}

    def _compile_py(self, f):
        mod = {}
        try:
            gl = dict(self._SAFE_BUILTINS)
            gl.update(PY_HELPERS)
            # Pin the builtins explicitly: exec() would otherwise inject the REAL builtins
            # dict into globals when the key is missing — and then import/open/os/network
            # were all reachable from an indicator script (the "sandbox" was cosmetic).
            # With __builtins__ set to the safe set only, import raises ImportError and
            # the closed-sandbox promise in the Python guide is actually true.
            gl["__builtins__"] = dict(self._SAFE_BUILTINS)
            exec(f["code"], gl)          # noqa: S102 — restricted local sandbox
            for req in ("LABEL", "TYPE", "SETTINGS", "calculate"):
                if req not in gl:
                    raise ValueError(f"missing {req}")
            mod = {k: gl[k] for k in ("LABEL", "TYPE", "SETTINGS", "calculate")
                   if k in gl}
            mod["signal"] = gl.get("signal")
            mod["get_range"] = gl.get("get_range")
            self._py_err[f["id"]] = 0
            self._py_slow.pop(f["id"], None)      # BSE: fresh start — strikes reset on (re)compile
            return mod, None
        except Exception as e:
            return None, str(e)

    def _enabled_files(self, kind):
        return [f for f in self._files if f.get("enabled") and f.get("kind") == kind]

    def _bse_disable_py(self, mid, why):
        """BSE Layer 1 — real auto-disable of a violating Python indicator: the module is
        removed, the file record is switched off and persisted (it stays off after a restart
        until the user re-enables it), the stale series leaves the chart, and the audit
        trail records the event without any script content."""
        name = self._py_names.get(mid, mid)
        self._py_mods.pop(mid, None)
        self._py_slow.pop(mid, None)
        self._py_err.pop(mid, None)
        flipped = False
        for f in self._files:
            if isinstance(f, dict) and f.get("id") == mid and f.get("enabled"):
                f["enabled"] = False
                flipped = True
        if flipped:
            _write_json(FILES_FILE, self._files)
            self.filesChanged.emit()              # the page re-reads the list — the switch shows OFF
        self.pyStopped.emit(mid)                  # the page drops the stale series from the chart
        self._log("err", "BSE: " + str(name) + " disabled — " + str(why))
        _bse_audit("py-budget-disable", str(name)[:40] + " — " + str(why)[:70])

    def _compute_py(self):
        for mid, mod in list(self._py_mods.items()):
            try:
                # BSE Layer 1 — per-call CPU budget: calculate() runs under a 3-second trace
                # watchdog. A stuck pure-Python loop never returns, so measuring only after
                # the return would never fire — the watchdog kills it mid-flight instead;
                # native-heavy calls the tracer cannot stop are measured after the return.
                t0 = time.perf_counter()
                res = _bse_budget_call(mod["calculate"], self._candles, dict(mod["SETTINGS"]))
                dt = time.perf_counter() - t0
                if dt > _BSE_BUDGET_SEC:
                    # returned but slow — strike; the strike window disables on repeat
                    now = time.monotonic()
                    last, n = self._py_slow.get(mid, (0.0, 0))
                    if now - last > BSE_LIMITS["py_slow"][1]:
                        n = 0
                    self._py_slow[mid] = (now, n + 1)
                    if n + 1 > BSE_LIMITS["py_slow"][0]:
                        self._bse_disable_py(mid, "calculate took %.1fs repeatedly (budget %.0fs)" % (dt, _BSE_BUDGET_SEC))
                        continue
                    self._log("info", "BSE: " + str(self._py_names.get(mid, mid))
                              + " calculate took %.1fs (budget %.0fs) — strike %d/%d"
                              % (dt, _BSE_BUDGET_SEC, n + 1, BSE_LIMITS["py_slow"][0]))
                else:
                    self._py_slow[mid] = (time.monotonic(), 0)   # a fast clean call forgives strikes
                if isinstance(res, (list, tuple)):
                    res = {"Value": list(res)}
                series = {}
                rng = None
                for k, arr in res.items():
                    # BSE Layer 1: output cap — a script returning a huge array cannot blow memory
                    if not isinstance(arr, (list, tuple)):
                        arr = list(arr)
                    if len(arr) > BSE_MAX["py_series"]:
                        arr = arr[:BSE_MAX["py_series"]]
                    series[k] = [None if (x is None or x != x) else round(float(x), 8) for x in arr]
                if mod.get("get_range") and str(mod.get("TYPE")) == "pane":
                    r = _bse_budget_call(mod["get_range"], series)
                    rng = [float(r[0]), float(r[1])]
                self.pyValues.emit(mid, json.dumps(series), json.dumps(rng))
                if mod.get("signal"):
                    sig = _bse_budget_call(mod["signal"], self._candles, {k: v for k, v in series.items()})
                    self._maybe_fire(mid, self._py_names.get(mid, str(mod.get("LABEL", mid))), sig)
            except _BSEBudget:
                # the watchdog killed the call mid-flight — unambiguous runaway: disable at once
                self._bse_disable_py(mid, "killed at the %.0fs CPU budget (stuck/heavy loop in calculate)" % _BSE_BUDGET_SEC)
            except Exception as e:
                n = self._py_err.get(mid, 0) + 1
                self._py_err[mid] = n
                name = self._py_names.get(mid, mid)
                if n <= 2:
                    self._log("err", f"{name}: {e}")
                elif n == 3:
                    self._log("info", f"{name}: errors hidden (persistent)")

    @Slot(str, str, str, result=str)
    def compilePyOne(self, fid, file_name, code):
        """Translate a single Python indicator coming from the embedded web page."""
        f = {"id": fid, "fileName": file_name, "kind": "py", "code": code, "enabled": True}
        mod, err = self._compile_py(f)
        if err:
            self._py_mods.pop(fid, None)
            return json.dumps({"ok": False, "error": str(err)})
        self._py_mods[fid] = mod
        self._py_names[fid] = file_name
        self._py_err[fid] = 0
        self._py_slow.pop(fid, None)              # BSE: fresh start — strikes reset on (re)compile
        self._log("ok", f"{file_name} (Python) {T[self._lang]['compileok']}")
        return json.dumps({"ok": True, "label": str(mod["LABEL"]), "type": str(mod["TYPE"]),
                           "settings": mod["SETTINGS"]})

    @Slot(str, result=str)
    def libFile(self, key):
        """Library indicator code as a new file carrying the library name — created by the embedded web page."""
        item = next((l for l in LIB if l["key"] == key), None)
        if not item:
            return "{}"
        sfx = random_suffix(6)
        return json.dumps({"id": "ind_" + sfx.lower(), "fileName": f"{item['name']}.js",
                           "kind": "indicator", "code": item["code"], "enabled": False})

    def boot_files_json(self):
        """User files in web-page format (injected into the HTML at boot).
        Encrypted .badi files are listed next to their originals — decrypted only on click."""
        src = self._files
        if isinstance(src, dict) and isinstance(src.get("files"), list):
            src = src["files"]
        out = []
        for f in src:
            if not isinstance(f, dict):
                continue
            k = self._norm_kind(f.get("kind"))
            out.append({"id": f.get("id", ""), "fileName": f.get("fileName", ""),
                        "kind": k, "code": f.get("code", ""), "enabled": bool(f.get("enabled"))})
        return json.dumps({"files": out, "pyTemplate": PY_IND_TEMPLATE,
                           "badiDir": BADI_DIR,
                           "market": {"assets": self._board_names(),
                                      "board": self._board,
                                      "added": self._added,
                                      "tfs": [k for k, _ in TFS],
                                      "asset": self._asset, "tf": self._tf, "live": self._live}})

    @Slot(str, result=str)
    def compilePy(self, files_json):
        """Translate every active Python file — called after ▶ run on a py file."""
        try:
            data = json.loads(files_json)
        except Exception:
            data = []
        if isinstance(data, dict) and isinstance(data.get("files"), list):
            data = data["files"]
        norm = []
        for f in data if isinstance(data, list) else []:
            if isinstance(f, dict) and isinstance(f.get("id"), str):
                f = dict(f)
                f["kind"] = self._norm_kind(f.get("kind"))
                f["fileName"] = _safe_file_name(f.get("fileName"))
                norm.append(f)
        self._files = norm
        _write_json(FILES_FILE, self._files)
        out = {}
        for f in self._enabled_files("py"):
            mod, err = self._compile_py(f)
            if err:
                out[f["id"]] = {"ok": False, "error": err}
                self._log("err", f"{f['fileName']}: {err}")
            else:
                self._py_mods[f["id"]] = mod
                out[f["id"]] = {"ok": True, "label": str(mod["LABEL"]), "type": str(mod["TYPE"]),
                                "settings": mod["SETTINGS"]}
                self._log("ok", f"{f['fileName']} (Python) {T[self._lang]['compileok']}")
                self._compute_py()
        # Remove modules of stopped files
        for f in self._files:
            if not f.get("enabled") and f["id"] in self._py_mods:
                del self._py_mods[f["id"]]
        return json.dumps(out)

    # ---------- Signals ----------
    @Slot(str, str, str, float, str, str, float)
    def fireSignal(self, fid, label, dir_, price, asset="", chats="", stay=0.0):
        # asset: the signal currency (from the multi-currency scanner or the chart) — chats: chat ID from the indicator itself
        # stay: MINUTES the card stays on the Signals page (owner request) — 0 = the chart timeframe
        if not price and self._candles:
            price = self._candles[-1]["c"]
        self._maybe_fire(fid, label, {"dir": dir_, "price": float(price),
                                      "asset": str(asset or ""), "chats": str(chats or ""),
                                      "stay": stay})

    def _maybe_fire(self, fid, label, sig):
        if not sig or not sig.get("dir"):
            return
        # BSE Layer 2: field caps + per-file signal rate limit — a looping script cannot flood
        # the card or Telegram; every exceeded burst is audited
        if not BSE_RATE.allow("sig:" + str(fid)[:40], *BSE_LIMITS["signal"]):
            _bse_violation("signal-rate", "indicator fired too many signals")
            self._log("err", "BSE: signal rate limit reached for an indicator — paused for this minute")
            return
        label = str(label or "")[:80]
        sig["asset"] = str(sig.get("asset") or "")[:40]
        sig["chats"] = str(sig.get("chats") or "")[:BSE_MAX["chat_len"] * BSE_MAX["chats"]]
        asset = str(sig.get("asset") or self._asset or "")
        cfg = self._asset_cfg(asset)
        on_chart = (asset == self._asset and bool(self._candles))
        # Chart currency: current candle time — other currencies: last completed candle of the current timeframe
        now_bar = self._candles[-1]["t"] if on_chart else \
            (int(datetime.now().timestamp()) - int(datetime.now().timestamp()) % max(5, self._tf_sec()))
        key = fid + ":" + asset + ":" + self._tf
        last = self._fire_state.get(key)
        if last and last[0] == now_bar and last[1] == sig["dir"]:
            return
        self._fire_state[key] = (now_bar, sig["dir"])
        price = float(sig.get("price") or 0)
        if on_chart and not price:
            price = self._candles[-1]["c"]
        price_s = round(price, cfg["dec"])
        when = datetime.fromtimestamp(now_bar).strftime("%Y-%m-%d %H:%M:%S")
        chats = str(sig.get("chats") or "")
        self._send_signal(fid, label, sig["dir"], price_s, when, asset=asset, chats=chats)
        # The card stays on the Signals page for the duration the INDICATOR sets ("stay",
        # in minutes — owner request); the default is the chart timeframe. When it ends
        # the engine settles WIN/LOSS and the PAGE records the finished signal in its
        # saved History tab (owner order v3.0.49).
        try:
            _stay_m = float(sig.get("stay") or 0)
        except Exception:
            _stay_m = 0.0
        _dur_s = _stay_m * 60.0 if _stay_m > 0 else self._tf_sec()
        expiry = (datetime.fromtimestamp(now_bar) + timedelta(seconds=_dur_s)).timestamp()
        self._sigpend.append({"asset": asset, "tf": self._tf, "dir": sig["dir"],
                              "entry": float(price), "expiry": expiry, "label": label,
                              "vol": cfg["vol"], "dec": cfg["dec"], "chats": chats,
                              "at": now_bar})
        # The live card appears on the Signals page the instant the signal fires
        self.liveSigChanged.emit()

    _fire_state = {}

    def _check_sig_results(self):
        """Settle pending signals: compare the price at expiry with the entry price."""
        if not self._sigpend:
            return
        now = datetime.now().timestamp()
        still = []
        for sp in self._sigpend:
            if now < sp["expiry"]:
                still.append(sp)
                continue
            if self._candles and sp["asset"] == self._asset and self._live:
                exit_px = self._candles[-1]["c"]
            else:
                # Deterministic simulation sized by the asset volatility (demo data — works even without live)
                f = ((_hash(sp["asset"] + sp["tf"] + str(int(sp["expiry"]))) % 2000) - 1000) / 1000.0
                exit_px = sp["entry"] * (1 + sp["vol"] * f * 3.0)
            exit_px = round(float(exit_px), sp["dec"])
            win = (sp["dir"] == "up" and exit_px > sp["entry"]) or (sp["dir"] == "down" and exit_px < sp["entry"])
            res = "win" if win else "loss"
            self.sigResult.emit(json.dumps({"asset": sp["asset"], "tf": sp["tf"], "dir": sp["dir"], "result": res}))
            self._log("ok" if win else "err",
                      ("✅ WIN" if win else "❌ LOSS") + f" — {sp['asset']} ({sp['tf']}) {sp['entry']} → {exit_px}")
            self._tg_result(sp, win, exit_px)
        if len(still) != len(self._sigpend):
            # settled signals left the live list — the Signals page updates its cards
            self.liveSigChanged.emit()
        self._sigpend = still

    def _tg_result(self, sp, win, exit_px):
        """Bot result message — styled like the designed signal card.
        The chat ID comes from the indicator itself (user request) — fallback is the app setting.
        The PAGE records the finished signal in its saved History tab when it receives the
        sigResult emission (owner order v3.0.49) — here only the Telegram send remains:
        when the bot is STOPPED (user request) nothing is sent either."""
        try:
            cfg = _read_json(CFG_FILE, {})
            token = cfg.get("token", "")
            chats = str(sp.get("chats") or "") or cfg.get("chats", "")
            if not (token and chats):
                return
            if not self._bot_on():
                return
            dirl = "▲ BUY" if sp["dir"] == "up" else "▼ SELL"
            text = (("✅ WIN" if win else "❌ LOSS") + f" | {sp['asset']} ({sp['tf']})\n"
                    + f"{dirl} @ {sp['entry']} → {exit_px}\n📊 {sp['label']}")
            threading.Thread(target=lambda: self._tg_try(token, chats, text), daemon=True).start()
        except Exception:
            pass

    def _tg_try(self, token, chats, text):
        try:
            _tg_send(token, chats, text)
        except Exception as e:
            self._log("err", f"Telegram result: {str(e)[:90]}")

    @Slot()
    def stop_all(self):
        """Shutdown guard (user request: no more crashes): stop every internal timer so no
        callback can fire while the QML engine and Chromium are being shut down."""
        self._closing = True
        try:
            BRIDGE.app_shutdown()        # الجسر: أوقف بولر الشموع بلطف (السرفر كما هو)
        except Exception:
            pass
        for _t in ("_timer", "_paidT", "_paidW", "_flush_timer", "_indT"):
            try:
                o = getattr(self, _t, None)
                if o is not None:
                    o.stop()
            except Exception:
                pass

    @Slot()
    def refreshPy(self):
        self._compute_py()

    # ---------- Bot start/stop switch (user request) ----------
    def _bot_on(self):
        """Bot running state (user request): a start/stop switch on the Telegram bot page.
        Running (default) → everything is sent exactly as before; STOPPED → nothing goes
        to Telegram at all: signals, WIN/LOSS results, script screenshots and composed
        images all hold. The explicit Test button still works — it is the user's own
        diagnostic action on the bot page."""
        try:
            return bool(_read_json(CFG_FILE, {}).get("botOn", True))
        except Exception:
            return True

    @Slot(bool)
    def setBotOn(self, on):
        """Start/stop the Telegram bot from the bot page — persisted in config.json."""
        try:
            cfg = _read_json(CFG_FILE, {})
            cfg["botOn"] = bool(on)
            _write_json(CFG_FILE, cfg)
            self._log("ok" if on else "info",
                      "Bot started — signals, results, screenshots and images will be sent" if on
                      else "Bot stopped — nothing will be sent to Telegram until you start it again")
        except Exception as e:
            self._log("err", str(e))

    @Slot(str)
    def stopPy(self, fid):
        self._py_mods.pop(fid, None)

    @Slot(str)
    def chartShot(self, dataUrl):
        """The chart sent a screenshot (data:image/png;base64,....)."""
        try:
            b64 = dataUrl.split(",", 1)[1]
            png = base64.b64decode(b64)
            path = os.path.join(SHOTS_DIR, "shot_" + datetime.now().strftime("%Y%m%d_%H%M%S") + ".png")
            with open(path, "wb") as fh:
                fh.write(png)
            self.shotSaved.emit(True, path)
            if self._pending:
                pend, self._pending = self._pending, None
                self._deliver(pend, png)
        except Exception as e:
            self._pending = None
            self._log("err", f"screenshot: {e}")
            if self._pending:
                pend, self._pending = self._pending, None
                self._deliver(pend, None)

    @Slot(str)
    def scriptShot(self, arg):
        """A script captured a chart screenshot and asked for Telegram delivery (user request).
        The page clamps the capture region to the chart canvas — only chart pixels can ever
        reach this slot: no app window, no desktop, no full screen. The image goes ONLY to the
        Telegram chats named by the script (fallback: the bot settings chat) — nowhere else.
        BSE Layer 2: the request is validated here (security hold, payload size, rate limit)
        before any network path is touched; violations are audited."""
        try:
            if BSE_STATE["hold"]:
                self._log("err", "BSE: security hold — script sends are stopped (restart the app)")
                return
            if len(str(arg)) > BSE_MAX["bridge_msg"] * 4:
                _bse_violation("scriptshot-size", "meta too large")
                return
            o = json.loads(arg)
            img = str(o.get("img") or "")
            if "," in img:
                img = img.split(",", 1)[1]
            png = base64.b64decode(img)
            if len(png) > BSE_MAX["scriptshot_png"]:
                _bse_violation("scriptshot-size", "png over cap")
                self._log("err", "BSE: screenshot rejected — image over the size cap")
                return
            if not BSE_RATE.allow("scriptshot", *BSE_LIMITS["scriptshot"]):
                _bse_violation("scriptshot-rate", "screenshot limit exceeded")
                self._log("err", "BSE: screenshot limit exceeded — too many per minute")
                return
            # Bot stopped (user request): script screenshots hold like every other send
            if not self._bot_on():
                self._log("info", "Bot stopped — screenshot not sent (press Start on the Telegram page)")
                return
            caption = str(o.get("caption") or "").strip() or "Chart screenshot"
            cfg = _read_json(CFG_FILE, {})
            chats = str(o.get("chats") or "").strip() or cfg.get("chats", "")
            token = cfg.get("token", "")
            if not token or not chats:
                self._log("err", "screenshot → Telegram: " + ("telegram not configured" if not token
                           else "no chat id — set chats in Indicators.shot({chats: '...'})"))
                return
            n, errs = _tg_send(token, chats, caption, png)
            self._log("ok", f"Screenshot → Telegram {n} chat(s)" + ("; " + "; ".join(errs) if errs else ""))
        except Exception as e:
            self._log("err", f"screenshot: {str(e)[:120]}")

    @Slot(str, result=str)
    def composeImage(self, arg):
        """A script asked the PYTHON engine to compose an image from its drawing commands
        (owner request) and send it as ONE Telegram message — the caption rides ON the photo.
        The chart library is never involved: _compose_png renders the closed, safe command set
        with Qt/QPainter (no files, no network, no screen access — the pixels are exactly what
        the commands draw) and the picture goes ONLY to the script chats (fallback: the bot
        settings chat). Nothing is written to disk.
        BSE Layer 2: spec size cap + rate limit + security hold are checked before anything
        renders or leaves the machine."""
        try:
            if BSE_STATE["hold"]:
                self._log("err", "BSE: security hold — script sends are stopped (restart the app)")
                return json.dumps({"ok": False, "error": "BSE security hold"})
            if len(str(arg)) > BSE_MAX["composepy"]:
                _bse_violation("composepy-size", "spec too large")
                return json.dumps({"ok": False, "error": "spec over the size cap"})
            if not BSE_RATE.allow("composepy", *BSE_LIMITS["composepy"]):
                _bse_violation("composepy-rate", "compose limit exceeded")
                return json.dumps({"ok": False, "error": "compose limit exceeded"})
            spec = json.loads(arg)
            if not isinstance(spec, dict):
                return json.dumps({"ok": False, "error": "bad spec"})
        except Exception as e:
            return json.dumps({"ok": False, "error": str(e)[:80]})
        try:
            png = _compose_png(spec)
        except Exception as e:
            return json.dumps({"ok": False, "error": str(e)[:80]})
        if not png:
            return json.dumps({"ok": False, "error": "render failed"})
        # Bot stopped (user request): composed images hold like every other send
        if not self._bot_on():
            return json.dumps({"ok": False, "error": "bot is stopped — press Start on the Telegram page"})
        caption = str(spec.get("caption") or "").strip() or "Chart screenshot"
        cfg = _read_json(CFG_FILE, {})
        chats = str(spec.get("chats") or "").strip() or cfg.get("chats", "")
        token = cfg.get("token", "")
        if not token or not chats:
            return json.dumps({"ok": False, "error": "telegram not configured" if not token else
                               "no chat id — set chats in Indicators.composePy({chats: '...'})"})
        def run():
            try:
                n, errs = _tg_send(token, chats, caption, png)
                self._log("ok", f"Composed image → Telegram {n} chat(s)" + ("; " + "; ".join(errs) if errs else ""))
            except Exception as e:
                self._log("err", f"composePy send: {str(e)[:120]}")
        threading.Thread(target=run, daemon=True).start()
        return json.dumps({"ok": True})

    @Slot()
    def requestShot(self):
        """Screenshot button (without sending)."""
        self._pending = None
        self.needShot.emit()

    needShot = Signal()
    tgDelivered = Signal(str, bool, str)   # a finished Telegram send (entry-json, ok, info)
    paidFetched = Signal(str)              # paid-poll worker results (json list of [rid, text])

    def _send_signal(self, fid, label, dir_, price, when, asset=None, chats=""):
        cfg = _read_json(CFG_FILE, {})
        token = cfg.get("token", "")
        # The chat ID comes from the indicator itself (user request) — fallback is the old app setting
        chats = str(chats or "").strip() or cfg.get("chats", "")
        asset = str(asset or self._asset or "")
        tmpl = TG_TMPL_DEFAULT
        dirl = "▲ BUY" if dir_ == "up" else "▼ SELL"
        try:
            text = tmpl.format(asset=asset, tf=self._tf, dir=dirl, price=price,
                               time=when, indicator=label)
        except Exception:
            text = f"{dirl} {asset} @ {price}"
        attach = bool(cfg.get("attach", True))
        entry = {"time": when, "asset": asset, "tf": self._tf, "indicator": label,
                 "dir": dir_, "price": price, "sent": None, "info": ""}
        rec = {"entry": entry, "token": token, "chats": chats, "text": text, "attach": attach}
        self._log("info", f"⚡ {label}: {dir_.upper()} {asset} @ {price}")
        if token and chats and not self._bot_on():
            # Bot stopped (owner request): NOTHING is sent to Telegram. The finished
            # signal still reaches the saved History tab of the signals card through the
            # sigResult emission (owner order v3.0.49) — the live card on the Signals page
            # is where a signal appears while it runs; the log line above is the trace.
            pass
        elif token and chats:
            self._pending = rec
            self.needShot.emit()
            # Fallback if no screenshot arrives within 4 seconds — send text only
            def _fallback():
                if self._pending is rec:
                    self._pending = None
                    self._deliver(rec, None)
            QTimer.singleShot(4000, _fallback)
        else:
            # The finished signal still reaches the saved History tab through the sigResult
            # emission (owner order v3.0.49) — the log below is the trace on this page.
            self._log("err", ("no chat id — set chats in the indicator signal()" if token
                              else "telegram not configured"))

    def _deliver(self, rec, png):
        """Telegram delivery. The network send used to run here on the GUI thread and froze
        the whole window for up to 20 s per chat on a slow network (one of the reasons the
        app looked like it "died suddenly" — user request). It now runs in a daemon thread
        and the result comes back through the tgDelivered signal, which Qt auto-queues
        into the main thread — the GUI never blocks on a network socket again."""
        if self._closing:
            return
        entry = rec["entry"]

        def _send():
            ok, info = False, ""
            try:
                n, errs = _tg_send(rec["token"], rec["chats"], rec["text"],
                                   png if rec["attach"] else None)
                ok, info = True, f"{n} chat(s)" + ("; " + "; ".join(errs) if errs else "")
            except Exception as e:
                info = str(e)[:120]
            try:
                self.tgDelivered.emit(json.dumps(entry), ok, info)
            except Exception:
                pass
        threading.Thread(target=_send, daemon=True).start()

    @Slot(str, bool, str)
    def _tg_delivered(self, entry_json, ok, info):
        """Main-thread landing of a finished Telegram send — history bookkeeping only."""
        if self._closing:
            return
        try:
            entry = json.loads(entry_json)
        except Exception:
            return
        # v3.0.42 (أمر المالك: «سجل اشارات تلجرام في صفحة بوت تلجرام ضف ايقونة
        # لحذف السجل»): السجل يسجل فقط ما وصل فعليًا لمسار الإرسال إلى تلجرام —
        # صف واحد لكل إشارة لحظة اكتمال إرسالها بحالتها النهائية (أُرسلت ✓ /
        # فشلت ✗ مع السبب). الإشارات التي لم تُرسل أصلًا (البوت متوقف أو بلا
        # توكن/رقم دردشة) تبقى بلا تسجيل كما هو — طلب المالك السابق الثابت.
        # محفوظ في signals.json حتى 500 صف ويبقى بعد إغلاق التطبيق، والقائمة في
        # صفحة البوت تُحدَّث لحظيًا عبر histChanged.
        entry["sent"] = bool(ok)
        entry["info"] = info
        try:
            self._hist.append(entry)
            if len(self._hist) > 500:
                self._hist = self._hist[-500:]
            _write_json(os.path.join(CFG_DIR, "signals.json"), self._hist)
            self.histChanged.emit()
        except Exception:
            pass
        if ok:
            self._log("ok", f"Telegram → {info} ({entry.get('asset', '')} {entry.get('dir', '')})")
        else:
            self._log("err", f"Telegram: {info}")

    @Slot()
    def clearHist(self):
        """v3.0.42 (أمر المالك): أيقونة حذف سجل الإشارات في صفحة بوت تلجرام —
        تمحو القائمة بالكامل (الذاكرة + ملف signals.json) فورًا."""
        self._hist = []
        try:
            _write_json(os.path.join(CFG_DIR, "signals.json"), [])
        except Exception:
            pass
        self.histChanged.emit()
        self._log("ok", "Telegram signals log cleared")

    @Slot(str, str, str)
    def sendTest(self, token, chats, text):
        def run():
            try:
                n, errs = _tg_send(token, chats, text)
                self.testResult.emit(True, f"{n} chat(s)" + ("; " + "; ".join(errs) if errs else ""))
            except Exception as e:
                self.testResult.emit(False, str(e)[:90])
        threading.Thread(target=run, daemon=True).start()

    @Slot(str, str, str)
    def saveTg(self, token, chats, tmpl_attach_json):
        try:
            d = json.loads(tmpl_attach_json)
            cfg = _read_json(CFG_FILE, {})
            cfg.update({"token": token, "chats": chats,
                        "tmpl": d.get("tmpl", ""), "attach": bool(d.get("attach", True))})
            _write_json(CFG_FILE, cfg)
            self._log("ok", "Telegram settings saved")
        except Exception as e:
            self._log("err", str(e))

    @Slot(result=str)
    def loadTg(self):
        cfg = _read_json(CFG_FILE, {})
        return json.dumps({"token": cfg.get("token", ""), "chats": cfg.get("chats", ""),
                           "tmpl": cfg.get("tmpl") or TG_TMPL_DEFAULT,
                           "attach": bool(cfg.get("attach", True)),
                           "botOn": bool(cfg.get("botOn", True))})

    # ---------- v3.0.30 (أمر المالك): عدة بوتات محفوظة مرقّمة (بوت 1، بوت 2 …) مع زر
    # تفعيل بجوار الحذف — وبوت واحد فقط يعمل في نفس الوقت: تفعيل بوت يوقف السابق.
    # التوكن النشط يُكتب في cfg["token"] نفسها فلا يتغير أي مسار إرسال قديم حرفيًا ----------
    @staticmethod
    def _tg_bots(cfg):
        """قائمة البوتات المحفوظة [{"tok": ..., "act": bool}, ...] — مع ترحيل الإعداد
        القديم (توكن واحد في cfg["token"]) إلى بوت 1 مفعّل مرة واحدة عند أول قراءة."""
        bots = cfg.get("bots")
        if not isinstance(bots, list):
            legacy = str(cfg.get("token", "") or "").strip()
            if legacy:
                bots = [{"tok": legacy, "act": True}]   # الإعداد القديم = البوت الأول مفعّل كما كان
            else:
                bots = []
        out = []
        for b in bots:
            if isinstance(b, dict) and str(b.get("tok", "") or "").strip():
                out.append({"tok": str(b.get("tok")).strip(), "act": bool(b.get("act", False))})
        return out

    @Slot(str, str, result=bool)
    def saveTgBot(self, token, meta_json=""):
        """حفظ بوت جديد في القائمة المرقّمة — البطاقة تمحو الخانة بعد النداء
        (أمر المالك: «عندما نضغط حفض يجب ان يمحى توكن من خانة الادخال لكي يبقا
        محفوظ في الاسفل ولكي نستطيع اضافة بوت اخر»). التوكن نفسه لا يتكرر في
        القائمة، والحفظ لا يغيّر البوت المفعّل — التفعيل زر صريح مستقل.
        meta_json يحمل إعداد الإرفاق (attach) كما في الحفظ القديم حرفيًا.
        يُرجع true إن أُضيف بوتًا جديدًا وfalse إن كان محفوظًا من قبل أو فارغًا."""
        try:
            tok = str(token or "").strip()
            if not tok:
                return False
            cfg = _read_json(CFG_FILE, {})
            try:
                meta = json.loads(meta_json or "{}")
            except Exception:
                meta = {}
            if "attach" in meta:
                cfg["attach"] = bool(meta.get("attach", True))   # كما في saveTg القديم حرفيًا
            bots = self._tg_bots(cfg)
            if any(b["tok"] == tok for b in bots):
                self._log("info", "This bot is already saved")
                _write_json(CFG_FILE, cfg)
                return False
            bots.append({"tok": tok, "act": False})
            cfg["bots"] = bots
            _write_json(CFG_FILE, cfg)
            self._log("ok", "Bot saved — %d bot(s) in the list" % len(bots))
            return True
        except Exception as e:
            self._log("err", str(e))
            return False

    @Slot(int)
    def activateTgBot(self, idx):
        """تفعيل البوت رقم idx (بوت 1، بوت 2 …) — بوت واحد فقط يعمل في نفس الوقت:
        تفعيل هذا البوت يوقف البوت المفعّل السابق تلقائيًا. توكن البوت المفعّل
        يُكتب في cfg["token"] نفسها فتستخدمه كل مسارات الإرسال القديمة كما هي."""
        try:
            cfg = _read_json(CFG_FILE, {})
            bots = self._tg_bots(cfg)
            if idx < 0 or idx >= len(bots):
                return
            for i, b in enumerate(bots):
                b["act"] = (i == idx)
            cfg["bots"] = bots
            cfg["token"] = bots[idx]["tok"]
            _write_json(CFG_FILE, cfg)
            self._log("ok", "Bot %d activated — the previous bot stopped" % (idx + 1))
        except Exception as e:
            self._log("err", str(e))

    @Slot(int)
    def deleteTgBot(self, idx):
        """حذف البوت رقم idx من القائمة — إن كان مفعّلًا ولا يوجد بوت مفعّل آخر
        يصبح cfg["token"] فارغًا (لا يُرسل شيء حتى يفعّل المستخدم بوتًا)."""
        try:
            cfg = _read_json(CFG_FILE, {})
            bots = self._tg_bots(cfg)
            if idx < 0 or idx >= len(bots):
                return
            removed = bots.pop(idx)
            cfg["bots"] = bots
            if removed.get("act") and not any(b["act"] for b in bots):
                cfg["token"] = ""
            _write_json(CFG_FILE, cfg)
            self._log("ok", "Bot deleted")
        except Exception as e:
            self._log("err", str(e))

    @Slot(result=str)
    def loadTgBots(self):
        """قائمة البوتات المحفوظة للصفحة — بالترتيب: بوت 1، بوت 2 … مع علم التفعيل."""
        try:
            cfg = _read_json(CFG_FILE, {})
            return json.dumps({"bots": self._tg_bots(cfg)})
        except Exception:
            return json.dumps({"bots": []})

    # ---------- BADI: encrypted indicators (the key stays inside the app only) ----------
    badiFpChanged = Signal()

    def _get_badi_fp(self):
        try:
            return BADI.fingerprint()
        except Exception:
            return "—"

    badiFp = Property(str, _get_badi_fp, notify=badiFpChanged)

    # ---------- Chart appearance ----------
    # Removed (user request): the chart always wears the app theme colors now — background, grid,
    # candles, axes, crosshair and drawings are derived from the app theme in the page
    # (__badiThemeKit.chartTheme) and re-applied live on every dark/light switch. Nothing
    # chart-color related is stored in config.json anymore (an old "chart_theme" key is ignored
    # and dropped on the next save), and there is no separate chart palette to diverge.

    def _badi_sandbox_check(self, code):
        """Check encrypted indicator code before loading — a static scan for forbidden patterns (files/
        network/internal app parts) then an isolated QuickJS run.
        Returns an error message, or None when accepted."""
        # 1) Static scan: the files the app creates, its services and internal engine parts
        #    must never be touched by an encrypted indicator — any touch rejects the whole file (user request)
        try:
            if BADI_BANNED_RE.search(str(code or "")):
                return BADI_MSGS[self._lang]["blocked"]
        except Exception:
            pass
        # 2) Runtime check inside QuickJS — no filesystem and no network there at all
        if not _HAS_QJS:
            return None          # QuickJS unavailable — the indicator loads and any error shows in the editor console
        try:
            ctx = _quickjs.Context()
            # Strict isolation (user request): no files and no network at all in QuickJS + strict limits
            # on memory and time — any dangerous code stops inside the sandbox and never touches the device.
            try:
                ctx.set_memory_limit(64 * 1024 * 1024)     # 64MB
            except Exception:
                pass
            try:
                ctx.set_time_limit(6)                      # seconds — stops infinite loops
            except Exception:
                pass
            ctx.eval(_QJS_STUBS)
            harness = (
                "var __CODE = " + json.dumps(code) + ";\n"
                + "var __OUT = (function () {\n"
                + "  try {\n"
                + "    var __f = new Function('Indicators', 'THEME', 'log', '\"use strict\";\\n' + __CODE);\n"
                + "    var __d = __f(Indicators, {}, function () {});\n"
                + "    if (!__d || typeof __d !== 'object' || typeof __d.calculate !== 'function') return 'E:noc';\n"
                + "    var __c = [];\n"
                + "    for (var i = 0; i < 90; i++) {\n"
                + "      var t = 1700000000 + i * 60, o = 1 + i * 0.01, cl = 1.05 + i * 0.01;\n"
                + "      __c.push({ time: t, t: t, open: o, o: o, high: o + 0.05, h: o + 0.05,\n"
                + "                 low: o - 0.04, l: o - 0.04, close: cl, c: cl, volume: 1000, v: 1000 });\n"
                + "    }\n"
                + "    var __v = __d.calculate(__c, __d.settings || {});\n"
                + "    if (typeof __d.signal === 'function') __d.signal(__c, __v, __d.settings || {});\n"
                + "    return 'OK';\n"
                + "  } catch (e) { return 'E:' + (e && e.message ? e.message : String(e)); }\n"
                + "})();\n"
                + "__OUT"
            )
            out = str(ctx.eval(harness)).strip()
        except Exception:
            return None          # The QuickJS environment itself failed — never block the import because of it
        if out == "OK":
            return None
        if out == "E:noc":
            return BADI_MSGS[self._lang]["noc"]
        msg = out[2:] if out.startswith("E:") else out
        low = msg.lower()
        # Helper missing only in the sandbox (the chart provides the full window.Indicators) → accepted
        if ("indicators" in low or "theme" in low or "not a function" in low
                or "undefined" in low):
            return None
        return BADI_MSGS[self._lang]["run"] + ": " + msg[:140]

    @Slot(str, str, str, str, str, str, result=str)
    def badiExport(self, code, file_name, kind="indicator", license_ids="", paid_server="", paid_id=""):
        """Encrypt the indicator and write a .badi file next to its original in the BadiCharts folder
        (like MetaTrader: .mq5/.ex5 side by side) — result is JSON.
        The original file is written first if not on disk yet, then the encrypted file beside it.
        license_ids: extra allowed USER IDs — separated by commas/spaces (optional fallback);
        the main source is the script itself: the BADI LICENSED USERS line (see _parse_script_licenses).
        Empty = works for everyone. The encrypted file runs only on a device matching its ID (user request).
        The key is never written into the file — licensing travels inside the encrypted envelope itself."""
        lang = self._lang
        try:
            _ensure_badi_dirs()
            kind = self._norm_kind(kind)
            if kind == "badi":
                return json.dumps({"ok": False, "error": BADI_MSGS[lang]["notbadi"]})
            # Buyer licensing lives in the script now (user request): the BADI LICENSED USERS line —
            # unlimited buyers, the seller edits it freely. Manual license_ids stay as a fallback.
            ids = _parse_script_licenses(code)
            manual = self._parse_license_ids(license_ids)
            if manual is None:
                return json.dumps({"ok": False, "error": BADI_MSGS[lang]["uidbad"]})
            for tok in manual:
                if tok not in ids:
                    ids.append(tok)
            fname = _safe_file_name(file_name) or "Indicator.js"
            base = fname.rsplit(".", 1)[0]
            src = {"fileName": fname, "kind": kind, "code": code or ""}
            src_path = self._write_entry_to_disk(src)   # Save the source first (like saving .mq5 before compiling)
            # Encrypted envelope: the code + the licensed ID list — the key stays completely outside the file
            env = {"t": "badi-ind", "name": base, "license": ids,
                   "created": int(time.time()), "code": code or ""}
            # Paid indicator (user request): the developer server + the indicator ID on it — both are embedded
            # inside the encrypted envelope itself so no script can change them; control later comes from the server only
            if str(paid_server or "").strip() or str(paid_id or "").strip():
                pm = _norm_paid_manifest({"id": paid_id, "server": paid_server})
                if not pm:
                    return json.dumps({"ok": False, "error": BADI_MSGS[lang]["paidbad"]})
                env["paid"] = pm
            blob = BADI.encrypt(json.dumps(env, ensure_ascii=False))
            d = _disk_dir_for(kind)
            path = os.path.join(d, base + ".badi")
            with open(path, "wb") as fh:
                fh.write(blob)
            self.syncDiskFiles()        # Inserts the encrypted file into the list next to its original immediately
            return json.dumps({"ok": True, "path": path, "src": src_path or ""})
        except BADIError as e:
            return json.dumps({"ok": False, "error": BADI_MSGS[lang].get(str(e), str(e))})
        except Exception as e:
            return json.dumps({"ok": False, "error": str(e)[:120]})

    @staticmethod
    def _parse_license_ids(raw):
        """Buyer ID list from comma/space-separated text — None when the format is wrong."""
        ids, seen = [], set()
        for tok in re.split(r"[,;\s]+", str(raw or "")):
            tok = tok.strip().upper()
            if not tok:
                continue
            if not BADI_UID_RE.match(tok):
                return None
            if tok not in seen:
                seen.add(tok)
                ids.append(tok)
        return ids

    @Slot(str, result=str)
    def badiScriptLicenses(self, code):
        """The buyer USER IDs declared in the indicator script (the BADI LICENSED USERS line) —
        the encrypt dialog shows them so the seller confirms exactly who will be embedded."""
        return json.dumps({"ok": True, "ids": _parse_script_licenses(code)})

    @Slot(str, result=str)
    def badiOpenName(self, name):
        """Open an encrypted indicator from the BadiCharts list by clicking it: decrypt in memory
        with the app key + QuickJS check — result is JSON (code ready to add to the editor)."""
        lang = self._lang
        try:
            nm = _safe_file_name(name)
            ent = next((f for f in self._files
                        if self._norm_kind(f.get("kind")) == "badi"
                        and _safe_file_name(f.get("fileName")).lower() == nm.lower()), None)
            p = (ent or {}).get("path") or os.path.join(BADI_IND_DIR, nm)
            if not os.path.isfile(p):
                p = os.path.join(BADI_TOOL_DIR, nm)
            if not p or not os.path.isfile(p):
                return json.dumps({"ok": False, "error": BADI_MSGS[lang]["short"]})
            with open(p, "rb") as fh:
                blob = fh.read()
            plain = BADI.decrypt(blob)
            code, lic, pmanifest, pname = _badi_payload(plain)
            # Licensing gate (user request): the embedded buyer ID must match this device ID
            if _badi_license_denied(lic):
                return json.dumps({"ok": False, "error": BADI_MSGS[lang]["license"] + _get_user_id()})
            # Paid-indicators gate (user request): register the record in the protected database
            # + block opening entirely when the subscription expired or the developer disabled the indicator from his server
            if pmanifest:
                try:
                    paid_register(pmanifest, pname)
                    deny = paid_open_denied(str(pmanifest.get("id") or ""), lang)
                    if deny:
                        return json.dumps({"ok": False, "error": deny})
                except Exception:
                    pass
            warn = self._badi_sandbox_check(code)
            if warn:
                return json.dumps({"ok": False, "error": warn})
            base = re.sub(r"\.badi$", "", os.path.basename(p), flags=re.I).strip() or "indicator"
            fid = "badi" + format(int(time.time() * 1000) & 0xFFFFFFFFFFFF, "x")
            return json.dumps({"ok": True, "id": fid, "fileName": base + ".js", "code": code})
        except BADIError as e:
            return json.dumps({"ok": False, "error": BADI_MSGS[lang].get(str(e), str(e))})
        except Exception as e:
            return json.dumps({"ok": False, "error": str(e)[:120]})

    @Slot(str, result=str)
    def badiImport(self, url):
        """Import a .badi file: decrypt with the app key in memory + QuickJS check — result is JSON."""
        lang = self._lang
        try:
            p = url
            if p.startswith("file://"):
                try:
                    p = QUrl(p).toLocalFile()
                except Exception:
                    p = urllib.parse.unquote(urllib.parse.urlparse(p).path)
            if not p or not os.path.isfile(p):
                return json.dumps({"ok": False, "error": BADI_MSGS[lang]["short"]})
            with open(p, "rb") as fh:
                blob = fh.read()
            plain = BADI.decrypt(blob)
            code, lic, pmanifest, pname = _badi_payload(plain)
            # Licensing gate (user request): the embedded buyer ID must match this device ID
            if _badi_license_denied(lic):
                return json.dumps({"ok": False, "error": BADI_MSGS[lang]["license"] + _get_user_id()})
            # Paid-indicators gate (user request): register the record in the protected database
            # + block opening entirely when the subscription expired or the developer disabled the indicator from his server
            if pmanifest:
                try:
                    paid_register(pmanifest, pname)
                    deny = paid_open_denied(str(pmanifest.get("id") or ""), lang)
                    if deny:
                        return json.dumps({"ok": False, "error": deny})
                except Exception:
                    pass
            warn = self._badi_sandbox_check(code)
            if warn:
                return json.dumps({"ok": False, "error": warn})
            base = re.sub(r"\.badi$", "", os.path.basename(p), flags=re.I).strip() or "indicator"
            fid = "badi" + format(int(time.time() * 1000) & 0xFFFFFFFFFFFF, "x")
            return json.dumps({"ok": True, "id": fid, "fileName": base + ".js", "code": code})
        except BADIError as e:
            return json.dumps({"ok": False, "error": BADI_MSGS[lang].get(str(e), str(e))})
        except Exception as e:
            return json.dumps({"ok": False, "error": str(e)[:120]})

