    # ---------- Paid indicators: notification card + developer control channel (user request) ----------
    @Property(list, notify=notifChanged)
    def notifs(self):
        """Notification list of the small card — no ready-made notifications: the developer sends them from his server."""
        return self._notifs

    @Property(int, notify=notifChanged)
    def notifsUnread(self):
        """Unread count — for the red badge on the notifications button."""
        return sum(1 for n in self._notifs if not n.get("read"))

    @Slot()
    def notifsMarkAll(self):
        """Opening the card marks everything read, so the red badge disappears."""
        ch = False
        for n in self._notifs:
            if not n.get("read"):
                n["read"] = True
                ch = True
        if ch:
            self.notifChanged.emit()

    @Slot()
    def notifsClear(self):
        """Clear all notifications from the card."""
        if self._notifs:
            self._notifs = []
            self.notifChanged.emit()

    def _notif_push(self, text, ind=""):
        """New notification: text only, ≤300 chars — no HTML and no file links (user request: hardened protection)."""
        t = re.sub(r"[\x00-\x1f]", " ", str(text or "")).strip()[:300]
        if not t:
            return
        self._notifs.insert(0, {"t": t, "at": int(time.time()), "read": False,
                                "ind": str(ind or "")[:60]})
        if len(self._notifs) > 50:
            del self._notifs[50:]
        self.notifChanged.emit()

    def _paid_poll(self):
        """Developer control channel through his server (user request): a small GET poll per paid indicator,
        JSON response only, ≤16KB, allow-listed commands only — no file upload or download ever,
        and any response containing files/base64 → full rejection + a 10-minute server ban.
        The HTTP fetch runs in a daemon worker — never on the GUI thread (it used to freeze
        the window for up to 8 s per server and could get the app killed — user request)."""
        if self._closing or self._paidBusy:
            return
        try:
            recs = paid_records()
            today = _today_iso()
            now = time.time()
            jobs = []
            for rid, rec in list(recs.items()):
                srv = str(rec.get("server") or "")
                if not srv or now < self._paid_block.get(rid, 0):
                    continue
                u = urllib.parse.urlparse(srv)
                # BSE Network Broker: HTTPS only (owner policy — "HTTPS for approved services"),
                # the declared host is the ONLY allowed host for this record, no redirects,
                # public-IP validation after DNS inside bse_open
                if u.scheme != "https" or not u.netloc:
                    if u.scheme or u.netloc:
                        _bse_audit("paid-skip", "non-https developer server — record skipped")
                    continue
                try:
                    left = paid_days_left(rec, today)
                    q = urllib.parse.urlencode({
                        "ind": rid, "dev": _get_user_id(),
                        "left": "" if left is None else max(0, int(left)),
                        "st": str(rec.get("status") or ""), "v": "1"})
                    if not BSE_RATE.allow("paid:" + rid[:32], *BSE_LIMITS["paid_poll"]):
                        continue
                except Exception:
                    continue
                jobs.append((rid, srv + ("&" if "?" in srv else "?") + q,
                             ((u.hostname or "").lower(),)))
        except Exception:
            return
        if not jobs:
            return
        self._paidBusy = True

        def _fetch():
            out = []
            for rid, url, host in jobs:
                try:
                    with bse_open(url, hosts=host,
                                  headers={"User-Agent": "BadiCharts-Paid/1"}, timeout=8) as resp:
                        raw = resp.read(16385)
                    if len(raw) > 16384:
                        out.append((rid, "@BAN@"))
                        continue
                    txt = raw.decode("utf-8", "ignore")
                    # Strict protection: any trace of files/base64 in the response → reject + ban the server
                    if re.search(r"base64|data:|file://|content-disposition|multipart", txt, re.I):
                        out.append((rid, "@BAN@"))
                        continue
                    out.append((rid, txt))
                except Exception:
                    continue   # Server unavailable — no user annoyance
            try:
                self.paidFetched.emit(json.dumps(out))
            except Exception:
                pass
        threading.Thread(target=_fetch, daemon=True).start()

    @Slot(str)
    def _paid_fetched(self, js):
        """Main-thread landing of the paid-poll worker — parsing and applying only."""
        self._paidBusy = False
        if self._closing:
            return
        try:
            out = json.loads(js)
        except Exception:
            return
        for rid, txt in out:
            rid = str(rid)
            if txt == "@BAN@":
                self._paid_block[rid] = time.time() + 600
                continue
            try:
                data = json.loads(txt)
                if not isinstance(data, dict) or not isinstance(data.get("cmds"), list):
                    continue
                if len(data["cmds"]) > 20:
                    self._paid_block[rid] = time.time() + 600
                    continue
                rec = paid_records().get(rid)
                if rec:
                    self._paid_apply(rid, rec, data["cmds"])
            except Exception:
                continue

    def _paid_apply(self, rid, rec, cmds):
        """Execute the allow-listed commands decided by the database: enable/disable through the bridge + text notifications."""
        try:
            toggles, notes = paid_apply_commands(rid, rec, cmds)
            for nm, on in toggles:
                if nm:
                    self.paidCmd.emit(json.dumps({"name": nm, "on": bool(on)}))
            for nt in notes:
                self._notif_push(nt, rec.get("name") or rid)
        except Exception:
            pass

    def _paid_watch(self):
        """Monitor the subscription locally from the protected database (user request): a reminder before expiry
        by 7/3/1 days, and at expiry: a notification + the indicator stops until the developer renews it from his server."""
        try:
            today = _today_iso()
            for rid, rec in list(paid_records().items()):
                if not rec.get("expiry"):
                    continue
                left = paid_days_left(rec, today)
                if left is None:
                    continue
                name = str(rec.get("name") or rid)
                lv = -1 if left < 0 else (1 if left <= 1 else (3 if left <= 3 else (7 if left <= 7 else 30)))
                if lv < int(rec.get("warned", 99)):
                    rec["warned"] = lv
                    paid_save_rec(rec)
                    if lv == -1:
                        self._notif_push(self._paid_ntext("ended", name), name)
                        if rec.get("enabled"):
                            rec["enabled"] = False
                            paid_save_rec(rec)
                            self.paidCmd.emit(json.dumps({"name": name, "on": False}))
                    else:
                        self._notif_push(self._paid_ntext("soon", name, left), name)
        except Exception:
            pass

    @Slot(result=str)
    def openBadiDir(self):
        """Open the BadiCharts folder on disk (Indicators + Tools) — the user drops
        indicators and tools directly into it and the app recognizes them automatically (user request)."""
        try:
            _ensure_badi_dirs()
            QDesktopServices.openUrl(QUrl.fromLocalFile(BADI_DIR))
            return BADI_DIR
        except Exception:
            return ""

    # ═══ v3.0.38 (أمر المالك): زر تنزيل شموع العملة المفتوحة — جنب زر بوت
    # تلجرام في شريط الصفحة، بطاقة اختيار JSON/TXT/CSV تظهر للنوع، والملف
    # ينزل في مجلد التطبيق بين مجلد المؤشرات والأدوات (BadiCharts/Candles).
    # بلا أي لمس للسرفر ولا مسارات التحميل — القراءة من _candles المحلية فقط ═══
    @Slot(str, result=str)
    def saveCandlesFile(self, fmt):
        """Save the OPEN pair's candles (the chart data itself) into
        BadiCharts/Candles/<asset>_<tf>.<json|txt|csv> — returns the saved
        path, or "" when there is nothing to save / the write failed.

        • json : {asset, display, tf, tf_seconds, count, candles:[{time, open,
          high, low, close, volume}]} — time = Unix seconds (UTC)
        • txt  : a human-readable table — datetime (LOCAL time like the chart
          display) then open/high/low/close/volume
        • csv  : header time,datetime,open,high,low,close,volume — time = Unix
          seconds, datetime = LOCAL time

        Re-downloading overwrites the same file with the newest snapshot."""
        try:
            fmt_s = str(fmt or "").strip().lower()
            if fmt_s not in ("json", "txt", "csv"):
                fmt_s = "json"
            try:
                os.makedirs(BADI_CANDLE_DIR, exist_ok=True)
            except Exception:
                pass
            code = str(self._asset or "")
            try:
                code = str(BRIDGE._cur[0] or code)
            except Exception:
                pass
            tf = str(self._tf or "1m")
            tf_sec = int(APP_TFS.get(tf, 60))
            with _web_candle_lock:
                candles = list(self._candles or [])
            if not candles:
                self._log("err", f"[candles-save] no candles for {code} {tf} — nothing to save")
                return ""
            display = str(self._asset or code)
            safe = re.sub(r"[^A-Za-z0-9]+", "_", str(code or "asset")).strip("_") or "asset"
            path = os.path.join(BADI_CANDLE_DIR, f"{safe}_{tf}.{fmt_s}")
            rows = []
            for c in candles:
                try:
                    t = int(c.get("t") or 0)
                    rows.append({"time": t,
                                 "open": float(c.get("o") or 0.0),
                                 "high": float(c.get("h") or 0.0),
                                 "low": float(c.get("l") or 0.0),
                                 "close": float(c.get("c") or 0.0),
                                 "volume": float(c.get("v") or 0.0)})
                except Exception:
                    continue
            rows.sort(key=lambda r: r["time"])
            if fmt_s == "json":
                payload = {"asset": code, "display": display, "tf": tf,
                           "tf_seconds": tf_sec, "count": len(rows), "candles": rows}
                with open(path, "w", encoding="utf-8") as f:
                    json.dump(payload, f, ensure_ascii=False, indent=1)
            else:
                def _dt(t):
                    try:
                        return datetime.fromtimestamp(int(t)).strftime("%Y-%m-%d %H:%M:%S")
                    except Exception:
                        return ""
                if fmt_s == "csv":
                    with open(path, "w", encoding="utf-8", newline="") as f:
                        f.write("time,datetime,open,high,low,close,volume\n")
                        for r in rows:
                            f.write(f"{r['time']},{_dt(r['time'])},{r['open']},{r['high']},{r['low']},{r['close']},{r['volume']}\n")
                else:
                    with open(path, "w", encoding="utf-8") as f:
                        f.write(f"BadiCharts candles — {display} ({code}) | tf {tf} | {len(rows)} candles\n")
                        f.write("datetime (local)\topen\thigh\tlow\tclose\tvolume\n")
                        for r in rows:
                            f.write(f"{_dt(r['time'])}\t{r['open']}\t{r['high']}\t{r['low']}\t{r['close']}\t{r['volume']}\n")
            self._log("ok", f"[candles-save] {display} {tf} → {path} ({len(rows)} candles, {fmt_s.upper()})")
            return path
        except Exception as e:
            try:
                self._log("err", f"[candles-save] failed: {e}")
            except Exception:
                pass
            return ""

    # ---------- Icons and logo ----------
    @Slot(str, bool, result=str)
    def logo(self, name, dark):
        return logo_uri(name, dark)

    @Slot(str, str, result=str)
    def icon(self, name, color):
        return icon_uri(name, color)

    @Slot(bool, result=str)
    def mark(self, dark):
        """BadiCharts mark (the two candles only) — for the new login page."""
        p = LOGO_PAL[bool(dark)]
        svg = ('<svg xmlns="http://www.w3.org/2000/svg" viewBox="8 16 76 76">'
               + ICON_SVG.format(**p) + '</svg>')
        return "data:image/svg+xml;utf8," + urllib.parse.quote(svg)
